INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Babytiann/Piko/piko-frontend-standards', 'community', 'Babytiann', 'Piko', 'Babytiann/Piko', 'piko-frontend-standards', 0, 0, 54, '2026-03-08T01:57:15.588Z', '2026-03-08T02:13:21.048Z', 'd14dd2a1b3e189914858737a4c1470c306217631be2314906fdec15977baab18', '{"id":"Babytiann/Piko/piko-frontend-standards","name":"piko-frontend-standards","description":{"en":"piko-frontend-standards is a set of code standards for frontend development, benefiting developers by promoting code as documentation and page autonomy. It enables efficient development and maintenance of frontend applications.","zh":"Piko 前端标准是一套代码即文档的开发指南，旨在提高开发效率和代码质量","ja":"Piko フロントエンド標準はコード即文書の開発ガイドであり、開発効率とコード品質を向上させることを目的としています","ko":"Piko 프론트엔드 표준은 코드即문서의 개발 가이드로서 개발 효율성과 코드 품질을 향상시키는 것을 목표로 합니다","es":"piko-frontend-standards es un conjunto de normas para desarrolladores frontend que busca mejorar la calidad y mantenibilidad del código","fr":"piko-frontend-standards est un ensemble de normes pour les développeurs frontend qui vise à améliorer la qualité et la maintenabilité du code","de":"piko-frontend-standards ist ein Satz von Normen für Frontend-Entwickler, die darauf abzielen, die Qualität und Wartbarkeit des Codes zu verbessern","pt":"O Piko Frontend Standards é um conjunto de diretrizes para codificação frontend que visa melhorar a legibilidade e manutenção do código","ru":"Piko Фронтенд Стандарты - это набор руководств для frontend-кодирования, направленный на улучшение читаемости и обслуживания кода для ИИ Агентов","ar":"معايير پيكو フロントإند هي مجموعة من الإرشادات لبرمجة الفرونت إند التي تهدف إلى تحسين قابلية القراءة و الصيانة للكود لآلات الإي الأجنت"},"seo":{"title":{"en":"piko-frontend-standards: Code Standards Setup Guide | AI ...","zh":"Piko 前端标准：代码即文档的开发指南","ja":"Piko フロントエンド標準：コード即文書の開発ガイド","ko":"Piko 프론트엔드 표준: 코드即문서의 개발 가이드","es":"Guía de configuración de piko-frontend-standards para des...","fr":"Mise en place des normes piko-frontend-standards pour les...","de":"Einrichtungsleitfaden für piko-frontend-standards für Ent...","pt":"Piko Frontend Standards: Guia de Configuração de Código c...","ru":"Piko Фронтенд Стандарты: Настройка Код как Документации д...","ar":"معايير پيكو フロントإند: دليل إعداد كود كما وثيقة لآلات الإي ..."},"description":{"en":"Unlock efficient frontend development with piko-frontend-standards. Discover how to implement code as documentation, page autonomy, and more. Get started now!","zh":"了解 Piko 前端标准，掌握代码即文档、页面自治、单一职责等开发原则，提升开发效率","ja":"Piko フロントエンド標準を学び、コード即文書、ページオートノミー、単一責任などの開発原則をマスターして開発効率を向上させる","ko":"Piko 프론트엔드 표준을 배우고 코드即문서, 페이지 자율성, 단일 책임 등의 개발 원칙을 마스터하여 개발 효율성을 향상시키세요","es":"Aprende a implementar las normas piko-frontend-standards en tus proyectos de desarrollo frontend con nuestra guía paso a paso","fr":"Découvrez comment mettre en place les normes piko-frontend-standards dans vos projets de développement frontend avec notre guide étape par étape","de":"Erfahren Sie, wie Sie die piko-frontend-standards in Ihren Frontend-Projekten implementieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o Piko Frontend Standards para melhorar a legibilidade e manutenção do seu código com práticas recomendadas de codificação","ru":"Узнайте, как настроить Piko Фронтенд Стандарты для улучшения читаемости и обслуживания вашего кода с помощью лучших практик кодирования для ИИ Агентов","ar":"تعلم كيفية ضبط معايير پيكو フロントإند لتحسين قابلية القراءة و الصيانة للكود الخاص بك باستخدام أفضل الممارسات لآلات الإي الأجنت"},"definition":{"en":"piko-frontend-standards is a set of guidelines for writing clean, maintainable, and efficient frontend code, emphasizing code as documentation and single responsibility principles.","zh":"Piko 前端标准是一套前端开发的代码组织和开发原则","ja":"Piko フロントエンド標準はフロントエンド開発のコード組織と開発原則のセットです","ko":"Piko 프론트엔드 표준은 프론트엔드 개발의 코드 구성과 개발 원칙의 집합입니다","es":"piko-frontend-standards es un conjunto de reglas y principios para escribir código frontend de alta calidad","fr":"piko-frontend-standards est un ensemble de règles et de principes pour écrire du code frontend de haute qualité","de":"piko-frontend-standards ist ein Satz von Regeln und Prinzipien für das Schreiben von hochwertigem Frontend-Code","pt":"O Piko Frontend Standards é um conjunto de práticas recomendadas de codificação para frontend que prioriza a legibilidade e manutenção do código","ru":"Piko Фронтенд Стандарты - это набор лучших практик кодирования для frontend, который отдает приоритет читаемости и обслуживанию кода для ИИ Агентов","ar":"معايير پيكو フロントإند هي مجموعة من أفضل الممارسات لبرمجة الفرونت إند التي تؤكد على قابلية القراءة و الصيانة للكود لآلات الإي الأجنت"},"features":{"en":["Enforces code as documentation principle for self-explanatory code","Promotes page autonomy with self-contained components, hooks, and types","Implements single responsibility principle for functions and components","Supports composition over complexity with slot and hook combinations","Explicitly annotates return types and handles promises with await or void","Utilizes type systems as contracts between modules with discriminated unions"],"zh":["代码即文档：命名自解释，拒绝冗余注释","页面自治：每个页面是自包含单元，拥有自己的组件、钩子、类型和工具","单一职责：一个函数或组件只做一件事","组合优于复杂性：Slot 组合优于巨型组件，Hook 组合优于万能 Hook","显式优于隐式：所有返回类型显式标注，所有 Promise 要么 await 要么 void","类型作为契约：类型系统是模块间的契约，用判别联合而非松散可选字段"],"ja":["コード即文書：命名が自解釈的であり、冗長なコメントを拒否する","ページオートノミー：各ページは自己包含的な単位であり、独自のコンポーネント、フック、タイプ、ツールを持ちます","単一責任：関数またはコンポーネントは一つのことをのみ行う","組み合わせ優于複雑性：Slot 組み合わせが巨大なコンポーネントよりも優れており、Hook 組み合わせが万能な Hook よりも優れています","明示的優于暗示的：全ての戻り値の型が明示的に標注され、全ての Promise が await または void のいずれかである","型としての契約：型システムはモジュール間の契約であり、判別的結合によって疎結合なオプショナル フィールドではなく"],"ko":["코드即문서:命名이 자체적으로 설명적이며,冗長한 주석을 거부함","페이지 자율성:각 페이지는 자체 포함적인 단위로,独自의 컴포넌트, 훅, 타입, 툴을 가짐","단일 책임:함수 또는 컴포넌트는 하나의 일을のみ 수행함","조합優于 복잡성:Slot 조합이巨형 컴포넌트보다優れており, Hook 조합이万能한 Hook보다優れて 있음","명시적優于 암시적:모든 반환값의 유형이 명시적으로标注되고,모든 Promise가 await 또는 void의いずれか임","타입으로서의 契約:타입 시스템은 모듈 간의 契約であり,판별적 결합에 의한疎結合なオプショナル 필드가아님"],"es":["Code as Documentation para una mayor claridad","Page Autonomy para una mejor organización del código","Single Responsibility para una mayor simplicidad","Composition over Complexity para una mayor flexibilidad","Explicit over Implicit para una mayor seguridad","Type as Contract para una mayor robustez"],"fr":["Code as Documentation pour une plus grande clarté","Page Autonomy pour une meilleure organisation du code","Single Responsibility pour une plus grande simplicité","Composition over Complexity pour une plus grande flexibilité","Explicit over Implicit pour une plus grande sécurité","Type as Contract pour une plus grande robustesse"],"de":["Code as Documentation für eine bessere Klarheit","Page Autonomy für eine bessere Organisation des Codes","Single Responsibility für eine einfachere Wartung","Composition over Complexity für eine bessere Flexibilität","Explicit over Implicit für eine bessere Sicherheit","Type as Contract für eine bessere Robustheit"],"pt":["Codificação como documentação","Autonomia de página","Responsabilidade única","Composição sobre complexidade","Explicitação sobre implicitação","Tipos como contrato"],"ru":["Код как документация","Автономность страницы","Одиночная ответственность","Композиция над сложностью","Явное над неявным","Типы как контракт для ИИ Агентов"],"ar":["ترميز كما وثيقة","استقلالية الصفحة","مسؤولية واحدة","تركيبة على التعقيد","صريح على غير صريح","أنواع كما عقد لآلات الإي الأجنت"]},"keywords":{"en":["how to use piko-frontend-standards","piko-frontend-standards setup guide","piko-frontend-standards vs other frontend standards","piko-frontend-standards install","what is piko-frontend-standards","piko-frontend-standards best practices","piko-frontend-standards alternative","piko-frontend-standards documentation","piko-frontend-standards tutorial"],"zh":["Piko 前端标准","代码即文档","页面自治","单一职责","组合优于复杂性","显式优于隐式","类型作为契约","前端开发","代码组织","开发原则"],"ja":["Piko フロントエンド標準","コード即文書","ページオートノミー","単一責任","組み合わせ優于複雑性","明示的優于暗示的","型としての契約","フロントエンド開発","コード組織","開発原則"],"ko":["Piko 프론트엔드 표준","코드即문서","페이지 자율성","단일 책임","조합優于 복잡성","명시적優于 암시적","타입으로서의 契約","프론트엔드 개발","코드 구성","개발 원칙"],"es":["piko-frontend-standards","desarrollo frontend","normas de código","calidad del código","mantenibilidad del código","Code as Documentation","Page Autonomy","Single Responsibility","Composition over Complexity","Explicit over Implicit","Type as Contract"],"fr":["piko-frontend-standards","développement frontend","normes de code","qualité du code","maintenabilité du code","Code as Documentation","Page Autonomy","Single Responsibility","Composition over Complexity","Explicit over Implicit","Type as Contract"],"de":["piko-frontend-standards","Frontend-Entwicklung","Code-Normen","Code-Qualität","Code-Wartbarkeit","Code as Documentation","Page Autonomy","Single Responsibility","Composition over Complexity","Explicit over Implicit","Type as Contract"],"pt":["Piko Frontend Standards","codificação frontend","legibilidade de código","manutenção de código","práticas recomendadas de codificação","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Piko Фронтенд Стандарты","frontend-кодирование","читаемость кода","обслуживание кода","лучшие практики кодирования","разработка программного обеспечения","инструменты разработки для ИИ Агентов"],"ar":["معايير پيكو フロントإند","برمجة الفرونت إند","قابلية القراءة للكود","صيانة الكود","أفضل الممارسات لبرمجة","تطوير البرمجيات","أدوات التطوير لآلات الإي الأجنت"]}},"owner":"Babytiann","repo":"Piko","repoPath":"Babytiann/Piko","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.588Z","topics":[],"category":"community","skillMd":{"name":"piko-frontend-standards","description":"Enforces strict frontend code standards for the Piko Expo/React Native project. Covers page-autonomous architecture, component design, hook taxonomy, type safety, style system, API layer, error handling, and naming conventions. Use when writing, reviewing, or refactoring any frontend code. Automatically apply when creating new components, hooks, services, or types.","bodyPreview":"# Piko Frontend Code Standards\n\n> 严格派：代码即文档，每一行都有存在的理由。\n\n## Core Philosophy\n\n1. **Code as Documentation** — 代码即文档，命名自解释，拒绝冗余注释\n2. **Page Autonomy** — 每个页面是自包含单元，拥有自己的 components/hooks/types/consts/utils\n3. **Single Responsibility** — 一个函数/组件/hook 只做一件事\n4. **Composition over Complexity** — Slot 组合 > 巨型组件，Hook 组合 > 万能 Hook\n5. **Explicit over Implicit** — 所有返回类型显式标注，所有 Promise 要么 await 要么 void\n6. **Type as Contract** — 类型系统是模块间的契约，用判别联合而非松散可选字段\n7. **Fail Fast, Fail Loud** — 纯函数映射错误类型，不在 hook 里硬编码错误","body":"# Piko Frontend Code Standards\n\n> 严格派：代码即文档，每一行都有存在的理由。\n\n## Core Philosophy\n\n1. **Code as Documentation** — 代码即文档，命名自解释，拒绝冗余注释\n2. **Page Autonomy** — 每个页面是自包含单元，拥有自己的 components/hooks/types/consts/utils\n3. **Single Responsibility** — 一个函数/组件/hook 只做一件事\n4. **Composition over Complexity** — Slot 组合 > 巨型组件，Hook 组合 > 万能 Hook\n5. **Explicit over Implicit** — 所有返回类型显式标注，所有 Promise 要么 await 要么 void\n6. **Type as Contract** — 类型系统是模块间的契约，用判别联合而非松散可选字段\n7. **Fail Fast, Fail Loud** — 纯函数映射错误类型，不在 hook 里硬编码错误逻辑\n\n## Comments: Less is More\n\n```\nMUST:  用清晰的函数名/变量名/类型名替代注释\nMUST:  复杂算法或非直觉的业务规则才需要注释\nMUST:  注释解释 WHY，不解释 WHAT (代码本身说明 what)\nNEVER: 函数签名上方加 JSDoc 复述参数名和类型 — TypeScript 已经表达了\nNEVER: 注释掉的代码 — 直接删除，git 有历史\nNEVER: 分隔线注释 (// ────────) — 用空行和函数拆分表达结构\nNEVER: \"显而易见\"的注释 (// 设置 loading 为 true → setIsLoading(true))\n```\n\n## Architecture: Page-Autonomous Structure\n\n```\nfrontend/\n├── app/                           # Expo Router 路由 (Screen 层)\n│   ├── _layout.tsx\n│   ├── (tabs)/\n│   │   ├── index.tsx              # → 编排 pages/home 的内容\n│   │   ├── ai/index.tsx\n│   │   └── profile/index.tsx\n│   └── chat/[id].tsx\n│\n├── pages/                         # 页面业务单元 (每个页面自包含)\n│   ├── home/\n│   │   ├── components/            # 页面私有组件\n│   │   ├── hooks/                 # 页面私有 hooks\n│   │   ├── types/                 # 页面私有类型\n│   │   ├── consts/                # 页面私有常量\n│   │   └── utils/                 # 页面私有工具函数\n│   ├── profile/\n│   │   ├── components/\n│   │   ├── hooks/\n│   │   └── types/\n│   └── chat/\n│       ├── components/\n│       ├── hooks/\n│       └── types/\n│\n├── common/                        # 跨页面共享\n│   ├── components/\n│   │   ├── page-loading/          # 通用加载\n│   │   ├── page-status-view/      # 通用错误/空态 + getPageErrorType()\n│   │   ├── biz/                   # 业务级共享组件\n│   │   └── product-card/          # 可复用卡片 (Slot 组合)\n│   ├── hooks/                     # 通用 hooks (useAuth, useSafeArea)\n│   │   └── index.ts              # Barrel re-export\n│   ├── typings/                   # 共享类型定义\n│   └── consts/                    # 全局常量\n│\n├── services/                      # API client + 页面级数据获取\n│   ├── api-client.ts             # 底层请求封装 (post, postSafe, postDirect)\n│   ├── home.ts                   # 首页数据获取\n│   ├── chat.ts                   # 聊天数据获取\n│   ├── profile.ts                # 个人资料数据获取\n│   └── telegram.ts               # Telegram 认证 & 消息 API\n│\n├── lib/                           # 框架级配置（如认证客户端）\n│   └── auth-client.ts            # Better Auth 客户端 (createAuthClient)，session/Cookie 与后端一致\n│\n├── contexts/                      # Context 定义\n└── utils/                         # 全局工具函数\n```\n\n### 关键原则\n\n```\nMUST:  页面私有代码放 pages/{page}/ 下，不放 common/\nMUST:  跨 2 个以上页面复用的代码提升到 common/\nMUST:  数据获取逻辑放 services/ (按页面分文件)，不内联在组件中\nMUST:  common/hooks/index.ts barrel re-export 所有公共 hooks\nMUST:  页面私有工具函数放 pages/{page}/utils/，一个文件一个主函数\nMUST:  utils/ 文件名 = 主函数名 (kebab-case)，如 calc-column-widths.ts\nMUST:  utils/index.ts barrel re-export 所有工具函数\nMUST:  utils/ 仅含纯函数 — 不含 hooks / 组件 / 副作用\nNEVER: 工具函数内联在组件文件中 — 提取到 utils/\nNEVER: 页面级 hooks/components 目录创建 barrel index.ts — 直接 import 具体文件\nNEVER: 页面 A 直接 import 页面 B 的私有模块\nNEVER: common/ 下的代码 import pages/ 下的代码 (依赖方向: pages → common)\n```\n\n## Component Patterns\n\n### 分类与位置\n\n| 类型           | 位置                       | 职责                   |\n| -------------- | -------------------------- | ---------------------- |\n| Screen         | `app/`                     | 路由入口，编排页面组件 |\n| Page Component | `pages/{page}/components/` | 页面私有 UI            |\n| Biz Shared     | `common/components/biz/`   | 跨页面业务组件         |\n| Base Shared    | `common/components/`       | 通用 UI，零业务        |\n\n### 规则\n\n```\nMUST:  Props 接口命名: 文件内用 Props，跨文件导出用 {ComponentName}Props\nMUST:  显式返回类型: (props: Props): ReactNode => { ... }\nMUST:  页面内组件用页面前缀: Chat 页的组件用 Chat 前缀 (ChatBubble, ChatInput)\nMUST:  条件渲染统一三元: {condition ? <X /> : null}\nMUST:  空状态统一 return null\nMUST:  Slot 组合: 通过 leftArea/title/footer 等 ReactNode props 组合复杂布局\nMUST:  多组件文件 — 主组件 index.tsx + 子组件各自独立文件，放同名文件夹下\nMUST:  子组件文件名 = 组件名 (kebab-case)，如 waiting-indicator.tsx\nALLOW: 极简渲染辅助 (无 hooks、1-3 行 JSX) — 可用箭头函数常量留在同文件\nMUST:  组件文件内的非公用辅助函数使用箭头函数常量 (const fn = (...): T => { ... })，不用 function 声明\nNEVER: function 声明式定义多个组件在同一文件\nNEVER: 超过 150 行的组件 — 拆分,依据具体情况拆分，如果真的要这么多，那就不拆了\nNEVER: Props 透传超过 2 层 — 用 Context\n```\n\n### Slot 组合示例\n\n```typescript\ninterface Props<T> {\n  data: T;\n  leftArea?: ReactNode;\n  title?: ReactNode;\n  subtitle?: ReactNode;\n  operationArea?: ReactNode;\n  onPress?: (data: T) => void;\n}\n\nexport default function CardContainer<T>({ data, leftArea, title, subtitle, operationArea, onPress }: Props<T>): ReactNode {\n  return (\n    <XStack onPress={() => onPress?.(data)}>\n      {leftArea ? <YStack flexShrink={0}>{leftArea}</YStack> : null}\n      <YStack flex={1}>\n        {title ? title : null}\n        {subtitle ? subtitle : null}\n        {operationArea ? operationArea : null}\n      </YStack>\n    </XStack>\n  );\n}\n```\n\n## Hook Taxonomy\n\n### 前置规则: 禁止空壳 re-export\n\n```\nNEVER: 创建只做 re-export 的 hook 文件 (如 export { useX } from ''lib'')\n       → 直接从源库导入，空壳文件是死代码的温床\nONLY:  当你封装了自定义逻辑时，才值得创建 hook 文件\n```\n\n### useCallback / useMemo 使用规则\n\n```\nNEVER: 默认给事件处理函数套 useCallback，给计算结果套 useMemo — 大多数场景没有收益\nONLY:  useCallback: 回调传给 React.memo 子组件，或作为 useEffect/useMemo 的依赖\nONLY:  useMemo: 计算确实昂贵 (大数组遍历、复杂格式化)，或结果作为 useEffect 的依赖需要稳定引用\nMUST:  简单赋值/三元/条件判断直接写，不套 useMemo\nMUST:  组件内部的事件处理函数直接写普通函数，不套 useCallback\n```\n\nHooks 严格分三类，每类有明确的约束：\n\n### ① 数据 Hook (Data Hook)\n\n职责：获取数据 + 管理 loading/error 状态。返回结构化对象。\n\n```\nMUST:  返回命名字段: { isLoading, errorType, data, handleRetry, handleRefresh }\nMUST:  错误映射使用纯函数 getPageErrorType()，不在 hook 中硬编码\nMUST:  最多 1 个 useEffect (初始加载)\nMUST:  返回类型显式定义为 interface\nMUST:  使用 state trigger (fetchKey) + useEffect 重新触发请求，不用 useCallback 包裹请求逻辑\nMUST:  useEffect cleanup 设置 cancelled 标记防止竞态更新\nNEVER: useCallback 包裹网络请求函数 — 请求只在 useEffect 内发起\n```\n\n#### 标准 Data Hook 模式\n\n```typescript\n// 简单模式: 加载 + 重试\nconst [fetchKey, setFetchKey] = useState<number>(0);\n\nuseEffect(() => {\n  let cancelled = false;\n  setIsLoading(true);\n  setErrorType(undefined);\n\n  async function load(): Promise<void> {\n    try {\n      const response = await fetchXxxPage();\n      if (cancelled) return;\n      const mappedError = getPageErrorType(response);\n      if (mappedError) {\n        setErrorType(mappedError);\n        setData(null);\n      } else {\n        setData(response.data ?? null);\n      }\n    } catch {\n      if (cancelled) return;\n      setErrorType(PageErrorType.NETWORK);\n      setData(null);\n    } finally {\n      if (!cancelled) setIsLoading(false);\n    }\n  }\n\n  void load();\n  return () => {\n    cancelled = true;\n  };\n}, [fetchKey]); // + 其他依赖如 session\n\nconst handleRetry = (): void => {\n  setFetchKey((k) => k + 1);\n};\n```\n\n### ② 派生 Hook (Derived Hook)\n\n职责：纯计算/数据转换，零副作用。只用 `useMemo`。\n\n```\nMUST:  只使用 useMemo，不使用 useEffect / useState\nMUST:  纯函数语义: 相同输入永远相同输出\nMUST:  命名体现数据来源: useDataFromQuery, useFormattedPrice\n```\n\n### ③ 副作用 Hook (Effect Hook)\n\n职责：管理单一副作用 (事件监听、定时器、性能埋点)。\n\n```\nMUST:  只有 1 个 useEffect\nMUST:  useRef 保存最新回调 (防止闭包过期)\nMUST:  cleanup 函数清理所有副作用\nMUST:  返回类型为 void (不返回状态)\n```\n\n### 组合\n\n```typescript\n// pages/chat/hooks/useChatPageData.ts — 数据 hook (单一 effect)\n// pages/chat/hooks/useChatPolling.ts — 副作用 hook (单一 effect)\n// 在 Screen 层组合:\nconst pageData = useChatPageData(chatId);\nuseChatPolling(pageData.silentRefresh, pollingInterval);\n```\n\n详见 [STANDARDS.md](STANDARDS.md#hook-architecture) 和 [PATTERNS.md](PATTERNS.md)\n\n## Type Safety\n\n```\nMUST:  所有函数参数 + 返回值显式标注类型\nMUST:  组件返回类型标注 ReactNode\nMUST:  Hook 返回类型定义为 interface (不用内联对象类型)\nMUST:  Context 用判别联合 (discriminated union) 区分场景\nMUST:  error 使用 enum PageErrorType，不用 string\nMUST:  API 响应用 type guard 验证，不用 as T\nMUST:  不等待的 Promise 用 void 标记: void doSomething()\nNEVER: any — 用 unknown + type guard\nNEVER: as T 类型断言\nNEVER: ! 非空断言\n```\n\n### API/IDL 接口类型（蛇形命名）\n\n凡用于描述**接口契约**的类型（HTTP 请求体、响应体、SSE 事件 payload 等），其**字段名必须使用 snake_case**，与后端、第三方 API 的 JSON 契约保持一致，便于跨语言/跨端对齐。\n\n```\nMUST:  请求体/响应体/SSE 事件等 IDL 类型的属性名使用 snake_case (如 conversation_id, header_title)\nMUST:  前端读取 API 响应、组装请求体、解析 SSE 时使用与类型一致的 snake_case 键\nNEVER: 在接口契约类型中使用 camelCase 字段名\n```\n\n仅在前端或后端内部使用的类型（如组件 Props、Hook 返回类型、内部状态）仍按「代码」命名规范使用 camelCase。\n\n### 判别联合 Context 示例\n\n```typescript\ninterface ChatDirectContext {\n  scene: ''direct'';\n  peerId: string;\n  getLogParams: () => DirectLogParams;\n}\n\ninterface ChatGroupContext {\n  scene: ''group'';\n  groupId: string;\n  memberCount: number;\n  getLogParams: () => GroupLogParams;\n}\n\ntype ChatPageContext = ChatDirectContext | ChatGroupContext;\n```\n\n## Error Handling\n\n```\nMUST:  纯函数映射错误: getPageErrorType(response) => PageErrorType | undefined\nMUST:  PageErrorType 使用 enum (DEFAULT, NETWORK, AUTH, EMPTY)\nMUST:  数据 Hook 中调用 getPageErrorType 设置错误状态\nMUST:  所有 async 必须 try/catch 或 .catch()\nMUST:  不等待的 async 调用加 void 前缀: void fetchData()\nNEVER: catch(e) {} 空 catch\nNEVER: silentLoad 无 catch — 静默操作也要 console.error\n```\n\n### 标准错误流\n\n```\nAPI 响应 → getPageErrorType(resp) → PageErrorType | undefined\n                                        ↓\n                              undefined = 成功，继续处理\n                              PageErrorType = 设置错误状态\n                                        ↓\n                              Screen: <PageStatusView errorType={errorType} onRetry={handleRetry} />\n```\n\n## Style System: Tamagui-First\n\n### 核心规则\n\n```\nMUST:  使用 Tamagui 组件 (XStack, YStack, View, Text) 替代 RN 原生组件\nMUST:  布局用 Tamagui props (bg, px, py, gap, flex, borderRadius, mt, mb, pl 等)\nMUST:  颜色只用 theme tokens ($color, $blue9, $gray4, $background)\nMUST:  间距只用 size tokens ($1, $2, $3, $4)\nMUST:  交互用 Tamagui 的 pressStyle + onPress，不用 RN Pressable/TouchableOpacity\nMUST:  非 Tamagui 组件 (如 Ionicons) 的颜色用 useTheme() + theme.xxx.val\nNEVER: 从 ''react-native'' 导入 View / Text — 从 ''tamagui'' 导入\nNEVER: useMemo 构造 style 对象 — 把样式直接写成 Tamagui props\nNEVER: className / Tailwind\nNEVER: 硬编码颜色 (#ffffff, rgba(...))\nALLOW: style prop — 仅 Tamagui 不支持的属性 (borderRadius 部分值、alignItems 等)\n```\n\n### 正确 vs 错误示例\n\n```typescript\n// BAD: RN 组件 + useMemo style 对象\nimport { View, Text, Pressable } from ''react-native'';\nconst styles = useMemo(() => ({\n  container: { padding: 12, backgroundColor: theme.blue2.val, borderRadius: 12 },\n  title: { fontSize: 14, fontWeight: ''600'', color: theme.blue11.val },\n}), [themeName]);\nreturn (\n  <Pressable onPress={handlePress}>\n    <View style={styles.container}>\n      <Text style={styles.title}>标题</Text>\n    </View>\n  </Pressable>\n);\n\n// GOOD: Tamagui 组件 + inline props\nimport { YStack, Text } from ''tamagui'';\nreturn (\n  <YStack\n    bg=\"$blue2\"\n    px=\"$3\"\n    py=\"$2.5\"\n    borderWidth={1}\n    borderColor=\"$blue7\"\n    pressStyle={{ opacity: 0.8 }}\n    onPress={handlePress}\n    style={{ borderRadius: 12 }}\n  >\n    <Text fontSize={14} fontWeight=\"600\" color=\"$blue11\">标题</Text>\n  </YStack>\n);\n```\n\n## Naming Conventions\n\n### 文件\n\n```\n组件:     kebab-case.tsx     (chat-bubble.tsx, page-loading.tsx)\nHook:     camelCase.ts       (useFetchData.ts, usePolling.ts)\nService:  camelCase.ts       (chatService.ts, profileService.ts)\nType:     index.ts (在 types/ 目录下)\n常量:     index.ts (在 consts/ 目录下)\n工具函数: kebab-case.ts      (calc-column-widths.ts, sanitize-streaming-markdown.ts)\n目录:     kebab-case/        (page-status-view/, operation-button/)\nBarrel:   common/hooks/index.ts 和 pages/{page}/utils/index.ts 需要 barrel re-export\n```\n\n### 代码\n\n```\n组件名:      PascalCase + 页面前缀    ChatBubble, ChatInput, ProfileCard\nHook:        use 前缀                useFetchData, usePolling, useAuth\n常量:        UPPER_SNAKE_CASE        TAB_BAR_HEIGHT, POLLING_INTERVAL\nEnum:        PascalCase              PageErrorType, ChatScene\n函数:        camelCase + 动词        fetchChatList, getPageErrorType, handleRetry\n布尔:        is/has/should 前缀      isLoading, hasMedia, shouldRefresh\n回调 Props:  on 前缀                 onPress, onRetry, onBind\n处理函数:    handle 前缀             handleBind, handleRetry\n返回类型:    显式标注                (): ReactNode, (): void, (): Promise<void>\n```\n\n## Import Organization\n\n```typescript\n// 1. React / React Native 核心\nimport { useState, useCallback } from ''react'';\nimport { Alert } from ''react-native'';\n\n// 2. 第三方框架\nimport { useRouter } from ''expo-router'';\nimport { YStack, Text } from ''tamagui'';\n\n// 3. 项目 common/ (shared)\nimport type { ProfilePageData } from ''@/common/typings/profile'';\nimport { useAuth } from ''@/common/hooks'';\nimport PageLoading from ''@/common/components/page-loading'';\nimport { getPageErrorType } from ''@/common/components/page-status-view'';\n\n// 4. 项目 services/ (数据获取)\nimport { fetchProfilePage } from ''@/services/profile'';\n\n// 5. 页面相对路径 (同页面内)\nimport { POLLING_INTERVAL } from ''../consts'';\nimport type { ChatLogParams } from ''../types'';\nimport ChatBubble from ''./chat-bubble'';\n```\n\n```\nMUST:  type-only imports 使用 import type { X }\nMUST:  组间保留空行\nMUST:  同组内按字母排序\nMUST:  common/hooks 用 barrel import: from ''@/common/hooks''\n```\n\n## 认证 (Better Auth)\n\nPiko 统一使用 **Better Auth** 做登录与鉴权。\n\n```\nMUST:  登录、session、OAuth（如 Apple 登录）使用 frontend/lib/auth-client.ts 的 createAuthClient 实例\nMUST:  需要带登录态请求时，用 authClient.getSession() / getCookie() 等注入；若在 fetch 里手动设置 Cookie，使用 credentials: ''omit''（与 Better Auth 文档一致）\nMUST:  鉴权/登录相关逻辑以 Better Auth 文档与项目 PRD（如 docs/PRD-Apple-Login-Better-Auth-Alignment.md）为准\nNEVER: 引入或教学其他认证库（如 Next-Auth）替代 Better Auth\n```\n\n## 依赖管理 (Dependency Management)\n\n```\nNEVER: 通过直接编辑 package.json 添加或删除依赖\nMUST:  使用包管理器官方命令添加/删除依赖（与本项目一致）\n       例如: pnpm add <pkg> / pnpm add -D <pkg>、pnpm remove <pkg>\n       或: npm install <pkg>、yarn add <pkg>（以项目根目录 package.json 或文档为准）\nMUST:  添加依赖前确认当前项目使用的包管理器（看 lockfile: pnpm-lock.yaml / package-lock.json / yarn.lock）\n```\n\n无论何时需要新增或移除依赖，都必须通过终端执行官方命令，不得手改 `package.json`。\n\n## Enforcement\n\n写代码时自动检查:\n\n1. 页面私有代码是否放在 pages/{page}/ 下？\n2. 组件是否超过 150 行？→ 拆分,依据具体情况拆分，如果真的要这么多，那就不拆了\n3. Hook 是否属于明确的分类 (数据/派生/副作用)？\n4. Hook 是否有多个 useEffect？→ 拆分\n5. 返回类型是否显式标注？→ 补充 ReactNode / void\n6. 是否有 any/as/! ？→ type guard\n7. error 是否用 enum？→ 不用 string\n8. 不等待的 Promise 是否加了 void？\n9. 样式是否用 Tamagui token？→ 不用 className/硬编码\n10. import 是否按规范分组？\n11. 新增/删除依赖是否通过包管理器命令？→ 禁止直接编辑 package.json\n12. 登录/鉴权相关是否使用 Better Auth（auth-client、credentials: ''omit'' 当手动设 Cookie）？→ 见「认证 (Better Auth)」节\n\n## References\n\n- [STANDARDS.md](STANDARDS.md) — 详细编码标准 + 完整代码实现\n- [PATTERNS.md](PATTERNS.md) — 正确模式 vs 反模式对照\n- [REVIEW-CHECKLIST.md](REVIEW-CHECKLIST.md) — PR 审查清单\n"},"lastSynced":"2026-03-08T02:13:21.048Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Development Agents requiring strict code standards and efficient page autonomy","zh":"适合需要严格代码标准和高效页面自治的前端开发代理","ja":"厳格なコード規範と効率的なページオートノミーを必要とするフロントエンド開発エージェントに適している","ko":"严格한 코드 표준과 효율적인 페이지 자율성을 필요로 하는 프론트엔드 개발 에이전트에 적합","es":"Ideal para Agentes de Desarrollo Frontend que requieren estrictas normas de código y autonomía de página eficiente","fr":"Idéal pour les agents de développement Frontend nécessitant des normes de code strictes et une autonomie de page efficace","de":"Ideal für Frontend-Entwicklungsagenten, die strenge Code-Standards und effiziente Seitenautonomie erfordern","pt":"Ideal para Agentes de Desenvolvimento Frontend que exigem padrões de código rigorosos e autonomia de página eficiente","ru":"Идеально для агентов фронтенд-разработки, требующих строгих стандартов кодирования и эффективной автономности страницы","ar":"مثالي لعمليات تطوير الواجهة الأمامية التي تتطلب معايير ترميز صارمة واستقلالية صفحة فعالة"},"recommendation":{"en":"Empowers agents to enforce code as documentation, utilizing explicit type annotations and promoting composition over complexity, while ensuring single responsibility and fail-fast error handling through strict adherence to TypeScript contracts and Promise handling","zh":"赋予代理人使用显式类型注释来强制执行代码作为文档，并通过严格遵守TypeScript契约和Promise处理来促进组合而非复杂性，确保单一责任和快速失败错误处理","ja":"エージェントに明示的な型注釈を使用してコードをドキュメントとして強制実行し、TypeScript契約とPromiseハンドリングへの厳格な遵守を通じて、複雑さよりも構成を促進し、単一の責任と迅速に失敗するエラー処理を確保する","ko":"에이전트가 명시적인 유형注釈를 사용하여 코드를 문서로 강제하고, TypeScript 계약과 Promise 처리에 대한 엄격한 준수를 통해 복잡성보다는 구성과 단일 책임 및 빠른 실패 오류 처리를 보장","es":"Habilita a los agentes a aplicar el código como documentación, utilizando anotaciones de tipo explícitas y promoviendo la composición sobre la complejidad, al mismo tiempo que garantiza la responsabilidad única y el manejo de errores fall-fast a través del cumplimiento estricto de los contratos de TypeScript y el manejo de Promesas","fr":"Permet aux agents d''appliquer le code comme documentation, en utilisant des annotations de type explicites et en promouvant la composition plutôt que la complexité, tout en assurant la responsabilité unique et la gestion des erreurs fail-fast grâce au respect strict des contrats TypeScript et de la gestion des Promesses","de":"Ermächtigt die Agenten, Code als Dokumentation durchzusetzen, indem explizite Typannotierungen verwendet und die Zusammensetzung über Komplexität gefördert wird, während gleichzeitig die Einzelverantwortung und der fail-fast-Fehlerbehandlung durch die strikte Einhaltung von TypeScript-Verträgen und der Promise-Verarbeitung sichergestellt werden","pt":"Habilita os agentes a impor código como documentação, utilizando anotações de tipo explícitas e promovendo composição sobre complexidade, garantindo responsabilidade única e tratamento de erros fail-fast por meio da adesão rigorosa aos contratos TypeScript e manipulação de Promessas","ru":"Наделяет агентов возможностью обеспечить код как документацию, используя явные аннотации типов и продвигая композицию над сложностью, обеспечивая единственную ответственность и обработку ошибок fail-fast посредством строгого соблюдения контрактов TypeScript и обработки Promises","ar":"تمكّن الوكلاء من فرض الشفرة كوثيقة، باستخدام تعليقات أنواع صريحة وتعزيز التركيب على التعقيد، مع ضمان المسؤولية الفريدة ومعالجة الأخطاء الفاشلة من خلال الالتزام الصارم بعقود TypeScript ومعالجة الوعد"},"useCases":{"en":["Enforcing code standards for page autonomy","Generating self-documenting code with explicit type annotations","Optimizing frontend development with composition over complexity principles"],"zh":["强制执行页面自治的代码标准","使用显式类型注释生成自我记录的代码","使用组合优于复杂性原则优化前端开发"],"ja":["ページオートノミーのコード規範を強制実行する","明示的な型注釈を使用して自己記述コードを生成する","構成よりも複雑さの原則を使用してフロントエンド開発を最適化する"],"ko":["페이지 자율성을 위한 코드 표준 강제","명시적인 유형 주석을 사용하여 자기 기록 코드 생성","구성보다 복잡성 원칙을 사용하여 프론트엔드 개발 최적화"],"es":["Aplicar normas de código para la autonomía de página","Generar código auto-documentado con anotaciones de tipo explícitas","Optimizar el desarrollo frontend con principios de composición sobre complejidad"],"fr":["Mettre en œuvre des normes de code pour l''autonomie de page","Générer du code auto-documenté avec des annotations de type explicites","Optimiser le développement frontend avec des principes de composition plutôt que de complexité"],"de":["Code-Standards für die Seitenautonomie durchsetzen","Selbst-dokumentierenden Code mit expliziten Typannotierungen generieren","Frontend-Entwicklung mit Zusammensetzungs-über-Komplexitäts-Prinzipien optimieren"],"pt":["Impor padrões de código para autonomia de página","Gerar código auto-documentado com anotações de tipo explícitas","Otimizar desenvolvimento frontend com princípios de composição sobre complexidade"],"ru":["Обеспечение стандартов кодирования для автономности страницы","Генерация само-документирующего кода с явными аннотациями типов","Оптимизация фронтенд-разработки на принципах композиции над сложностью"],"ar":["فرض معايير الترميز لاستقلالية الصفحة","إنشاء شفرة ذاتية التوثيق مع تعليقات أنواع صريحة","تحسين تطوير الواجهة الأمامية بمبادئ التركيب على التعقيد"]},"limitations":{"en":["Requires adherence to strict coding standards","Limited to frontend development applications","Dependent on TypeScript for contract-based typing"],"zh":["需要遵守严格的编码标准","仅限于前端开发应用","依赖TypeScript进行基于契约的类型化"],"ja":["厳格なコード規範への遵守が必要","フロントエンド開発アプリケーションに限定される","TypeScriptを使用した契約ベースの型付けに依存する"],"ko":["严格한 코딩 표준 준수를 필요로함","프론트엔드 개발 애플리케이션에만 제한","TypeScript를 사용한 계약 기반 타이핑에 의존"],"es":["Requiere el cumplimiento de estrictas normas de codificación","Limitado a aplicaciones de desarrollo frontend","Dependiente de TypeScript para la tipificación basada en contratos"],"fr":["Nécessite le respect de normes de codage strictes","Limité aux applications de développement frontend","Dépendant de TypeScript pour la typification basée sur les contrats"],"de":["Erfordert die Einhaltung strenger Codierungsstandards","Begrenzt auf Frontend-Entwicklungsanwendungen","Abhängig von TypeScript für die vertragsbasierte Typisierung"],"pt":["Exige adesão a padrões de codificação rigorosos","Limitado a aplicações de desenvolvimento frontend","Dependente de TypeScript para digitação baseada em contrato"],"ru":["Требует соблюдения строгих стандартов кодирования","Ограничен для фронтенд-разработки приложений","Зависит от TypeScript для контрактного типирования"],"ar":["يتطلب الالتزام بمعايير الترميز الصارمة","محدود لتطبيقات تطوير الواجهة الأمامية"