INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Babytiann/Piko/piko-frontend-standards', 'piko-frontend-standards', 'Babytiann', 'Piko', 'community', 'piko-frontend-standards Babytiann Piko community piko-frontend-standards is a set of code standards for frontend development, benefiting developers by promoting code as documentation and page autonomy. It enables efficient development and maintenance of frontend applications. Piko 前端标准是一套代码即文档的开发指南，旨在提高开发效率和代码质量 Piko フロントエンド標準はコード即文書の開発ガイドであり、開発効率とコード品質を向上させることを目的としています Piko 프론트엔드 표준은 코드即문서의 개발 가이드로서 개발 효율성과 코드 품질을 향상시키는 것을 목표로 합니다 piko-frontend-standards es un conjunto de normas para desarrolladores frontend que busca mejorar la calidad y mantenibilidad del código piko-frontend-standards est un ensemble de normes pour les développeurs frontend qui vise à améliorer la qualité et la maintenabilité du code piko-frontend-standards ist ein Satz von Normen für Frontend-Entwickler, die darauf abzielen, die Qualität und Wartbarkeit des Codes zu verbessern O Piko Frontend Standards é um conjunto de diretrizes para codificação frontend que visa melhorar a legibilidade e manutenção do código Piko Фронтенд Стандарты - это набор руководств для frontend-кодирования, направленный на улучшение читаемости и обслуживания кода для ИИ Агентов معايير پيكو フロントإند هي مجموعة من الإرشادات لبرمجة الفرونت إند التي تهدف إلى تحسين قابلية القراءة و الصيانة للكود لآلات الإي الأجنت how to use piko-frontend-standards piko-frontend-standards setup guide piko-frontend-standards vs other frontend standards piko-frontend-standards install what is piko-frontend-standards piko-frontend-standards best practices piko-frontend-standards alternative piko-frontend-standards documentation piko-frontend-standards tutorial Piko 前端标准 代码即文档 页面自治 单一职责 组合优于复杂性 显式优于隐式 类型作为契约 前端开发 代码组织 开发原则 Enforces code as documentation principle for self-explanatory code Promotes page autonomy with self-contained components, hooks, and types Implements single responsibility principle for functions and components Supports composition over complexity with slot and hook combinations Explicitly annotates return types and handles promises with await or void Utilizes type systems as contracts between modules with discriminated unions piko-frontend-standards is a set of guidelines for writing clean, maintainable, and efficient frontend code, emphasizing code as documentation and single responsibility principles.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('niltsiar/kotlin_multiplatform_pokedex/kmp-compose-unstyled', 'community', 'niltsiar', 'kotlin_multiplatform_pokedex', 'niltsiar/kotlin_multiplatform_pokedex', 'kmp-compose-unstyled', 0, 0, 54, '2026-03-08T01:57:15.617Z', '2026-03-08T02:13:25.731Z', '8f2169753e158fc96b014b8fee8ff29e8ecde2e92b7748cfec306182c2c0c7eb', '{"id":"niltsiar/kotlin_multiplatform_pokedex/kmp-compose-unstyled","name":"kmp-compose-unstyled","description":{"en":"kmp-compose-unstyled is a Kotlin Multiplatform project for developing headless component libraries, handling UX logic and accessibility. It benefits developers building unstyled UI screens and custom themes.","zh":"KMP Compose Unstyled是一个用于测试Kotlin Multiplatform应用开发的项目，提供无样式组件库实现","ja":"KMP Compose Unstyledは、Kotlin Multiplatformアプリを開発するための小さなプロジェクトです。ヘドレスコンポーネントライブラリの実装パターンを提供します","ko":"KMP Compose Unstyled는 Kotlin Multiplatform 애플리케이션 개발을 테스트하기 위한 작은 프로젝트로, 헤드리스 컴포넌트 라이브러리 구현 패턴을 제공합니다","es":"kmp-compose-unstyled es una biblioteca de componentes headless para aplicaciones Kotlin Multiplatform que maneja la lógica de UX, estado y accesibilidad sin renderizar una interfaz de usuario visual por defecto","fr":"kmp-compose-unstyled est une bibliothèque de composants headless pour les applications Kotlin Multiplatform qui gère la logique UX, l''état et l''accessibilité sans rendre une interface utilisateur visuelle par défaut","de":"kmp-compose-unstyled ist eine Headless-Komponentenbibliothek für Kotlin-Multiplatform-Anwendungen, die die UX-Logik, den Zustand und die Zugänglichkeit ohne standardmäßige Darstellung einer visuellen Benutzeroberfläche verwaltet","pt":"O kmp-compose-unstyled é uma biblioteca de componentes headless para aplicações Kotlin Multiplatform, permitindo a criação de UIs personalizadas e acessíveis","ru":"kmp-compose-unstyled - это библиотека бесстойловых компонентов для приложений Kotlin Multiplatform, позволяющая создавать индивидуальные и доступные интерфейсы","ar":"kmp-compose-unstyled هي مكتبة مكونات بدون أنماط ل تطبيقات Kotlin Multiplatform، مما يسمح بإنشاء واجهات مستخدم مخصصة وقابلة للوصول"},"seo":{"title":{"en":"kmp-compose-unstyled: Headless Component Library Setup Gu...","zh":"KMP Compose Unstyled.setup指南 - 无样式组件库实现","ja":"KMP Compose Unstyledのベストプラクティス - AIエージェントを使用したUI開発","ko":"KMP Compose Unstyled설치 가이드 - 헤드리스 컴포넌트 라이브러리 구현","es":"Guía de configuración de kmp-compose-unstyled para Kotlin...","fr":"Mise en place de kmp-compose-unstyled pour les applicatio...","de":"Einrichtungsleitfaden für kmp-compose-unstyled in Kotlin-...","pt":"Guia de Configuração do kmp-compose-unstyled para Desenvo...","ru":"Настройка kmp-compose-unstyled для Разработки Бесстойловы...","ar":"دليل إعداد kmp-compose-unstyled لتطوير واجهات المستخدم غي..."},"description":{"en":"Discover how to implement unstyled UI screens and configure themes using kmp-compose-unstyled. Learn more and get started with this AI agent skill today!","zh":"了解KMP Compose Unstyled的技术细节和实现方法，使用无样式组件库开发跨平台应用","ja":"KMP Compose Unstyledを使用して、UXロジック、状態、そしてアクセシビリティを扱うヘドレスコンポーネントを作成する方法を学ぶ","ko":"KMP Compose Unstyled를 사용하여 헤드리스 컴포넌트 라이브러리를 구현하고 Pokédex 프로젝트에 적용하는 방법을 알아보세요","es":"Aprende a utilizar kmp-compose-unstyled para crear componentes de interfaz de usuario sin estilo en aplicaciones Kotlin Multiplatform","fr":"Découvrez comment utiliser kmp-compose-unstyled pour créer des composants d''interface utilisateur sans style dans les applications Kotlin Multiplatform","de":"Erfahren Sie, wie Sie kmp-compose-unstyled verwenden, um ungestylte Benutzeroberflächenkomponenten in Kotlin-Multiplatform-Anwendungen zu erstellen","pt":"Aprenda a utilizar o kmp-compose-unstyled para criar UIs personalizadas e acessíveis em aplicações Kotlin Multiplatform","ru":"Узнайте, как использовать kmp-compose-unstyled для создания индивидуальных и доступных интерфейсов в приложениях Kotlin Multiplatform","ar":"تعرف على كيفية استخدام kmp-compose-unstyled لإنشاء واجهات مستخدم مخصصة وقابلة للوصول في تطبيقات Kotlin Multiplatform"},"definition":{"en":"kmp-compose-unstyled is a headless component library implementation for Kotlin Multiplatform apps, providing unstyled components for UX logic and accessibility.","zh":"KMP Compose Unstyled是一种无样式组件库实现，用于处理UX逻辑、状态和可访问性","ja":"KMP Compose Unstyledは、UXロジック、状態、そしてアクセシビリティを扱うヘドレスコンポーネントライブラリの実装です","ko":"KMP Compose Unstyled는 UX 로직, 상태, 및 접근성을 처리하는 헤드리스 컴포넌트 라이브러리 구현입니다","es":"kmp-compose-unstyled es una biblioteca de componentes headless para Kotlin Multiplatform que permite crear componentes de interfaz de usuario sin estilo","fr":"kmp-compose-unstyled est une bibliothèque de composants headless pour les applications Kotlin Multiplatform qui permet de créer des composants d''interface utilisateur sans style","de":"kmp-compose-unstyled ist eine Headless-Komponentenbibliothek für Kotlin-Multiplatform-Anwendungen, die die Erstellung von ungestylten Benutzeroberflächenkomponenten ermöglicht","pt":"O kmp-compose-unstyled é uma biblioteca de componentes headless que lida com a lógica de UX, estado e acessibilidade sem renderizar UI visual por padrão","ru":"kmp-compose-unstyled - это библиотека бесстойловых компонентов, которая обрабатывает логику UX, состояние и доступность без отображения визуального интерфейса по умолчанию","ar":"kmp-compose-unstyled هي مكتبة مكونات بدون أنماط تتعامل مع منطق UX والحالة والوصول دون عرض واجهة مستخدم مرئية افتراضيا"},"features":{"en":["Building Unstyled UI screens in :features:<feature>:ui-unstyled modules","Configuring Themes using buildTheme or buildPlatformTheme DSLs","Implementing Headless Components with custom styling","Ensuring Platform-specific accessibility","Using Kotlin Multiplatform for cross-platform development"],"zh":["无样式组件库实现","UX逻辑和状态处理","可访问性支持","使用buildTheme或buildPlatformTheme DSL配置主题","实现自定义样式的头部组件"],"ja":["ヘドレスコンポーネントライブラリの実装","UXロジックと状態の処理","アクセシビリティのサポート","buildThemeまたはbuildPlatformTheme DSLを使用したテーマの設定","カスタムスタイルのヘッドレスコンポーネントの実装"],"ko":["헤드리스 컴포넌트 라이브러리 구현","UX 로직 및 상태 처리","접근성 지원","buildTheme 또는 buildPlatformTheme DSL을 사용한 테마 설정","커스텀 스타일의 헤드리스 컴포넌트 구현"],"es":["Implementación de componentes headless para aplicaciones Kotlin Multiplatform","Configuración de temas utilizando DSLs como buildTheme o buildPlatformTheme","Creación de componentes de interfaz de usuario sin estilo para manejar la lógica de UX y el estado","Compatibilidad con la accesibilidad en componentes sin estilo","Integración con la biblioteca de componentes de Pokédex"],"fr":["Implémentation de composants headless pour les applications Kotlin Multiplatform","Configuration de thèmes en utilisant des DSL comme buildTheme ou buildPlatformTheme","Création de composants d''interface utilisateur sans style pour gérer la logique UX et l''état","Compatibilité avec l''accessibilité dans les composants sans style","Intégration avec la bibliothèque de composants de Pokédex"],"de":["Implementierung von Headless-Komponenten für Kotlin-Multiplatform-Anwendungen","Konfiguration von Designs mit DSLs wie buildTheme oder buildPlatformTheme","Erstellung von ungestylten Benutzeroberflächenkomponenten zur Verwaltung der UX-Logik und des Zustands","Unterstützung der Zugänglichkeit in ungestylten Komponenten","Integration mit der Komponentenbibliothek von Pokédex"],"pt":["Criação de UIs personalizadas e acessíveis","Utilização de componentes headless para lógica de UX e estado","Configuração de temas personalizados com DSLs","Implementação de componentes personalizados com estilização","Garantia de acessibilidade em aplicações Kotlin Multiplatform"],"ru":["Создание индивидуальных и доступных интерфейсов","Использование бесстойловых компонентов для логики UX и состояния","Настройка индивидуальных тем с помощью DSL","Реализация индивидуальных компонентов с кастомной стилизацией","Обеспечение доступности в приложениях Kotlin Multiplatform"],"ar":["إنشاء واجهات مستخدم مخصصة وقابلة للوصول","استخدام مكونات بدون أنماط لمنطق UX والحالة","تكوين أنماط مخصصة باستخدام لغة تحويل DSL","تنفيذ مكونات مخصصة مع تنسيق مخصص","ضمان الوصول في تطبيقات Kotlin Multiplatform"]},"keywords":{"en":["how to use kmp-compose-unstyled","kmp-compose-unstyled alternative","kmp-compose-unstyled setup guide","what is kmp-compose-unstyled","kmp-compose-unstyled vs Jetpack Compose","kmp-compose-unstyled install","kotlin multiplatform development","headless component library","unstyled UI screens"],"zh":["KMP Compose Unstyled","无样式组件库","Kotlin Multiplatform","UX逻辑","状态处理","可访问性","AI工具","跨平台应用开发"],"ja":["KMP Compose Unstyled","ヘドレスコンポーネントライブラリ","Kotlin Multiplatform","UXロジック","状態の処理","アクセシビリティ","AIエージェント","クロスプラットフォームアプリ開発"],"ko":["KMP Compose Unstyled","헤드리스 컴포넌트 라이브러리","Kotlin Multiplatform","UX 로직","상태 처리","접근성","AI 도구","크로스 플랫폼 애플리케이션 개발"],"es":["kmp-compose-unstyled","Kotlin Multiplatform","componentes headless","temas de interfaz de usuario","accesibilidad en aplicaciones móviles","desarrollo de aplicaciones con Kotlin","bibliotecas de componentes para Kotlin","herramientas de desarrollo de aplicaciones móviles"],"fr":["kmp-compose-unstyled","Kotlin Multiplatform","composants headless","thèmes d''interface utilisateur","accessibilité dans les applications mobiles","développement d''applications avec Kotlin","bibliothèques de composants pour Kotlin","outils de développement d''applications mobiles"],"de":["kmp-compose-unstyled","Kotlin-Multiplatform","Headless-Komponenten","Benutzeroberflächendesigns","Zugänglichkeit in mobilen Anwendungen","Entwicklung von Anwendungen mit Kotlin","Komponentenbibliotheken für Kotlin","Entwicklungstools für mobile Anwendungen","Künstliche Intelligenz Agenten"],"pt":["kmp-compose-unstyled","Kotlin Multiplatform","UI personalizada","acessibilidade","componentes headless","temas personalizados","DSL","desenvolvimento de aplicações móveis"],"ru":["kmp-compose-unstyled","Kotlin Multiplatform","индивидуальный интерфейс","доступность","бесстойловые компоненты","индивидуальные темы","DSL","разработка мобильных приложений"],"ar":["kmp-compose-unstyled","Kotlin Multiplatform","واجهة مستخدم مخصصة","الوصول","مكونات بدون أنماط","أنماط مخصصة","لغة تحويل DSL","تطوير تطبيقات الجوال"]}},"owner":"niltsiar","repo":"kotlin_multiplatform_pokedex","repoPath":"niltsiar/kotlin_multiplatform_pokedex","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.617Z","topics":[],"category":"community","skillMd":{"name":"kmp-compose-unstyled","description":"Headless component library with platform-native theming and accessibility. Use when: (1) Building Unstyled UI screens in :ui-unstyled modules, (2) Configuring themes with buildPlatformTheme DSL, (3) Implementing headless components (Button, Text, ProgressIndicator), (4) Ensuring platform-native accessibility, (5) Creating custom-styled components. Keywords: Compose Unstyled, headless components, platform theming, accessibility","bodyPreview":"# KMP Compose Unstyled\n\nHeadless component library implementation patterns for the Pokédex project. Unstyled components handle UX logic, state, and accessibility while rendering no visual UI by default.\n\n## When to Use This Skill\n\n- **Building Unstyled UI screens** in `:features:<feature>:ui-unstyled` modules.\n- **Configuring Themes** using `buildTheme` or `buildPlatformTheme` DSLs.\n- **Implementing Headless Components** (Button, Text, ProgressIndicator, etc.) with custom styling.\n- **Ensuring P","body":"# KMP Compose Unstyled\n\nHeadless component library implementation patterns for the Pokédex project. Unstyled components handle UX logic, state, and accessibility while rendering no visual UI by default.\n\n## When to Use This Skill\n\n- **Building Unstyled UI screens** in `:features:<feature>:ui-unstyled` modules.\n- **Configuring Themes** using `buildTheme` or `buildPlatformTheme` DSLs.\n- **Implementing Headless Components** (Button, Text, ProgressIndicator, etc.) with custom styling.\n- **Ensuring Platform-Native Accessibility** using interactive size modifiers and platform-specific indications.\n\n## Mode Detection\n\n| User Request | Reference File | Load When |\n|--------------|----------------|-----------|\n| \"Create Unstyled component\" / \"buildPlatformTheme\" | [compose_unstyled_reference.md](references/compose_unstyled_reference.md) | MANDATORY - Read before implementing |\n| \"Customize tokens\" / \"CompositionLocal theming\" | [component_token_customization_example.md](references/component_token_customization_example.md) | MANDATORY - Read before customizing |\n| \"Component not working\" / \"UI issues\" | [troubleshooting.md](references/troubleshooting.md) | Check for common issues |\n\n**MANDATORY - READ ENTIRE FILE**: Before implementing Unstyled components with buildPlatformTheme or buildTheme, you MUST read [compose_unstyled_reference.md](references/compose_unstyled_reference.md) (~1319 lines) for comprehensive component catalog and patterns.\n\n**MANDATORY - READ ENTIRE FILE**: Before customizing component tokens via CompositionLocal, you MUST read [component_token_customization_example.md](references/component_token_customization_example.md) (~142 lines) for customization patterns.\n\n**Do NOT load** `component_token_customization_example.md` for basic component usage - only load when implementing custom token overrides.\n**Do NOT load** `troubleshooting.md` unless experiencing specific UI component issues.\n\n## Core Patterns\n\n### 1. buildPlatformTheme DSL\nUses platform-specific fonts, sizes, and indications automatically.\n```kotlin\nval PlatformTheme = buildPlatformTheme(name = \"MyAppTheme\") {\n    defaultContentColor = Color.Black\n    defaultTextStyle = TextStyle(fontSize = 16.sp, fontWeight = FontWeight.Normal)\n    // Platform fonts (Roboto, SF Pro) applied automatically\n}\n```\n\n### 2. Interactive Size Modifier\nEnsures touch targets meet platform accessibility standards (Android 48dp, iOS 44dp).\n```kotlin\nButton(\n    onClick = {},\n    modifier = Modifier.interactiveSize(Theme[interactiveSizes][sizeDefault])\n) { Text(\"Accessible Button\") }\n```\n\n### 3. Theme Access Syntax\nAlways use direct bracket notation for fresh theme reads. Avoid storing theme references.\n```kotlin\nval primary = Theme[colors][primary] // ✅ Direct access\nval body = Theme[typography][bodyMedium]\n```\n\n### 4. ProgressIndicator Wrapper\nUnlike Material, Unstyled `ProgressIndicator` requires a wrapper to render the fill.\n```kotlin\nProgressIndicator(progress = progress) {\n    Box(Modifier.fillMaxWidth(progress).fillMaxSize().background(contentColor, shape))\n}\n```\n\n## Related Skills\n- **@kmp-design-systems** - Token system and core component architecture.\n- **@kmp-architecture** - Module structure (Unstyled theme in `:core:designsystem-unstyled`).\n- **@compose-screen** - General patterns for implementing Compose screens.\n- **@ui-ux-designer** - Visual design and animation guidelines.\n\n## Critical Guardrails\n\n1. **NEVER include Material Design 3 patterns or components in Unstyled modules** → keep modules strictly separated (reason: maintains clean architectural boundaries and prevents visual leakage).\n2. **NEVER hardcode platform-specific sizes** → always use `Theme[interactiveSizes][sizeDefault]` (reason: ensures accessibility compliance across Android/iOS/Desktop/Web automatically).\n3. **NEVER manual configure `fontFamily` in `buildPlatformTheme`** → let it be automatic unless using custom fonts (reason: ensures native platform look-and-feel without extra configuration).\n4. **NEVER store `Theme.currentTheme` in variables** → always use direct bracket notation `Theme[prop][token]` (reason: breaks reactivity and prevents state atomicity issues).\n5. **NEVER use `Modifier.clickable` for interactive elements** → use the `Button` component instead (reason: `Button` provides built-in ARIA support and keyboard interaction logic).\n6. **NEVER forget the inner fill Box for `ProgressIndicator`** → always implement the rendering block (reason: unlike Material, Unstyled ProgressIndicator renders no UI by default).\n7. **NEVER skip `@Preview` annotations** → every UI component needs a preview with its theme (reason: essential for visual verification and developer efficiency).\n8. **NEVER access tokens via `MaterialTheme.tokens` in unstyled modules** → use the Unstyled `Theme` object (reason: prevents tight coupling and breaks dual-theme encapsulation).\n\n## Decision Framework\n\nBefore implementing Unstyled components, ask yourself:\n\n1. **What level of customization is needed?**\n   - Platform-native defaults → Use `buildPlatformTheme` (automatic fonts, sizes, indications)\n   - Custom styling → Use `buildTheme` with explicit token values\n   - Component-specific → Apply Modifier chains to headless components\n\n2. **Which headless components should I use?**\n   - Interactive elements → `Button`, `IconButton` (handle touch targets, accessibility)\n   - Text display → `Text` (platform-native typography)\n   - Loading states → `ProgressIndicator` (platform-specific animations)\n   - Custom components → Build with `Modifier.interactiveSize()` for accessibility\n\n3. **How do I ensure accessibility?**\n   - Always use `Modifier.interactiveSize()` for touch targets (48dp minimum)\n   - Use `Modifier.indication()` for platform-native feedback\n   - Add `@Preview` with theme applied for visual verification\n   - Test on both Android and iOS for platform consistency\n\n## Essential Workflows\n\n### Workflow 1: Creating an Unstyled Screen with buildPlatformTheme\n\nTo implement a screen with platform-native theming:\n\n1. Define the theme using `buildPlatformTheme` in your design system module:\n   ```kotlin\n   val UnstyledTheme = buildPlatformTheme(name = \"UnstyledTheme\") {\n       defaultContentColor = Color(0xFF1C1B1F)\n       defaultTextStyle = TextStyle(fontSize = 16.sp, fontWeight = FontWeight.Normal)\n       // Platform fonts (Roboto, SF Pro) applied automatically\n   }\n   ```\n2. Wrap your screen content with the theme object:\n   ```kotlin\n   @Composable\n   fun PokemonListUnstyledScreen(viewModel: PokemonListViewModel) {\n       val uiState by viewModel.uiState.collectAsStateWithLifecycle()\n       UnstyledTheme {\n           PokemonListContent(uiState = uiState)\n       }\n   }\n   ```\n3. Access tokens using bracket notation:\n   ```kotlin\n   Box(modifier = Modifier.background(Theme[colors][background])) {\n       Text(\"Pokédex\", style = Theme[typography][headlineLarge])\n   }\n   ```\n\nRelated skills: @kmp-design-systems, @compose-screen\n\n### Workflow 2: Building Custom Headless Components\n\nTo create reusable components using Unstyled primitives:\n\n1. Use the `Button` component for any interactive element:\n   ```kotlin\n   @Composable\n   fun PokemonCard(pokemon: Pokemon, onClick: () -> Unit) {\n       Button(\n           onClick = onClick,\n           backgroundColor = Theme[colors][surface],\n           contentColor = Theme[colors][onSurface],\n           shape = Theme[shapes][cardShape],\n           modifier = Modifier.interactiveSize(Theme[interactiveSizes][sizeDefault])\n       ) {\n           Column(horizontalAlignment = Alignment.CenterHorizontally) {\n               AsyncImage(model = pokemon.imageUrl, contentDescription = null)\n               Text(text = pokemon.name, style = Theme[typography][bodyLarge])\n           }\n       }\n   }\n   ```\n2. Apply `interactiveSize` to ensure accessibility standards are met.\n\nRelated skills: @kmp-design-systems, @ui-ux-designer\n\n### Workflow 3: Implementing Interactive Size for Accessibility\n\nTo ensure your UI meets platform-specific touch target requirements:\n\n1. Use `sizeDefault` (48dp Android, 44dp iOS) for primary actions:\n   ```kotlin\n   Button(\n       onClick = {},\n       modifier = Modifier.interactiveSize(Theme[interactiveSizes][sizeDefault])\n   ) { Text(\"Accessible Button\") }\n   ```\n2. Use `sizeMinimum` (32dp Android, 28dp iOS) for dense toolbars:\n   ```kotlin\n   IconButton(\n       onClick = {},\n       modifier = Modifier.interactiveSize(Theme[interactiveSizes][sizeMinimum])\n   ) { Icon(Lucide.Settings, contentDescription = \"Settings\") }\n   ```\n\nRelated skills: @kmp-architecture, @ui-ux-designer\n\n### Workflow 4: Using ProgressIndicator with Custom Styling\n\nTo implement a progress bar that requires manual fill rendering:\n\n1. Provide the rendering block inside the `ProgressIndicator` call:\n   ```kotlin\n   ProgressIndicator(\n       progress = progress,\n       modifier = Modifier.fillMaxWidth().height(8.dp),\n       shape = RoundedCornerShape(8.dp),\n       backgroundColor = Theme[colors][surface],\n       contentColor = Theme[colors][primary]\n   ) {\n       // Manual rendering of the progress fill\n       Box(\n           Modifier\n               .fillMaxWidth(progress)\n               .fillMaxSize()\n               .background(contentColor, shape)\n       )\n   }\n   ```\n\nRelated skills: @kmp-developer, @compose-screen\n\n## Quick Reference\n\n| Pattern | Purpose | Example |\n|---------|---------|---------|\n| `buildPlatformTheme` | Platform-native fonts/sizes | `buildPlatformTheme(name = \"App\") { ... }` |\n| `Theme[colors][primary]` | Direct theme access | `val primary = Theme[colors][primary]` |\n| `interactiveSize` | Accessibility compliance | `Modifier.interactiveSize(Theme[interactiveSizes][sizeDefault])` |\n| `ProgressIndicator` | Custom fill rendering | `ProgressIndicator(progress) { Box(...) }` |\n| `ProvideTextStyle` | Cascading text styles | `ProvideTextStyle(Theme[typography][body]) { ... }` |\n\n## Cross-References\n\n### Skills (by Category)\n\n**Design & UI**\n| Skill | Purpose | Link |\n| --- | --- | --- |\n| @kmp-design-systems | Token system and component architecture | [SKILL.md](../kmp-design-systems/SKILL.md) |\n| @ui-ux-designer | Visual design and animation guidelines | [SKILL.md](../ui-ux-designer/SKILL.md) |\n| @compose-screen | General patterns for implementing Compose screens | [SKILL.md](../compose-screen/SKILL.md) |\n\n**Implementation**\n| Skill | Purpose | Link |\n| --- | --- | --- |\n| @kmp-architecture | Module structure and vertical slicing | [SKILL.md](../kmp-architecture/SKILL.md) |\n| @kmp-developer | General development and feature implementation | [SKILL.md](../kmp-developer/SKILL.md) |\n| @kmp-critical-patterns | 6 core patterns quick reference | [SKILL.md](../kmp-critical-patterns/SKILL.md) |\n\n**Platform & Navigation**\n| Skill | Purpose | Link |\n| --- | --- | --- |\n| @kmp-navigation | Navigation 3 modular architecture | [SKILL.md](../kmp-navigation/SKILL.md) |\n| @kmp-testing-patterns | UI and screenshot testing with Roborazzi | [SKILL.md](../kmp-testing-patterns/SKILL.md) |\n\n### Documents\n\n| Document | Purpose | Link |\n| --- | --- | --- |\n| compose_unstyled_patterns.md | Detailed patterns catalog | See @kmp-compose-unstyled skill |\n| compose_unstyled_reference.md | Catalog and implementation reference | [compose_unstyled_reference.md](references/compose_unstyled_reference.md) |\n| component_token_customization_example.md | Customization via CompositionLocal | [component_token_customization_example.md](references/component_token_customization_example.md) |\n| troubleshooting.md | Common UI component issues and solutions | [troubleshooting.md](references/troubleshooting.md) |\n| [@kmp-architecture](../kmp-architecture/SKILL.md) | Architecture and development conventions | Architecture skill |\n\n## Troubleshooting Common Unstyled Component Issues\n\n### Clickable Component Not Responding\n\n**Symptom:** Card hover/press states work, but clicking does nothing.\n\n**Cause:** Missing `.clickable()` modifier despite having `MutableInteractionSource`.\n\n**Solution:**\n```kotlin\nColumn(\n    modifier = modifier\n        .clip(shape)\n        .border(...)\n        .clickable(  // ← REQUIRED for actual clicks\n            interactionSource = interactionSource,\n            indication = null,  // Or ripple effect\n            onClick = onClick\n        )\n        .hoverable(interactionSource = interactionSource)  // Only tracks hover\n        .padding(...)\n)\n```\n\n**Why:** `hoverable()` only tracks hover state, doesn''t make component clickable. Must add `.clickable()` separately.\n\n**Order matters:**\n1. `.clip()` - Define shape first\n2. `.border()` - Visual border\n3. `.clickable()` - Make clickable\n4. `.hoverable()` - Track hover state\n5. `.padding()` - Internal padding\n\n---\n\n### Hover Effects Too Subtle\n\n**Symptom:** Hover state implemented but barely visible.\n\n**Cause:** Minimal effect values (brightness 1.1, border alpha 0.2).\n\n**Solution for Unstyled theme:**\n```kotlin\nval brightness by animateFloatAsState(\n    targetValue = when {\n        isPressed -> 0.95f\n        isHovered -> 1.15f  // More noticeable (was 1.1)\n        else -> 1f\n    }\n)\n\nval borderAlpha by animateFloatAsState(\n    targetValue = when {\n        isPressed -> 0.3f\n        isHovered -> 0.5f   // More prominent (was 0.2)\n        else -> 0.2f\n    }\n)\n\nval scale by animateFloatAsState(\n    targetValue = when {\n        isPressed -> 0.98f\n        isHovered -> 1.02f  // Slight grow (was 1.0)\n        else -> 1f\n    }\n)\n```\n\n**Why:** Minimal effects match \"unstyled\" aesthetic but need sufficient visibility for usability.\n\n---\n"},"lastSynced":"2026-03-08T02:13:25.731Z","agentAnalysis":{"suitability":{"en":"Ideal for Kotlin Multiplatform Agents requiring headless component libraries for custom UI development and accessibility handling.","zh":"适用于需要无头组件库的Kotlin Multiplatform Agents进行自定义UI开发和无障碍处理。","ja":"Kotlin Multiplatform AgentsがカスタムUI開発とアクセシビリティの処理を必要とするヘッドレスコンポーネントライブラリに最適です。","ko":"커스텀 UI 개발 및 접근성 처리를 위해 헤드리스 컴포넌트 라이브러리가 필요한 Kotlin Multiplatform 에이전트에 적합합니다.","es":"Ideal para Agentes de Kotlin Multiplatform que requieren bibliotecas de componentes sin interfaz gráfica para el desarrollo de interfaces de usuario personalizadas y el manejo de accesibilidad.","fr":"Idéal pour les agents Kotlin Multiplatform nécessitant des bibliothèques de composants sans interface graphique pour le développement d''interfaces utilisateur personnalisées et la gestion de l''accessibilité.","de":"Ideal für Kotlin-Multiplatform-Agents, die Bibliotheken ohne Benutzeroberfläche für die Entwicklung von benutzerdefinierten Benutzeroberflächen und die Verarbeitung von Zugriffsmöglichkeiten erfordern.","pt":"Ideal para Agentes Kotlin Multiplatform que exigem bibliotecas de componentes headless para desenvolvimento de UI personalizado e tratamento de acessibilidade.","ru":"Идеально подходит для агентов Kotlin Multiplatform, требующих библиотек головных компонентов для разработки пользовательского интерфейса и обработки доступности.","ar":"مثالي لعميل Kotlin Multiplatform الذي يتطلب مكتبات مكونات بدون واجهة لتنمية واجهة المستخدم المخصصة ومعالجة إمكانية الوصول."},"recommendation":{"en":"Empowers agents to develop unstyled UI screens and custom themes using Kotlin Multiplatform project''s headless component library implementation patterns, handling UX logic, state, and accessibility while rendering no visual UI by default, utilizing DSLs like buildTheme or buildPlatformTheme.","zh":"使得代理能够使用Kotlin Multiplatform项目的无头组件库实现模式开发无样式UI屏幕和自定义主题，处理UX逻辑、状态和无障碍，同时默认不渲染视觉UI，利用诸如buildTheme或buildPlatformTheme的DSL。","ja":"エージェントがKotlin Multiplatformプロジェクトのヘッドレスコンポーネントライブラリの実装パターンを使用して、スタイルのないUI画面とカスタムテーマを開発し、UXロジック、状態、アクセシビリティを処理し、デフォルトで視覚的なUIをレンダリングしないようにし、buildThemeやbuildPlatformThemeなどのDSLを利用できるようにします。","ko":"에이전트가 Kotlin Multiplatform 프로젝트의 헤드리스 컴포넌트 라이브러리 구현 패턴을 사용하여 스타일이 없는 UI 화면과 커스텀 테ーマ를 개발하고 UX 논리, 상태 및 접근성을 처리하며 기본적으로 시각적 UI를 렌더링하지 않도록 하며 buildTheme 또는 buildPlatformTheme와 같은 DSL을 활용할 수 있도록 합니다.","es":"Habilita a los agentes para desarrollar pantallas de interfaz de usuario sin estilo y temas personalizados utilizando los patrones de implementación de la biblioteca de componentes sin interfaz gráfica del proyecto Kotlin Multiplatform, manejando la lógica de UX, el estado y la accesibilidad mientras se renderiza una interfaz de usuario sin visualización por defecto, utilizando DSL como buildTheme o buildPlatformTheme.","fr":"Permet aux agents de développer des écrans d''interface utilisateur sans style et des thèmes personnalisés en utilisant les modèles d''implémentation de la bibliothèque de composants sans interface graphique du projet Kotlin Multiplatform, en gérant la logique UX, l''état et l''accessibilité tout en rendant une interface utilisateur sans visualisation par défaut, en utilisant des DSL comme buildTheme ou buildPlatformTheme.","de":"Ermöglicht es Agenten, ungestaltete Benutzeroberflächenscreens und benutzerdefinierte Themen unter Verwendung der Implementierungsmuster der headless-Komponentenbibliothek des Kotlin-Multiplatform-Projekts zu entwickeln, wobei die UX-Logik, der Zustand und die Zugriffsmöglichkeiten gehandhabt und standardmäßig keine visuelle Benutzeroberfläche gerendert wird, unter Verwendung von DSLs wie buildTheme oder buildPlatformTheme.","pt":"Habilita os agentes a desenvolver telas de UI sem estilos e temas personalizados usando os padrões de implementação da biblioteca de componentes headless do projeto Kotlin Multiplatform, manipulando a lógica de UX, estado e acessibilidade enquanto renderiza nenhuma UI visual por padrão, utilizando DSLs como buildTheme ou buildPlatformTheme.","ru":"Наделяет агентов возможностью разрабатывать нестилизованные экраны UI и пользовательские темы, используя шаблоны реализации библиотеки головных компонентов проекта Kotlin Multiplatform, обрабатывая логику UX, состояние и доступность при отрисовке не визуального UI по умолчанию, используя DSL, такие как buildTheme или buildPlatformTheme.","ar":"يمنح العميل القدرة على تطوير شاشات واجهة المستخدم غير المنسقة وأفكار مخصصة باستخدام أنماط تنفيذ مكتبة المكونات بدون واجهة لمشروع Kotlin Multiplatform، معالجة منطق UX والحالة وإمكانية الوصول عند تقديم واجهة المستخدم غير المرئية افتراضيًا، باستخدام DSL مثل buildTheme أو buildPlatformTheme."},"useCases":{"en":["Building Unstyled UI screens in :features:<feature>:ui-unstyled modules","Configuring custom themes using buildTheme or buildPlatformTheme DSLs","Implementing headless components with custom styling for accessibility"],"zh":["在:features:<feature>:ui-unstyled模块中构建无样式UI屏幕","使用buildTheme或buildPlatformTheme DSL配置自定义主题","实现带有自定义样式的无头组件以进行无障碍访问"],"ja":[":features:<feature>:ui-unstyledモジュールでスタイルのないUI画面を構築する","buildThemeまたはbuildPlatformTheme DSLを使用してカスタムテーマを構成する","アクセシビリティのためにカスタムスタイル付きのヘッドレスコンポーネントを実装する"],"ko":[":features:<feature>:ui-unstyled 모듈에서 스타일이 없는 UI 화면을 구축하는 것","buildTheme 또는 buildPlatformTheme DSL을 사용하여 커스텀 테ーマ를 구성하는 것","접근성을 위해 커스텀 스타일이 있는 헤드리스 컴포넌트를 구현하는 것"],"es":["Creación de pantallas de interfaz de usuario sin estilo en módulos :features:<feature>:ui-unstyled","Configuración de temas personalizados utilizando DSL como buildTheme o buildPlatformTheme","Implementación de componentes sin interfaz gráfica con estilo personalizado para accesibilidad"],"fr":["Création d''écrans d''interface utilisateur sans style dans les modules :features:<feature>:ui-unstyled","Configuration de thèmes personnalisés en utilisant des DSL comme buildTheme ou buildPlatformTheme","Implémentation de composants sans interface graphique avec un style personnalisé pour l''accessibilité"],"de":["Erstellung von ungestalteten Benutzeroberflächenscreens in :features:<feature>:ui-unstyled-Modulen","Konfiguration von benutzerdefinierten Themen unter Verwendung von DSL wie buildTheme oder buildPlatformTheme","Implementierung von headless-Komponenten mit benutzerdefiniertem Stil für die Zugriffsmöglichkeiten"],"pt":["Construir telas de UI não estilizadas em módulos :features:<feature>:ui-unstyled","Configurar temas personalizados usando DSLs buildTheme ou buildPlatformTheme","Implementar componentes headless com estilização personalizada para acessibilidade"],"ru":["Создание нестилизованных экранов UI в модулях :features:<feature>:ui-unstyled","Настройка пользовательских тем, используя DSL buildTheme или buildPlatformTheme","Реализация головных компонентов с пользовательской стилизацией для доступности"],"ar":["بناء شاشات واجهة المستخدم غير المنسقة في وحدات :features:<feature>:ui-unstyled","تكوين مواضيع مخصصة باستخدام DSLs buildTheme أو buildPlatformTheme","تنفيذ مكونات بدون واجهة مع تنسيق مخصص للوصول"]},"limitations":{"en":["Requires Kotlin Multiplatform project setup","Limited to headless component library development"],"zh":["需要Kotlin Multiplatform项目设置","仅限无头组件库开发"],"ja":["Kotlin Multiplatformプロジェクトの設定が必要","ヘッドレスコンポーネントライブラリの開発に限定される"],"ko":["Kotlin Multiplatform 프로젝트 설정이 필요합니다","헤드리스 컴포넌트 라이브러리 개발에만 제한됩니다"],"es":["Requiere configuración del proyecto Kotlin Multiplatform","Limitado al desarrollo de bibliotecas de componentes sin interfaz gráfica"],"fr":["Nécessite une configuration du projet Kotlin Multiplatform","Limité au développement de bibliothèques de composants sans interface graphique"],"de":["Erfordert die Einrichtung des Kotlin-Multiplatform-Projekts","Begrenzt auf die Entwicklung von Bibliotheken ohne Benutzeroberfläche"],"pt":["Exige configuração do projeto Kotlin Multiplatform","Limitado ao desenvolvimento da biblioteca de componentes headless"],"ru":["Требует настройки проекта Kotlin Multiplatform","Ограничен разработкой библиотеки головных компонентов"],"ar":["يتطلب إعداد مشروع Kotlin Multiplatform","محدود بتطوير مكتبة المكونات بدون واجهة"]},"version":4},"contentHash":"8f2169753e158fc96b014b8fee8ff29e8ecde2e92b7748cfec306182c2c0c7eb","qualityScore":54}');
