INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('niltsiar/kotlin_multiplatform_pokedex/kmp-compose-unstyled', 'kmp-compose-unstyled', 'niltsiar', 'kotlin_multiplatform_pokedex', 'community', 'kmp-compose-unstyled niltsiar kotlin_multiplatform_pokedex community kmp-compose-unstyled is a Kotlin Multiplatform project for developing headless component libraries, handling UX logic and accessibility. It benefits developers building unstyled UI screens and custom themes. KMP Compose Unstyled是一个用于测试Kotlin Multiplatform应用开发的项目，提供无样式组件库实现 KMP Compose Unstyledは、Kotlin Multiplatformアプリを開発するための小さなプロジェクトです。ヘドレスコンポーネントライブラリの実装パターンを提供します KMP Compose Unstyled는 Kotlin Multiplatform 애플리케이션 개발을 테스트하기 위한 작은 프로젝트로, 헤드리스 컴포넌트 라이브러리 구현 패턴을 제공합니다 kmp-compose-unstyled es una biblioteca de componentes headless para aplicaciones Kotlin Multiplatform que maneja la lógica de UX, estado y accesibilidad sin renderizar una interfaz de usuario visual por defecto kmp-compose-unstyled est une bibliothèque de composants headless pour les applications Kotlin Multiplatform qui gère la logique UX, l''état et l''accessibilité sans rendre une interface utilisateur visuelle par défaut kmp-compose-unstyled ist eine Headless-Komponentenbibliothek für Kotlin-Multiplatform-Anwendungen, die die UX-Logik, den Zustand und die Zugänglichkeit ohne standardmäßige Darstellung einer visuellen Benutzeroberfläche verwaltet O kmp-compose-unstyled é uma biblioteca de componentes headless para aplicações Kotlin Multiplatform, permitindo a criação de UIs personalizadas e acessíveis kmp-compose-unstyled - это библиотека бесстойловых компонентов для приложений Kotlin Multiplatform, позволяющая создавать индивидуальные и доступные интерфейсы kmp-compose-unstyled هي مكتبة مكونات بدون أنماط ل تطبيقات Kotlin Multiplatform، مما يسمح بإنشاء واجهات مستخدم مخصصة وقابلة للوصول how to use kmp-compose-unstyled kmp-compose-unstyled alternative kmp-compose-unstyled setup guide what is kmp-compose-unstyled kmp-compose-unstyled vs Jetpack Compose kmp-compose-unstyled install kotlin multiplatform development headless component library unstyled UI screens KMP Compose Unstyled 无样式组件库 Kotlin Multiplatform UX逻辑 状态处理 可访问性 AI工具 跨平台应用开发 Building Unstyled UI screens in :features:<feature>:ui-unstyled modules Configuring Themes using buildTheme or buildPlatformTheme DSLs Implementing Headless Components with custom styling Ensuring Platform-specific accessibility Using Kotlin Multiplatform for cross-platform development kmp-compose-unstyled is a headless component library implementation for Kotlin Multiplatform apps, providing unstyled components for UX logic and accessibility.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('popup-studio-ai/bkit-codex/phase-2-convention', 'community', 'popup-studio-ai', 'bkit-codex', 'popup-studio-ai/bkit-codex', 'phase-2-convention', 0, 0, 54, '2026-03-08T01:57:15.621Z', '2026-03-08T02:13:30.201Z', '711f4d5c77853a8168dd741c82fb6dd429403ef0afd705f6d8368540e6454802', '{"id":"popup-studio-ai/bkit-codex/phase-2-convention","name":"phase-2-convention","description":{"en":"The phase-2-convention skill sets coding standards for AI-native development, benefiting developers by preventing confusion and reducing code review friction. It establishes rules for consistent conventions.","zh":"Phase 2 编码约定设置是 AI-native 开发的关键步骤，通过 PDCA 和 Context Engineering 实现高效开发","ja":"Phase 2 コーディング規約設定は AI ネイティブ開発の重要なステップで、PDCA とコンテキストエンジニアリングを実現","ko":"Phase 2 코딩 규약 설정은 AI 네이티브 개발의 중요한 단계로 PDCA와 컨텍스트 엔지니어링을 구현","es":"Phase 2 Convention es una herramienta para establecer convenciones de codificación en desarrollo de Agentes de IA, mejorando la colaboración y reduciendo la fricción en las revisiones de código","fr":"Phase 2 Convention est un outil pour établir des conventions de codage dans le développement d''outils d''IA, améliorant la collaboration et réduisant la friction dans les révisions de code","de":"Phase-2-Convention ist ein Tool zur Einrichtung von Codierkonventionen in der AI-Entwicklung, um die Zusammenarbeit zu verbessern und die Reibung bei Code-Reviews zu reduzieren","pt":"O Phase 2 Convention é uma ferramenta para estabelecer padrões de codificação para desenvolvimento AI-nativo. Ele utiliza o Vibecoding Kit para OpenAI Codex e segue o ciclo PDCA.","ru":"Phase 2 Convention — это инструмент для установления стандартов кодирования для ИИ-ориентированного развития. Он использует Vibecoding Kit для OpenAI Codex и следует циклу PDCA.","ar":"المرحلة 2 Convention هي أداة لتحديد معايير الترميز للتنمية الأصلية بالذكاء الاصطناعي. เธا تستخدم Vibecoding Kit لـ OpenAI Codex وتتبع دورة PDCA."},"seo":{"title":{"en":"phase-2-convention: Coding Standards Setup Guide | AI Age...","zh":"Phase 2 编码约定设置指南 - AIエージェント开发最佳实践","ja":"Phase 2 コーディング規約設定ガイド - AIエージェント開発のベストプラクティス","ko":"Phase 2 코딩 규약 설정 가이드 - AI 에이전트 개발 최적화","es":"Guía de configuración de Phase 2 Convention para Agentes ...","fr":"Guide de mise en place de la convention Phase 2 pour les ...","de":"Einrichtungsleitfaden für Phase-2-Convention in AI-Entwic...","pt":"Guia de Configuração do Phase 2 Convention para Desenvolv...","ru":"Настройка Phase 2 Convention для ИИ-ориентированного разв...","ar":"دليل إعداد المرحلة 2 Convention للتنمية الأصلية بالذكاء ا..."},"description":{"en":"Discover how to establish consistent coding conventions with phase-2-convention. Get started with the $phase-2-convention start command and reduce code revie...","zh":"了解 Phase 2 编码约定设置，实现 AI-native 开发的 PDCA 和 Context Engineering","ja":"Phase 2 コーディング規約設定について学び、AI ネイティブ開発の PDCA とコンテキストエンジニアリングを実現","ko":"Phase 2 코딩 규약 설정에 대해 알아보고 AI 네이티브 개발의 PDCA와 컨텍스트 엔지니어링을 구현","es":"Aprende a establecer convenciones de codificación para Agentes de IA con Phase 2 Convention y mejora la colaboración en desarrollo","fr":"Découvrez comment établir des conventions de codage pour les outils d''IA avec Phase 2 Convention et améliorez la collaboration en développement","de":"Erfahren Sie, wie Sie mit Phase-2-Convention Codierkonventionen für AI-Entwicklung einrichten und die Zusammenarbeit verbessern","pt":"Aprenda a configurar o Phase 2 Convention para desenvolvimento AI-nativo com o Vibecoding Kit para OpenAI Codex","ru":"Узнайте, как настроить Phase 2 Convention для ИИ-ориентированного развития с помощью Vibecoding Kit для OpenAI Codex","ar":"تعرف على كيفية تهيئة المرحلة 2 Convention للتنمية الأصلية بالذكاء الاصطناعي باستخدام Vibecoding Kit ل OpenAI Codex"},"definition":{"en":"phase-2-convention is a coding standard setup guide that prevents confusion and reduces code review friction through consistent conventions for human and AI developers","zh":"Phase 2 编码约定设置是一种 AI-native 开发方法，通过建立编码标准和规约来实现高效开发","ja":"Phase 2 コーディング規約設定は、AI ネイティブ開発方法の一つで、コーディング規約を設定して効率的な開発を実現","ko":"Phase 2 코딩 규약 설정은 AI 네이티브 개발 방법 중 하나로 코딩 규약을 설정하여 효율적인 개발을 구현","es":"Phase 2 Convention es una herramienta de Agentes de IA que establece convenciones de codificación para mejorar la colaboración en desarrollo","fr":"Phase 2 Convention est un outil d''IA qui établit des conventions de codage pour améliorer la collaboration en développement","de":"Phase-2-Convention ist ein AI-Tool, das Codierkonventionen zur Verbesserung der Zusammenarbeit in der Entwicklung einrichtet","pt":"O que é Phase 2 Convention? É uma ferramenta para estabelecer padrões de codificação para desenvolvimento AI-nativo.","ru":"Что такое Phase 2 Convention? Это инструмент для установления стандартов кодирования для ИИ-ориентированного развития.","ar":"ما هي المرحلة 2 Convention؟ هي أداة لتحديد معايير الترميز للتنمية الأصلية بالذكاء الاصطناعي."},"features":{"en":["Initializes Phase 2 with the $phase-2-convention start command","Generates convention documentation using the $phase-2-convention generate command","Checks convention compliance with the $phase-2-convention lint command","Establishes consistent coding standards for AI-native development","Prevents confusion and reduces code review friction through PDCA and Context Engineering"],"zh":["支持 PDCA 和 Context Engineering","提供编码标准和规约设置","实现高效开发和代码复用","支持多种开发语言和框架","提供代码检查和 lint 功能"],"ja":["PDCA とコンテキストエンジニアリングをサポート","コーディング規約を設定","効率的な開発とコードの再利用を実現","多くの開発言語とフレームワークをサポート","コードチェックと lint 機能を提供"],"ko":["PDCA와 컨텍스트 엔지니어링을 지원","코딩 규약을 설정","효율적인 개발과 코드 재사용을 구현","다수의 개발 언어와 프레임워크를 지원","코드 체크와 lint 기능을 제공"],"es":["Establece convenciones de codificación para desarrollo de Agentes de IA","Genera documentos de convención con el comando `$phase-2-convention generate`","Verifica la conformidad con las convenciones con el comando `$phase-2-convention lint`","Mejora la colaboración en desarrollo mediante convenciones de codificación consistentes","Reduce la fricción en las revisiones de código mediante convenciones claras"],"fr":["Établit des conventions de codage pour le développement d''outils d''IA","Génère des documents de convention avec la commande `$phase-2-convention generate`","Vérifie la conformité aux conventions avec la commande `$phase-2-convention lint`","Améliore la collaboration en développement grâce à des conventions de codage cohérentes","Réduit la friction dans les révisions de code grâce à des conventions claires"],"de":["Richtet Codierkonventionen für die AI-Entwicklung ein","Generiert Konventionsdokumente mit dem Befehl `$phase-2-convention generate`","Überprüft die Konformität mit den Konventionen mit dem Befehl `$phase-2-convention lint`","Verbessert die Zusammenarbeit in der Entwicklung durch konsistente Codierkonventionen","Reduziert die Reibung bei Code-Reviews durch klare Konventionen"],"pt":["Estabelece padrões de codificação para desenvolvimento AI-nativo","Utiliza o Vibecoding Kit para OpenAI Codex","Segue o ciclo PDCA","Comando `start` para iniciar a fase 2","Comando `generate` para gerar documento de convenção","Comando `lint` para verificar conformidade com a convenção"],"ru":["Устанавливает стандарты кодирования для ИИ-ориентированного развития","Использует Vibecoding Kit для OpenAI Codex","Следует циклу PDCA","Команда `start` для начала фазы 2","Команда `generate` для генерации документа конвенции","Команда `lint` для проверки соответствия конвенции"],"ar":["تحديد معايير الترميز للتنمية الأصلية بالذكاء الاصطناعي","استخدام Vibecoding Kit لـ OpenAI Codex","متابعة دورة PDCA","الأمر `start` لبدء المرحلة 2","الأمر `generate` لتوليد وثيقة الاتفاقية","الأمر `lint` للتحقق من مطابقة الاتفاقية"]},"keywords":{"en":["how to use phase-2-convention","phase-2-convention setup guide","what is phase-2-convention","phase-2-convention alternative","phase-2-convention vs Vibecoding Kit","phase-2-convention install","PDCA for AI development","Context Engineering for coding standards"],"zh":["AIエージェント开发","Phase 2 编码约定设置","PDCA","Context Engineering","AI-native 开发","编码标准","代码检查","lint"],"ja":["AIエージェント開発","Phase 2 コーディング規約設定","PDCA","コンテキストエンジニアリング","AI ネイティブ開発","コーディング規約","コードチェック","lint"],"ko":["AI 에이전트 개발","Phase 2 코딩 규약 설정","PDCA","컨텍스트 엔지니어링","AI 네이티브 개발","코딩 규약","코드 체크","lint"],"es":["Agentes de IA","convenciones de codificación","desarrollo de software","colaboración en desarrollo","revisiones de código","Phase 2 Convention","herramientas de desarrollo","IA nativa","PDCA"],"fr":["outils d''IA","conventions de codage","développement de logiciels","collaboration en développement","révisions de code","Phase 2 Convention","outils de développement","IA native","PDCA"],"de":["AI-Tools","Codierkonventionen","Software-Entwicklung","Zusammenarbeit in der Entwicklung","Code-Reviews","Phase-2-Convention","Entwicklungstools","native AI","PDCA"],"pt":["Phase 2 Convention","desenvolvimento AI-nativo","Vibecoding Kit","OpenAI Codex","PDCA","padrões de codificação","ferramentas de desenvolvimento AI"],"ru":["Phase 2 Convention","ИИ-ориентированное развитие","Vibecoding Kit","OpenAI Codex","PDCA","стандарты кодирования","инструменты разработки ИИ"],"ar":["المرحلة 2 Convention","التنمية الأصلية بالذكاء الاصطناعي","Vibecoding Kit","OpenAI Codex","PDCA","معايير الترميز","أدوات التنمية الذكاء الاصطناعي"]}},"owner":"popup-studio-ai","repo":"bkit-codex","repoPath":"popup-studio-ai/bkit-codex","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.621Z","topics":[],"category":"community","skillMd":{"name":"phase-2-convention","description":"|","bodyPreview":"# Phase 2: Coding Conventions\n\n> Establish coding standards before writing application code.\n\n## Purpose\n\nPhase 2 sets the rules everyone (human and AI) follows. Consistent conventions prevent confusion and reduce code review friction.\n\n## Actions\n\n| Action | Description | Example |\n|--------|-------------|---------|\n| `start` | Begin Phase 2 | `$phase-2-convention start` |\n| `generate` | Generate convention doc | `$phase-2-convention generate` |\n| `lint` | Check convention compliance | `$phase-","body":"# Phase 2: Coding Conventions\n\n> Establish coding standards before writing application code.\n\n## Purpose\n\nPhase 2 sets the rules everyone (human and AI) follows. Consistent conventions prevent confusion and reduce code review friction.\n\n## Actions\n\n| Action | Description | Example |\n|--------|-------------|---------|\n| `start` | Begin Phase 2 | `$phase-2-convention start` |\n| `generate` | Generate convention doc | `$phase-2-convention generate` |\n| `lint` | Check convention compliance | `$phase-2-convention lint` |\n\n## Deliverables\n\n1. **Convention Document** - `docs/01-plan/convention.md`\n2. **ESLint/Prettier Config** - Automated enforcement\n3. **File Naming Rules** - Directory and file naming patterns\n4. **Component Naming Rules** - UI component conventions\n5. **Git Commit Conventions** - Commit message format\n\n## Process\n\n### Step 1: Language & Framework Conventions\n\n```markdown\n## TypeScript Conventions\n- Strict mode enabled\n- No `any` type (use `unknown` if needed)\n- Interfaces over Types for object shapes\n- Enum for fixed value sets\n- Async/await over .then() chains\n```\n\n### Step 2: Naming Rules\n\n| Element | Convention | Example |\n|---------|-----------|---------|\n| Files (components) | PascalCase | `UserProfile.tsx` |\n| Files (utilities) | camelCase | `formatDate.ts` |\n| Files (styles) | kebab-case | `user-profile.module.css` |\n| Variables | camelCase | `userName`, `isActive` |\n| Constants | UPPER_SNAKE | `MAX_RETRY_COUNT` |\n| Types/Interfaces | PascalCase | `UserProfile`, `ApiResponse` |\n| Hooks | camelCase with use | `useAuth`, `useQuery` |\n| Components | PascalCase | `UserCard`, `NavBar` |\n| API routes | kebab-case | `/api/user-profile` |\n| Database | snake_case | `user_profile`, `created_at` |\n\n### Step 3: Directory Structure Rules\n\n- Group by feature, not by type\n- Max 3 levels deep\n- index.ts for barrel exports\n- __tests__/ next to source files\n\n### Step 4: Git Conventions\n\n```\n<type>(<scope>): <description>\n\nTypes: feat, fix, docs, style, refactor, test, chore\nScope: component or module name\nDescription: imperative mood, lowercase, no period\n\nExamples:\n- feat(auth): add social login support\n- fix(api): handle null response from user endpoint\n```\n\n### Step 5: Code Style Enforcement\n\n```json\n{\n  \"extends\": [\"next/core-web-vitals\", \"prettier\"],\n  \"rules\": {\n    \"no-console\": \"warn\",\n    \"no-unused-vars\": \"error\",\n    \"@typescript-eslint/no-explicit-any\": \"error\"\n  }\n}\n```\n\n## Convention Patterns\n\nSee `references/naming-conventions.md` for detailed patterns.\n\n## Output Location\n\n```\ndocs/01-plan/\n├── convention.md      # Full convention document\nproject/\n├── .eslintrc.json     # ESLint config\n├── .prettierrc        # Prettier config\n└── .editorconfig      # Editor config\n```\n\n## Next Phase\n\nWhen conventions are established, proceed to **$phase-3-mockup** for UI/UX design.\n\n## Common Mistakes\n\n| Mistake | Solution |\n|---------|----------|\n| No automated enforcement | Set up ESLint + Prettier from day 1 |\n| Too many rules | Start minimal, add rules as needed |\n| Inconsistent naming | Use a naming decision table |\n| No commit conventions | Use commitlint with husky |\n| Mixing conventions | One language = one convention set |\n"},"lastSynced":"2026-03-08T02:13:30.201Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing standardized coding conventions and compliance checks.","zh":"非常适合需要标准化编码约定和合规性检查的代码审查代理。","ja":"コードレビューエージェントが標準化されたコーディング規約とコンプライアンスチェックを必要とする場合に最適です。","ko":"標準화된 코딩 규약과 컴플라이언스 체크가 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan convenciones de codificación estandarizadas y controles de cumplimiento.","fr":"Parfait pour les agents de révision de code nécessitant des conventions de codage standardisées et des vérifications de conformité.","de":"Perfekt für Code-Review-Agents, die standardisierte Codierkonventionen und Compliance-Checks benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de convenções de codificação padronizadas e verificações de conformidade.","ru":"Идеально подходит для агентов проверки кода, требующих стандартизированных соглашений по кодированию и проверок соответствия.","ar":"مثالي للوكلاء المراجعة البرمجية الذين يحتاجون إلى اتفاقيات برمجة معيارية وفحوصات مطابقة."},"recommendation":{"en":"Empowers agents to establish and enforce consistent coding standards, reducing code review friction and preventing confusion through automated linting and convention documentation generation using protocols like command-line interfaces.","zh":"赋予代理建立和执行一致的编码标准的能力，通过自动linting和使用命令行接口等协议生成约定文档，减少代码审查摩擦，防止混淆。","ja":"エージェントが一貫したコーディング規約を確立し、実施する能力を与え、コマンドラインインターフェースなどのプロトコルを使用した自動lintingと規約ドキュメントの生成により、コードレビューの摩擦を減らし、混乱を防ぎます。","ko":"에이전트가 일관된 코딩 표준을 설정하고 시행할 수 있는 능력을 부여하여, 명령행 인터페이스와 같은 프로토콜을 사용한 자동 linting 및 규약 문서 생성을 통해 코드 리뷰의 마찰을 줄이고混淆를 방지합니다.","es":"Habilita a los agentes a establecer y hacer cumplir estándares de codificación coherentes, reduciendo la fricción de revisión de código y evitando confusiones a través de la generación automática de documentación de convenciones y protocolos como interfaces de línea de comandos.","fr":"Permet aux agents d''établir et de faire respecter des normes de codage cohérentes, réduisant ainsi la friction lors de la révision de code et prévenant les confusions grâce à la génération automatique de documentation de conventions et de protocoles tels que les interfaces de ligne de commande.","de":"Ermächtigt die Agenten, konsistente Codierstandards zu etablieren und durchzusetzen, wodurch die Reibung bei der Code-Überprüfung reduziert und Verwirrung durch automatisierte Erstellung von Konventionsdokumentation und Protokollen wie der Kommandozeilen-Schnittstelle vermieden wird.","pt":"Habilita os agentes a estabelecer e aplicar padrões de codificação consistentes, reduzindo a fricção da revisão de código e prevenindo confusões por meio da criação automatizada de documentação de convenções e linting usando protocolos como interfaces de linha de comando.","ru":"Наделяет агентов возможностью устанавливать и обеспечивать последовательные стандарты кодирования, снижая трение при проверке кода и предотвращая путаницу за счет автоматизированного создания документации по соглашениям и линтинга с использованием протоколов, таких как командные интерфейсы.","ar":"يمنح الوكلاء القدرة على إنشاء معايير برمجة متسقة وتطبيقها، وتقليل الاحتكاك في مراجعة الشفرة ومنع الارتباك من خلال إنشاء تلقائي لوثائق الاتفاقيات وlinting باستخدام بروتوكولات مثل واجهات سطر الأوامر."},"useCases":{"en":["Generating convention documentation","Checking code compliance with established conventions","Automating code review processes"],"zh":["生成约定文档","检查代码是否符合既定的约定","自动化代码审查过程"],"ja":["規約ドキュメントの生成","コードが既定の規約に従っているかどうかの確認","コードレビューの自動化"],"ko":["규약 문서 생성","코드가 정해진 규약을 따르는지 확인","코드 리뷰 프로세스 자동화"],"es":["Generación de documentación de convenciones","Comprobación del cumplimiento del código con las convenciones establecidas","Automatización de procesos de revisión de código"],"fr":["Génération de documentation de conventions","Vérification de la conformité du code avec les conventions établies","Automatisation des processus de révision de code"],"de":["Generierung von Konventionsdokumentation","Überprüfung der Code-Einhaltung mit etablierten Konventionen","Automatisierung von Code-Überprüfungsprozessen"],"pt":["Geração de documentação de convenção","Verificação da conformidade do código com convenções estabelecidas","Automatização de processos de revisão de código"],"ru":["Генерация документации по соглашениям","Проверка соответствия кода установленным соглашениям","Автоматизация процессов проверки кода"],"ar":["توليد وثائق الاتفاقية","فحص مطابقة الشفرة للاتفاقيات المحددة","تأتمة عمليات مراجعة الشفرة"]},"limitations":{"en":["Requires initial convention setup","Limited to coding standards enforcement"],"zh":["需要初始约定设置","仅限于编码标准的执行"],"ja":["初期の規約設定が必要","コーディング規約の実施に限定される"],"ko":["초기 규약 설정이 필요","코딩 표준 시행에만 제한됨"],"es":["Requiere configuración inicial de convenciones","Limitado a la aplicación de normas de codificación"],"fr":["Nécessite une configuration initiale des conventions","Limité à l''application des normes de codage"],"de":["Benötigt eine anfängliche Konventionseinstellung","Begrenzt auf die Durchsetzung von Codierstandards"],"pt":["Requer configuração inicial de convenção","Limitado à aplicação de padrões de codificação"],"ru":["Требует первоначальной настройки соглашения","Ограничен обеспечением стандартов кодирования"],"ar":["يتطلب إعداد اتفاقية أولي","محدود بإنفاذ معايير البرمجة"]},"version":4},"contentHash":"711f4d5c77853a8168dd741c82fb6dd429403ef0afd705f6d8368540e6454802","qualityScore":54}');
