INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('popup-studio-ai/bkit-codex/phase-2-convention', 'phase-2-convention', 'popup-studio-ai', 'bkit-codex', 'community', 'phase-2-convention popup-studio-ai bkit-codex community The phase-2-convention skill sets coding standards for AI-native development, benefiting developers by preventing confusion and reducing code review friction. It establishes rules for consistent conventions. Phase 2 编码约定设置是 AI-native 开发的关键步骤，通过 PDCA 和 Context Engineering 实现高效开发 Phase 2 コーディング規約設定は AI ネイティブ開発の重要なステップで、PDCA とコンテキストエンジニアリングを実現 Phase 2 코딩 규약 설정은 AI 네이티브 개발의 중요한 단계로 PDCA와 컨텍스트 엔지니어링을 구현 Phase 2 Convention es una herramienta para establecer convenciones de codificación en desarrollo de Agentes de IA, mejorando la colaboración y reduciendo la fricción en las revisiones de código Phase 2 Convention est un outil pour établir des conventions de codage dans le développement d''outils d''IA, améliorant la collaboration et réduisant la friction dans les révisions de code Phase-2-Convention ist ein Tool zur Einrichtung von Codierkonventionen in der AI-Entwicklung, um die Zusammenarbeit zu verbessern und die Reibung bei Code-Reviews zu reduzieren O Phase 2 Convention é uma ferramenta para estabelecer padrões de codificação para desenvolvimento AI-nativo. Ele utiliza o Vibecoding Kit para OpenAI Codex e segue o ciclo PDCA. Phase 2 Convention — это инструмент для установления стандартов кодирования для ИИ-ориентированного развития. Он использует Vibecoding Kit для OpenAI Codex и следует циклу PDCA. المرحلة 2 Convention هي أداة لتحديد معايير الترميز للتنمية الأصلية بالذكاء الاصطناعي. เธا تستخدم Vibecoding Kit لـ OpenAI Codex وتتبع دورة PDCA. how to use phase-2-convention phase-2-convention setup guide what is phase-2-convention phase-2-convention alternative phase-2-convention vs Vibecoding Kit phase-2-convention install PDCA for AI development Context Engineering for coding standards AIエージェント开发 Phase 2 编码约定设置 PDCA Context Engineering AI-native 开发 编码标准 代码检查 lint Initializes Phase 2 with the $phase-2-convention start command Generates convention documentation using the $phase-2-convention generate command Checks convention compliance with the $phase-2-convention lint command Establishes consistent coding standards for AI-native development Prevents confusion and reduces code review friction through PDCA and Context Engineering phase-2-convention is a coding standard setup guide that prevents confusion and reduces code review friction through consistent conventions for human and AI developers');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('teradata-labs/claude-cookbooks/td-svm', 'community', 'teradata-labs', 'claude-cookbooks', 'teradata-labs/claude-cookbooks', 'td-svm', 0, 0, 54, '2026-03-08T01:57:15.641Z', '2026-03-08T02:13:41.934Z', '3227c0035f2da6e847d8dbcf0cdcd83a9f0cb9ec764854b0f6b3558e4536e3a4', '{"id":"teradata-labs/claude-cookbooks/td-svm","name":"td-svm","description":{"en":"The td-svm skill provides a comprehensive analytical workflow for linear and non-linear classification using Support Vector Machine. It benefits data scientists and analysts working with Teradata.","zh":"td-svm 是一个 Teradata 支持向量机的集合，提供了从数据探索到模型部署的完整分析工作流","ja":"td-svm は Teradata サポートベクターマシンのコレクションであり、データの探索からモデルへのデプロイまでの完全な分析ワークフローを提供","ko":"td-svm은 Teradata 지원 벡터 머신의 컬렉션으로, 데이터 탐색에서 모델 배포까지 완전한 분석 워크플로우를 제공","es":"TD_SVM es una colección de notebooks que muestra formas efectivas de utilizar AI con Teradata para clasificación lineal y no lineal. Ofrece un flujo de trabajo analítico completo con preprocessamiento automatizado","fr":"TD_SVM est une collection de notebooks qui montre des façons efficaces d''utiliser l''IA avec Teradata pour la classification linéaire et non linéaire. Il offre un flux de travail analytique complet avec un preprocessamiento automatisé","de":"TD_SVM ist eine Sammlung von Notebooks, die effektive Wege zur Nutzung von KI mit Teradata für lineare und nichtlineare Klassifizierung zeigt. Es bietet einen vollständigen analytischen Workflow mit automatisierter Vorverarbeitung","pt":"O TD_SVM é uma coleção de notebooks que demonstram formas eficazes de usar AI com Teradata para análise de classificação. Oferece pré-processamento automático e implementação avançada do TD_SVM","ru":"TD_SVM - это коллекция ноутбуков, демонстрирующих эффективные способы использования ИИ с Teradata для классификации. Предоставляет автоматическую предварительную обработку и продвинутую реализацию TD_SVM","ar":"TD_SVM هو مجموعة من الدفاتر التي تظهر طرقًا فعالة لاستخدام الذكاء الاصطناعي مع Teradata لتحليل التصنيف. يقدم معالجة أولية آلية وتنفيذا متقدمًا لـ TD_SVM"},"seo":{"title":{"en":"td-svm: Advanced Support Vector Machine Setup Guide | AI ...","zh":"td-svm 设置指南：Teradata 支持向量机实现","ja":"td-svm セットアップガイド：Teradata サポートベクターマシン","ko":"td-svm 설정 가이드: Teradata 지원 벡터 머신","es":"Guía de configuración de TD_SVM para clasificación avanzada","fr":"Guide de mise en place de TD_SVM pour une classification ...","de":"Einrichtungsleitfaden für TD_SVM zur erweiterten Klassifi...","pt":"Guia de Configuração do TD_SVM para Análise de Classificação","ru":"Настройка TD_SVM для классификации с помощью ИИ Агентов","ar":"دليل إعداد TD_SVM لتحليل التصنيف باستخدام أدوات الذكاء ال..."},"description":{"en":"Unlock efficient classification analytics with td-svm. Explore notebooks, automate preprocessing, and deploy models with ease. Get started now!","zh":"了解 td-svm 的功能和特点，掌握 Teradata 支持向量机的高级实现和自动预处理","ja":"td-svm の機能と特徴を学び、Teradata サポートベクターマシンの高度な実装と自動前処理をマスター","ko":"td-svm의 기능과 특징을 배우고, Teradata 지원 벡터 머신의 고급 구현과 자동 전처리를 마스터","es":"Aprende a utilizar TD_SVM para clasificación lineal y no lineal con Teradata. Descubre cómo implementar un flujo de trabajo analítico completo con preprocess...","fr":"Découvrez comment utiliser TD_SVM pour la classification linéaire et non linéaire avec Teradata. Apprenez à mettre en place un flux de travail analytique com...","de":"Erfahren Sie, wie Sie TD_SVM für lineare und nichtlineare Klassifizierung mit Teradata verwenden. Entdecken Sie, wie Sie einen vollständigen analytischen Wor...","pt":"Aprenda a utilizar o TD_SVM para análise de classificação linear e não linear com Teradata. Descubra como implementar workflows analíticos completos","ru":"Узнайте, как использовать TD_SVM для классификации с помощью ИИ Агентов и Teradata. Откройте для себя возможности полных аналитических рабочих процессов","ar":"تعرف على كيفية استخدام TD_SVM لتحليل التصنيف الخطي وغير الخطي مع Teradata. اكتشف كيفية تنفيذ سير عمل تحليلي كامل"},"definition":{"en":"td-svm is a collection of notebooks and recipes for effective AI-driven classification analytics with Teradata Support Vector Machine.","zh":"td-svm 是一种用于线性和非线性分类的 Teradata 支持向量机","ja":"td-svm は線形および非線形分類のための Teradata サポートベクターマシン","ko":"td-svm은 선형 및 비선형 분류를 위한 Teradata 지원 벡터 머신","es":"TD_SVM es un conjunto de herramientas de aprendizaje automático para clasificación lineal y no lineal con Teradata","fr":"TD_SVM est un ensemble d''outils de machine learning pour la classification linéaire et non linéaire avec Teradata","de":"TD_SVM ist eine Sammlung von Machine-Learning-Tools für lineare und nichtlineare Klassifizierung mit Teradata","pt":"O TD_SVM é uma ferramenta de classificação que utiliza Máquinas de Vetor de Suporte para análise de classificação linear e não linear","ru":"TD_SVM - это инструмент классификации, использующий Машины Вектора Поддержки для классификации с помощью ИИ Агентов","ar":"TD_SVM هو أداة تصنيف تستخدم آلات المتجهات الداعمة لتحليل التصنيف الخطي وغير الخطي"},"features":{"en":["Complete analytical workflow from data exploration to model deployment","Automated preprocessing including scaling, encoding, and train-test splitting","Advanced TD_SVM implementation for linear and non-linear classification","Supports data exploration and model deployment using Teradata","Enables automated preprocessing for efficient data preparation"],"zh":["完整的分析工作流","自动预处理，包括缩放、编码和训练-测试分割","高级 Teradata 支持向量机实现","支持线性和非线性分类","数据探索和模型部署"],"ja":["完全な分析ワークフロー","自動前処理、スケーリング、エンコーディング、トレーニング-テスト分割を含む","高度な Teradata サポートベクターマシンの実装","線形および非線形分類のサポート","データの探索とモデルへのデプロイ"],"ko":["완전한 분석 워크플로우","자동 전처리, 스케일링, 인코딩, 훈련-테스트 분할 등을 포함","고급 Teradata 지원 벡터 머신 구현","선형 및 비선형 분류 지원","데이터 탐색 및 모델 배포"],"es":["Flujo de trabajo analítico completo desde la exploración de datos hasta la implementación del modelo","Preprocessamiento automatizado, incluyendo escalado, codificación y división de entrenamiento y prueba","Implementación avanzada de TD_SVM para clasificación lineal y no lineal","Soporte para clasificación de datos con Teradata","Capacidad para realizar análisis de datos complejos con facilidad"],"fr":["Flux de travail analytique complet de l''exploration des données à la mise en place du modèle","Prétraitement automatisé, incluant la mise à l''échelle, la codification et la division de l''entraînement et de la vérification","Mise en place avancée de TD_SVM pour la classification linéaire et non linéaire","Prise en charge de la classification de données avec Teradata","Capacité à effectuer des analyses de données complexes avec facilité"],"de":["Vollständiger analytischer Workflow von der Datenexploration bis zur Modellimplementierung","Automatisierte Vorverarbeitung, einschließlich Skalierung, Kodierung und Aufteilung von Trainings- und Testdaten","Erweiterte Implementierung von TD_SVM für lineare und nichtlineare Klassifizierung","Unterstützung für die Klassifizierung von Daten mit Teradata","Fähigkeit, komplexe Datenanalysen mit Leichtigkeit durchzuführen"],"pt":["Fluxo de trabalho analítico completo","Pré-processamento automático","Implementação avançada do TD_SVM","Classificação linear e não linear"],"ru":["Полный аналитический рабочий процесс","Автоматическая предварительная обработка","Продвинутая реализация TD_SVM","Линейная и нелинейная классификация"],"ar":["سير عمل تحليلي كامل","معالجة أولية آلية","تنفيذ متقدم لـ TD_SVM","تصنيف خطي وغير خطي"]},"keywords":{"en":["how to use td-svm","td-svm alternative","td-svm setup guide","what is td-svm","td-svm vs scikit-learn","td-svm install","Teradata Support Vector Machine","classification analytics with td-svm"],"zh":["td-svm","Teradata 支持向量机","AI 에이전트","支持向量机","线性分类","非线性分类","自动预处理","数据探索","模型部署"],"ja":["td-svm","Teradata サポートベクターマシン","AI エージェント","サポートベクターマシン","線形分類","非線形分類","自動前処理","データの探索","モデルへのデプロイ"],"ko":["td-svm","Teradata 지원 벡터 머신","AI 에이전트","지원 벡터 머신","선형 분류","비선형 분류","자동 전처리","데이터 탐색","모델 배포"],"es":["td-svm","clasificación lineal","clasificación no lineal","teradata","herramientas de aprendizaje automático","flujo de trabajo analítico","preprocessamiento automatizado","análisis de datos complejos"],"fr":["td-svm","classification linéaire","classification non linéaire","teradata","outils de machine learning","flux de travail analytique","prétraitement automatisé","analyses de données complexes"],"de":["td-svm","lineare Klassifizierung","nichtlineare Klassifizierung","teradata","Machine-Learning-Tools","analytischer Workflow","automatisierte Vorverarbeitung","komplexe Datenanalysen"],"pt":["td-svm","análise de classificação","máquinas de vetor de suporte","teradata","ai para análise de dados","ferramentas de ai","td_svm setup","td_svm guia"],"ru":["td-svm","классификация","машины вектора поддержки","teradata","ии агенты","инструменты ии","td_svm настройка","td_svm руководство"],"ar":["td-svm","تحليل التصنيف","آلات المتجهات الداعمة","teradata","أدوات الذكاء الاصطناعي","أدوات اي","إعداد td_svm","دليل td_svm"]}},"owner":"teradata-labs","repo":"claude-cookbooks","repoPath":"teradata-labs/claude-cookbooks","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.641Z","topics":[],"category":"community","skillMd":{"name":"td-svm","description":"Support Vector Machine for linear and non-linear classification","bodyPreview":"# Teradata Support Vector Machine\n\n| **Skill Name** | Teradata Support Vector Machine |\n|----------------|--------------|\n| **Description** | Support Vector Machine for linear and non-linear classification |\n| **Category** | Classification Analytics |\n| **Function** | TD_SVM |\n\n## Core Capabilities\n\n- **Complete analytical workflow** from data exploration to model deployment\n- **Automated preprocessing** including scaling, encoding, and train-test splitting\n- **Advanced TD_SVM implementation** w","body":"# Teradata Support Vector Machine\n\n| **Skill Name** | Teradata Support Vector Machine |\n|----------------|--------------|\n| **Description** | Support Vector Machine for linear and non-linear classification |\n| **Category** | Classification Analytics |\n| **Function** | TD_SVM |\n\n## Core Capabilities\n\n- **Complete analytical workflow** from data exploration to model deployment\n- **Automated preprocessing** including scaling, encoding, and train-test splitting\n- **Advanced TD_SVM implementation** with parameter optimization\n- **Comprehensive evaluation metrics** and model validation\n- **Production-ready SQL generation** with proper table management\n- **Error handling and data quality checks** throughout the pipeline\n- **Business-focused interpretation** of analytical results\n\n## Table Analysis Workflow\n\nThis skill automatically analyzes your provided table to generate optimized SQL workflows. Here''s how it works:\n\n### 1. Table Structure Analysis\n- **Column Detection**: Automatically identifies all columns and their data types\n- **Data Type Classification**: Distinguishes between numeric, categorical, and text columns\n- **Primary Key Identification**: Detects unique identifier columns\n- **Missing Value Assessment**: Analyzes data completeness\n\n### 2. Feature Engineering Recommendations\n- **Numeric Features**: Identifies columns suitable for scaling and normalization\n- **Categorical Features**: Detects columns requiring encoding (one-hot, label encoding)\n- **Target Variable**: Helps identify the dependent variable for modeling\n- **Feature Selection**: Recommends relevant features based on data types\n\n### 3. SQL Generation Process\n- **Dynamic Column Lists**: Generates column lists based on your table structure\n- **Parameterized Queries**: Creates flexible SQL templates using your table schema\n- **Table Name Integration**: Replaces placeholders with your actual table names\n- **Database Context**: Adapts to your database and schema naming conventions\n\n## How to Use This Skill\n\n1. **Provide Your Table Information**:\n   ```\n   \"Analyze table: database_name.table_name\"\n   or\n   \"Use table: my_data with target column: target_var\"\n   ```\n\n2. **The Skill Will**:\n   - Query your table structure using `SHOW COLUMNS FROM table_name`\n   - Analyze data types and suggest appropriate preprocessing\n   - Generate complete SQL workflow with your specific column names\n   - Provide optimized parameters based on your data characteristics\n\n## Input Requirements\n\n### Data Requirements\n- **Source table**: Teradata table with analytical data\n- **Target column**: Dependent variable for classification analysis\n- **Feature columns**: Independent variables (numeric and categorical)\n- **ID column**: Unique identifier for record tracking\n- **Minimum sample size**: 100+ records for reliable classification modeling\n\n### Technical Requirements\n- **Teradata Vantage** with ClearScape Analytics enabled\n- **Database permissions**: CREATE, DROP, SELECT on working database\n- **Function access**: TD_SVM, SVMSparsePredict\n\n## Output Formats\n\n### Generated Tables\n- **Preprocessed data tables** with proper scaling and encoding\n- **Train/test split tables** for model validation\n- **Model table** containing trained TD_SVM parameters\n- **Prediction results** with confidence metrics\n- **Evaluation metrics** table with performance statistics\n\n### SQL Scripts\n- **Complete workflow scripts** ready for execution\n- **Parameterized queries** for different datasets\n- **Table management** with proper cleanup procedures\n\n## Classification Use Cases Supported\n\n1. **Non-linear classification**: Comprehensive analysis workflow\n2. **High-dimensional data**: Comprehensive analysis workflow\n3. **Kernel methods**: Comprehensive analysis workflow\n\n## Best Practices Applied\n\n- **Data validation** before analysis execution\n- **Proper feature scaling** and categorical encoding\n- **Train-test splitting** with stratification when appropriate\n- **Cross-validation** for robust model evaluation\n- **Parameter optimization** using systematic approaches\n- **Residual analysis** and diagnostic checks\n- **Business interpretation** of statistical results\n- **Documentation** of methodology and assumptions\n\n## Example Usage\n\n```sql\n-- Example workflow for Teradata Support Vector Machine\n-- Replace ''your_table'' with actual table name\n\n-- 1. Data exploration and validation\nSELECT COUNT(*),\n       COUNT(DISTINCT your_id_column),\n       AVG(your_target_column),\n       STDDEV(your_target_column)\nFROM your_database.your_table;\n\n-- 2. Execute complete classification workflow\n-- (Detailed SQL provided by the skill)\n```\n\n## Scripts Included\n\n### Core Analytics Scripts\n- **`preprocessing.sql`**: Data preparation and feature engineering\n- **`table_analysis.sql`**: Automatic table structure analysis\n- **`complete_workflow_template.sql`**: End-to-end workflow template\n- **`model_training.sql`**: TD_SVM training procedures\n- **`prediction.sql`**: SVMSparsePredict execution\n- **`evaluation.sql`**: Model validation and metrics calculation\n\n### Utility Scripts\n- **`data_quality_checks.sql`**: Comprehensive data validation\n- **`parameter_tuning.sql`**: Systematic parameter optimization\n- **`diagnostic_queries.sql`**: Model diagnostics and interpretation\n\n## Limitations and Disclaimers\n\n- **Data quality**: Results depend on input data quality and completeness\n- **Sample size**: Minimum sample size requirements for reliable results\n- **Feature selection**: Manual feature engineering may be required\n- **Computational resources**: Large datasets may require optimization\n- **Business context**: Statistical results require domain expertise for interpretation\n- **Model assumptions**: Understand underlying mathematical assumptions\n\n## Quality Checks\n\n### Automated Validations\n- **Data completeness** verification before analysis\n- **Statistical assumptions** testing where applicable\n- **Model convergence** monitoring during training\n- **Prediction quality** assessment using validation data\n- **Performance metrics** calculation and interpretation\n\n### Manual Review Points\n- **Feature selection** appropriateness for business problem\n- **Model interpretation** alignment with domain knowledge\n- **Results validation** against business expectations\n- **Documentation** completeness for reproducibility\n\n## Updates and Maintenance\n\n- **Version compatibility**: Tested with latest Teradata Vantage releases\n- **Performance optimization**: Regular query performance reviews\n- **Best practices**: Updated based on analytics community feedback\n- **Documentation**: Maintained with latest ClearScape Analytics features\n- **Examples**: Updated with real-world use cases and scenarios\n\n---\n\n*This skill provides production-ready classification analytics using Teradata ClearScape Analytics TD_SVM with comprehensive data science best practices.*\n"},"lastSynced":"2026-03-08T02:13:41.934Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Science Agents requiring advanced linear and non-linear classification capabilities using Support Vector Machine","zh":"适用于需要使用支持向量机进行高级线性和非线性分类能力的数据科学代理","ja":"サポートベクターマシンを使用した高度な線形および非線形分類機能を必要とするデータサイエンスエージェントに最適","ko":"서포트 벡터 머신을 사용하여 고급 선형 및 비선형 분류 기능을 필요로 하는 데이터 과학 에이전트에 적합","es":"Ideal para Agentes de Ciencia de Datos que requieren capacidades de clasificación lineal y no lineal avanzadas utilizando Support Vector Machine","fr":"Idéal pour les agents de science des données nécessitant des capacités de classification linéaire et non linéaire avancées en utilisant Support Vector Machine","de":"Ideal für Data Science-Agents, die erweiterte lineare und nichtlineare Klassifizierungsfähigkeiten unter Verwendung von Support Vector Machine benötigen","pt":"Ideal para Agentes de Ciência de Dados que exigem capacidades de classificação linear e não linear avançadas usando Support Vector Machine","ru":"Идеально для агентов Data Science, требующих передовых линейных и нелинейных возможностей классификации с использованием Support Vector Machine","ar":"مثالي لعميل علم البيانات الذي يتطلب قدرات تصنيف خطية وغير خطية متقدمة باستخدام Support Vector Machine"},"recommendation":{"en":"Empowers agents to perform comprehensive analytical workflows for classification using Teradata Support Vector Machine, including automated preprocessing and advanced TD_SVM implementation, leveraging train-test splitting and scaling for accurate model deployment","zh":"赋予代理执行使用Teradata支持向量机的综合分析工作流，包括自动预处理和高级TD_SVM实现，利用训练测试分割和缩放以实现准确的模型部署","ja":"Teradataサポートベクターマシンを使用した包括的な分析ワークフローをエージェントが実行できるようにする、自動前処理および高度なTD_SVMの実装を含む、トレーニングテスト分割およびスケーリングを使用して精確なモデル展開を実現する","ko":"에이전트가 Teradata 서포트 벡터 머신을 사용하여 전체 분석 워크플로를 수행할 수 있도록 하는 것으로, 자동 전처리 및 고급 TD_SVM 구현을 포함하며, 훈련 테스트 분할 및 확장을 사용하여 정확한 모델 배포를 가능하게 함","es":"Habilita a los agentes a realizar flujos de trabajo analíticos integrales para la clasificación utilizando Teradata Support Vector Machine, incluyendo la preprocesamiento automático y la implementación avanzada de TD_SVM, aprovechando la división de entrenamiento y prueba y la escalabilidad para una implementación de modelo precisa","fr":"Permet aux agents d''effectuer des flux de travail analytiques complets pour la classification en utilisant Teradata Support Vector Machine, y compris le prétraitement automatisé et la mise en œuvre avancée de TD_SVM, en exploitant le partage d''entraînement et de test et la mise à l''échelle pour un déploiement de modèle précis","de":"Ermächtigt Agenten, umfassende analytische Workflows für die Klassifizierung unter Verwendung von Teradata Support Vector Machine durchzuführen, einschließlich automatisierter Vorverarbeitung und erweiterter TD_SVM-Implementierung, unter Ausnutzung von Trainings- und Testaufteilung sowie Skalierung für eine genaue Modellbereitstellung","pt":"Habilita os agentes a realizar fluxos de trabalho analíticos abrangentes para classificação usando Teradata Support Vector Machine, incluindo pré-processamento automatizado e implementação avançada do TD_SVM, aproveitando a divisão de treinamento e teste e escalabilidade para implantação precisa do modelo","ru":"Наделяет агентов возможностью выполнять комплексные аналитические рабочие процессы для классификации с использованием Teradata Support Vector Machine, включая автоматическую предварительную обработку и продвинутую реализацию TD_SVM, используя разделение обучения и тестирования и масштабирование для точной развертывания модели","ar":"يمنح الوكلاء القدرة على أداء تدفقات عمل تحليلية شاملة للتصنيف باستخدام Teradata Support Vector Machine، بما في ذلك المعالجة المسبقة الأوتوماتيكية والتنفيذ المتقدم لـ TD_SVM، واستغلال الانقسام بين التدريب والاختبار والتوسع لتنفيذ نموذج دقيق"},"useCases":{"en":["Automating classification model development with TD_SVM","Generating insights from large datasets using Teradata","Deploying predictive models with advanced preprocessing"],"zh":["使用TD_SVM自动执行分类模型开发","使用Teradata从大型数据集生成洞察","使用高级预处理部署预测模型"],"ja":["TD_SVMを使用した分類モデル開発の自動化","Teradataを使用した大規模データセットからの洞察の生成","高度な前処理を使用した予測モデルの展開"],"ko":["TD_SVM을 사용하여 분류 모델 개발 자동화","Teradata를 사용하여 대규모 데이터셋에서 통찰력 생성","고급 전처리를 사용하여 예측 모델 배포"],"es":["Automatización del desarrollo de modelos de clasificación con TD_SVM","Generación de conocimientos a partir de grandes conjuntos de datos utilizando Teradata","Implementación de modelos predictivos con preprocesamiento avanzado"],"fr":["Automatisation du développement de modèles de classification avec TD_SVM","Génération d''informations à partir de grands ensembles de données en utilisant Teradata","Déploiement de modèles prédictifs avec un prétraitement avancé"],"de":["Automatisierung der Entwicklung von Klassifizierungsmodellen mit TD_SVM","Generierung von Erkenntnissen aus großen Datensätzen unter Verwendung von Teradata","Bereitstellung von Vorhersagemodellen mit erweiterter Vorverarbeitung"],"pt":["Automatizar o desenvolvimento do modelo de classificação com TD_SVM","Gerar informações a partir de grandes conjuntos de dados usando Teradata","Implantar modelos preditivos com pré-processamento avançado"],"ru":["Автоматизировать разработку модели классификации с использованием TD_SVM","Получать информацию из больших наборов данных с помощью Teradata","Развертывать прогностические модели с продвинутой предварительной обработкой"],"ar":["أتمتة تطوير نموذج التصنيف باستخدام TD_SVM","إنتاج معلومات من مجموعات بيانات كبيرة باستخدام Teradata","نشر نماذج تنبؤية مع معالجة مسبقة متقدمة"]},"limitations":{"en":["Requires Teradata environment","Specific to classification analytics"],"zh":["需要Teradata环境","仅限于分类分析"],"ja":["Teradata環境が必要","分類分析に特化"],"ko":["Teradata 환경이 필요","분류 분석에만 특화"],"es":["Requiere entorno de Teradata","Específico para análisis de clasificación"],"fr":["Nécessite un environnement Teradata","Spécifique à l''analyse de classification"],"de":["Benötigt Teradata-Umgebung","Spezifisch für Klassifizierungsanalyse"],"pt":["Exige ambiente Teradata","Específico para análise de classificação"],"ru":["Требует среды Teradata","Конкретно для анализа классификации"],"ar":["يتطلب بيئة Teradata","محدد للتحليل التصنيفي"]},"version":4},"contentHash":"3227c0035f2da6e847d8dbcf0cdcd83a9f0cb9ec764854b0f6b3558e4536e3a4","qualityScore":54}');
