INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('teradata-labs/claude-cookbooks/td-svm', 'td-svm', 'teradata-labs', 'claude-cookbooks', 'community', 'td-svm teradata-labs claude-cookbooks community The td-svm skill provides a comprehensive analytical workflow for linear and non-linear classification using Support Vector Machine. It benefits data scientists and analysts working with Teradata. td-svm 是一个 Teradata 支持向量机的集合，提供了从数据探索到模型部署的完整分析工作流 td-svm は Teradata サポートベクターマシンのコレクションであり、データの探索からモデルへのデプロイまでの完全な分析ワークフローを提供 td-svm은 Teradata 지원 벡터 머신의 컬렉션으로, 데이터 탐색에서 모델 배포까지 완전한 분석 워크플로우를 제공 TD_SVM es una colección de notebooks que muestra formas efectivas de utilizar AI con Teradata para clasificación lineal y no lineal. Ofrece un flujo de trabajo analítico completo con preprocessamiento automatizado TD_SVM est une collection de notebooks qui montre des façons efficaces d''utiliser l''IA avec Teradata pour la classification linéaire et non linéaire. Il offre un flux de travail analytique complet avec un preprocessamiento automatisé TD_SVM ist eine Sammlung von Notebooks, die effektive Wege zur Nutzung von KI mit Teradata für lineare und nichtlineare Klassifizierung zeigt. Es bietet einen vollständigen analytischen Workflow mit automatisierter Vorverarbeitung O TD_SVM é uma coleção de notebooks que demonstram formas eficazes de usar AI com Teradata para análise de classificação. Oferece pré-processamento automático e implementação avançada do TD_SVM TD_SVM - это коллекция ноутбуков, демонстрирующих эффективные способы использования ИИ с Teradata для классификации. Предоставляет автоматическую предварительную обработку и продвинутую реализацию TD_SVM TD_SVM هو مجموعة من الدفاتر التي تظهر طرقًا فعالة لاستخدام الذكاء الاصطناعي مع Teradata لتحليل التصنيف. يقدم معالجة أولية آلية وتنفيذا متقدمًا لـ TD_SVM how to use td-svm td-svm alternative td-svm setup guide what is td-svm td-svm vs scikit-learn td-svm install Teradata Support Vector Machine classification analytics with td-svm td-svm Teradata 支持向量机 AI 에이전트 支持向量机 线性分类 非线性分类 自动预处理 数据探索 模型部署 Complete analytical workflow from data exploration to model deployment Automated preprocessing including scaling, encoding, and train-test splitting Advanced TD_SVM implementation for linear and non-linear classification Supports data exploration and model deployment using Teradata Enables automated preprocessing for efficient data preparation td-svm is a collection of notebooks and recipes for effective AI-driven classification analytics with Teradata Support Vector Machine.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('karanchawla/vvm/vvm', 'community', 'karanchawla', 'vvm', 'karanchawla/vvm', 'vvm', 0, 0, 54, '2026-03-08T01:57:15.643Z', '2026-03-08T02:13:44.949Z', '545df9404a3f930fd2f2422674fc2db4c8fc5e2f70d0b7f200f5cfd47f335e0b', '{"id":"karanchawla/vvm/vvm","name":"vvm","description":{"en":"vvm enables developers to write agentic programs with the LLM as the runtime, benefiting those who want to create AI-powered workflows. It supports specific commands and file formats.","zh":"VVM（Vibe Virtual Machine）是一种用于编写代理程序的语言，用于AI工具开发和集成","ja":"VVM（Vibe Virtual Machine）は、AIエージェントの開発と統合に使用される言語です","ko":"VVM（Vibe Virtual Machine）は 인공지능 에이전트 개발과 통합을 위한 언어입니다","es":"VVM es un lenguaje para escribir programas agénticos con LLM como tiempo de ejecución. Se activa con comandos como /vvm-boot o al abrir archivos .vvm","fr":"VVM est un langage pour écrire des programmes agéntiques avec LLM comme runtime. Il est activé avec des commandes comme /vvm-boot ou en ouvrant des fichiers .vvm","de":"VVM ist eine Sprache für das Schreiben agenter Programm mit LLM als Laufzeit. Es wird aktiviert mit Befehlen wie /vvm-boot oder beim Öffnen von .vvm-Dateien","pt":"A VVM é uma linguagem para escrever programas agênticos com suporte a runtime de LLM. Ela permite criar fluxos de trabalho impulsionados por IA.","ru":"VVM — язык для написания агентских программ с поддержкой runtime LLM. Он позволяет создавать рабочие процессы, управляемые ИИ.","ar":"VVM هي لغة لكتابة البرامج الوكيلية بدعم تشغيل LLM. وهي تسمح بإنشاء سير عمل مدفوعة بالذكاء الاصطناعي."},"seo":{"title":{"en":"vvm: Setup Guide for AI Agents | AI Agent Skill","zh":"VVM Setup Guide: AIエージェント集成与Vibe Virtual Machine","ja":"VVM Setup Guide: AIエージェントとVibe Virtual Machineの活用","ko":"VVM 설치 가이드: 인공지능 에이전트와 Vibe Virtual Machine","es":"Guía de configuración de VVM: Máquina Virtual de Vibe","fr":"Guide 