INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('karanchawla/vvm/vvm', 'vvm', 'karanchawla', 'vvm', 'community', 'vvm karanchawla vvm community vvm enables developers to write agentic programs with the LLM as the runtime, benefiting those who want to create AI-powered workflows. It supports specific commands and file formats. VVM（Vibe Virtual Machine）是一种用于编写代理程序的语言，用于AI工具开发和集成 VVM（Vibe Virtual Machine）は、AIエージェントの開発と統合に使用される言語です VVM（Vibe Virtual Machine）は 인공지능 에이전트 개발과 통합을 위한 언어입니다 VVM es un lenguaje para escribir programas agénticos con LLM como tiempo de ejecución. Se activa con comandos como /vvm-boot o al abrir archivos .vvm VVM est un langage pour écrire des programmes agéntiques avec LLM comme runtime. Il est activé avec des commandes comme /vvm-boot ou en ouvrant des fichiers .vvm VVM ist eine Sprache für das Schreiben agenter Programm mit LLM als Laufzeit. Es wird aktiviert mit Befehlen wie /vvm-boot oder beim Öffnen von .vvm-Dateien A VVM é uma linguagem para escrever programas agênticos com suporte a runtime de LLM. Ela permite criar fluxos de trabalho impulsionados por IA. VVM — язык для написания агентских программ с поддержкой runtime LLM. Он позволяет создавать рабочие процессы, управляемые ИИ. VVM هي لغة لكتابة البرامج الوكيلية بدعم تشغيل LLM. وهي تسمح بإنشاء سير عمل مدفوعة بالذكاء الاصطناعي. how to use vvm vvm setup guide vvm alternative vvm vs other languages vvm install what is vvm vvm documentation vvm syntax vvm AI workflows VVM AIエージェント Vibe Virtual Machine AI工具开发 代理程序 LLM AI驱动的工作流 VVM语法 VVM语义 Activates on /vvm-boot, /vvm-compile, /vvm-run, or /vvm-generate commands Supports .vvm file format for writing agentic programs Utilizes LLM as the runtime for executing programs Enables creation of AI-powered workflows Provides documentation files for understanding VVM syntax and semantics vvm is a language for writing agentic programs where the LLM acts as the runtime, utilizing commands like /vvm-boot and /vvm-run.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('underwear/claude-code-underwear-skills/op', 'community', 'underwear', 'claude-code-underwear-skills', 'underwear/claude-code-underwear-skills', 'op', 0, 0, 54, '2026-03-08T01:57:15.644Z', '2026-03-08T02:13:45.460Z', 'a6d6f8ca5b003a00a1585e32e7b97e5a437d37f1d0542334867e3ae0f89a09b8', '{"id":"underwear/claude-code-underwear-skills/op","name":"op","description":{"en":"The op skill manages secrets in 1Password using the op command, authenticated via service account, benefiting developers and security teams. It provides a collection of useful skills for Claude Code.","zh":"op 是 1Password CLI 命令行工具的集合，用于管理密码和密钥","ja":"op は 1Password CLI コマンドラインツールのコレクションで、パスワードと鍵を管理するために使用","ko":"op는 1Password CLI 명령줄 도구의 모음으로, 비밀번호와 키를 관리하는 데 사용됩니다","es":"El comando op permite gestionar secretos en 1Password mediante la línea de comandos. Se autentica mediante cuentas de servicio y admite la administración de elementos en vaults.","fr":"La commande op permet de gérer les secrets dans 1Password via la ligne de commande. Elle s''authentifie via des comptes de service et prend en charge la gestion d''éléments dans des vaults.","de":"Der Befehl op ermöglicht die Verwaltung von Geheimnissen in 1Password über die Kommandozeile. Er authentifiziert sich über Dienstkonten und unterstützt die Verwaltung von Elementen in Vault-Verzeichnissen.","pt":"O op é uma ferramenta de linha de comando para gerenciar segredos com 1Password. Ele fornece uma forma segura de armazenar e recuperar informações sensíveis.","ru":"Op - это инструмент командной строки для управления секретами с помощью 1Password. Он предоставляет безопасный способ хранения и извлечения конфиденциальной информации с ИИ Агентами","ar":"op هو أداة سطر أوامر لتدبير الأسرار باستخدام 1Password. يوفر وسيلة آمنة لتخزين واسترجاع المعلومات الحساسة مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"op: 1Password CLI Management Setup Guide | AI Agent Skill","zh":"op Setup Guide: 1Password CLI 命令行工具","ja":"op セットアップガイド: 1Password CLI コマンドラインツール","ko":"op 설정 가이드: 1Password CLI 명령줄 도구","es":"Guía de configuración de op: Administración de secretos e...","fr":"Guide de configuration d''op : Gestion des secrets dans 1P...","de":"op-Setup-Anleitung: Verwaltung von Geheimnissen in 1Password","pt":"Guia de Configuração do op: Gerenciando Segredos com 1Pas...","ru":"Настройка op: Руководство по управлению секретами с помощ...","ar":"دليل إعداد op: إدارة الأسرار باستخدام 1Password CLI وأدوا..."},"description":{"en":"Discover how to manage secrets in 1Password using the op command. Learn how to authenticate via service account and get started with our expert guide.","zh":"了解 op 的功能和用法，包括 1Password CLI 命令行工具的使用方法","ja":"op の機能と使い方を学ぶ、1Password CLI コマンドラインツールの使い方を含む","ko":"op의 기능과 사용 방법을 알아보세요, 1Password CLI 명령줄 도구 사용법 포함","es":"Aprende a utilizar el comando op para gestionar secretos en 1Password. Descubre cómo autenticar mediante cuentas de servicio y administrar elementos en vaults.","fr":"Découvrez comment utiliser la commande op pour gérer les secrets dans 1Password. Apprenez à vous authentifier via des comptes de service et à gérer des éléme...","de":"Erfahren Sie, wie Sie den Befehl op verwenden, um Geheimnisse in 1Password zu verwalten. Entdecken Sie, wie Sie sich über Dienstkonten authentifizieren und E...","pt":"Aprenda a configurar o op para gerenciar segredos com 1Password CLI e melhore a segurança dos seus projetos de desenvolvimento","ru":"Узнайте, как настроить op для управления секретами с помощью 1Password CLI и улучшите безопасность своих проектов разработки с ИИ Агентами","ar":"تعرف على كيفية إعداد op لإدارة الأسرار باستخدام 1Password CLI وتحسين أمان مشاريع التطوير الخاصة بك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"op is a command-line interface for managing secrets in 1Password, allowing authenticated access via service account.","zh":"op 是一种命令行工具，用于管理 1Password 密码和密钥","ja":"op は、1Password のパスワードと鍵を管理するためのコマンドラインツール","ko":"op는 1Password 비밀번호와 키를 관리하는 명령줄 도구입니다","es":"op es una herramienta de línea de comandos para gestionar secretos en 1Password mediante cuentas de servicio.","fr":"op est un outil de ligne de commande pour gérer les secrets dans 1Password via des comptes de service.","de":"op ist ein Kommandozeilen-Tool zur Verwaltung von Geheimnissen in 1Password über Dienstkonten.","pt":"O op é uma ferramenta de linha de comando para gerenciar segredos com 1Password","ru":"Op - это инструмент командной строки для управления секретами с помощью 1Password и ИИ Агентов","ar":"op هو أداة سطر أوامر لتدبير الأسرار باستخدام 1Password وأدوات الذكاء الاصطناعي"},"features":{"en":["Manages secrets in 1Password using the op command","Authenticates via service account","Lists items in a vault using op item list --vault","Discovers available vault names using op vault list --format=json","Requires --vault on every command for service accounts"],"zh":["支持 1Password CLI 命令行工具","使用服务账户进行认证","支持多个金库","可以列出所有项目","支持 JSON 格式输出"],"ja":["1Password CLI コマンドラインツールをサポート","サービスアカウントによる認証","複数の金庫をサポート","すべてのアイテムをリストできます","JSON フォーマット出力をサポート"],"ko":["1Password CLI 명령줄 도구 지원","서비스 계정으로 인증","여러 금고 지원","모든 항목을 나열할 수 있습니다","JSON 형식 출력 지원"],"es":["Autenticación mediante cuentas de servicio","Administración de elementos en vaults","Soporte para la lista de elementos en vaults","Compatibilidad con el formato JSON para la salida de comandos","Requiere el parámetro --vault para cada comando","Permite la descubierta de nombres de vault disponibles"],"fr":["Authentification via des comptes de service","Gestion d''éléments dans des vaults","Prise en charge de la liste d''éléments dans des vaults","Compatibilité avec le format JSON pour la sortie de commandes","Nécessite le paramètre --vault pour chaque commande","Permet la découverte de noms de vault disponibles"],"de":["Authentifizierung über Dienstkonten","Verwaltung von Elementen in Vault-Verzeichnissen","Unterstützung für die Liste von Elementen in Vault-Verzeichnissen","Kompatibilität mit dem JSON-Format für die Ausgabe von Befehlen","Erfordert den Parameter --vault für jeden Befehl","Ermöglicht die Entdeckung von verfügbaren Vault-Namen"],"pt":["Gerenciamento de segredos com 1Password CLI","Autenticação via conta de serviço","Listagem de itens em vault","Uso de vault nome para comandos subsequentes","Suporte a formato JSON"],"ru":["Управление секретами с помощью 1Password CLI и ИИ Агентов","Аутентификация через сервисный аккаунт","Список элементов в хранилище","Использование имени хранилища для последующих команд","Поддержка формата JSON"],"ar":["تدبير الأسرار باستخدام 1Password CLI وأدوات الذكاء الاصطناعي","التحقق من خلال حساب الخدمة","قائمة العناصر في الخزنة","استخدام اسم الخزنة لأوامر لاحقة","دعم تنسيق JSON"]},"keywords":{"en":["how to use op","op setup guide","1password cli management","op alternative","op vs lastpass","op install","what is op","op command-line interface","1password secrets management"],"zh":["op 命令行工具","1Password CLI","服务账户认证","金库管理","JSON 输出","密码管理","命令行工具"],"ja":["op コマンドラインツール","1Password CLI","サービスアカウント認証","金庫管理","JSON 出力","パスワード管理","コマンドラインツール"],"ko":["op 명령줄 도구","1Password CLI","서비스 계정 인증","금고 관리","JSON 출력","비밀번호 관리","명령줄 도구"],"es":["op comando","1Password CLI","gestión de secretos","autenticación de servicio","administración de vaults","formato JSON","Herramientas de desarrollo","seguridad de aplicaciones","gestión de identidades"],"fr":["commande op","1Password CLI","gestion des secrets","authentification de service","gestion de vaults","format JSON","Outils de développement","sécurité des applications","gestion des identités"],"de":["op-Befehl","1Password CLI","Verwaltung von Geheimnissen","Dienstauthentifizierung","Verwaltung von Vault-Verzeichnissen","JSON-Format","Entwicklertools","Anwendungssicherheit","Identitätsverwaltung"],"pt":["op","1Password CLI","gerenciamento de segredos","autenticação via conta de serviço","listagem de itens em vault","uso de vault nome","suporte a formato JSON","desenvolvimento de software","segurança de dados"],"ru":["op","1Password CLI","управление секретами","аутентификация через сервисный аккаунт","список элементов в хранилище","использование имени хранилища","поддержка формата JSON","разработка программного обеспечения","безопасность данных","ИИ Агенты"],"ar":["op","1Password CLI","تدبير الأسرار","التحقق من خلال حساب الخدمة","قائمة العناصر في الخزنة","استخدام اسم الخزنة","دعم تنسيق JSON","تطوير البرمجيات","أمان البيانات","أدوات الذكاء الاصطناعي"]}},"owner":"underwear","repo":"claude-code-underwear-skills","repoPath":"underwear/claude-code-underwear-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.644Z","topics":[],"category":"community","skillMd":{"name":"op","description":"Manage 1Password secrets. Use when user wants to list, get, or read passwords, OTP codes, API keys, or other secrets from 1Password.","bodyPreview":"# 1Password CLI (`op`)\n\nManage secrets in 1Password using the `op` command. Authenticated via service account.\n\n## User Request\n\n$ARGUMENTS\n\n## Commands Reference\n\n**Important:** Service accounts require `--vault` on every command. Before running any item commands, discover the available vault name first:\n\n```bash\nop vault list --format=json\n```\n\nThen use the vault name from the response in all subsequent commands.\n\n### List Items\n\n```bash\n# List all items in vault\nop item list --vault \"VAULT_NA","body":"# 1Password CLI (`op`)\n\nManage secrets in 1Password using the `op` command. Authenticated via service account.\n\n## User Request\n\n$ARGUMENTS\n\n## Commands Reference\n\n**Important:** Service accounts require `--vault` on every command. Before running any item commands, discover the available vault name first:\n\n```bash\nop vault list --format=json\n```\n\nThen use the vault name from the response in all subsequent commands.\n\n### List Items\n\n```bash\n# List all items in vault\nop item list --vault \"VAULT_NAME\" --format=json\n\n# Long format (with categories, dates)\nop item list --vault \"VAULT_NAME\" --long --format=json\n\n# Filter by category\nop item list --vault \"VAULT_NAME\" --categories Login --format=json\nop item list --vault \"VAULT_NAME\" --categories \"API Credential\" --format=json\n\n# Filter by tags\nop item list --vault \"VAULT_NAME\" --tags production --format=json\n\n# Filter favorites only\nop item list --vault \"VAULT_NAME\" --favorite --format=json\n```\n\n### Get Item Details\n\n```bash\n# Full item details\nop item get \"Item Title\" --vault \"VAULT_NAME\" --format=json\n\n# Get OTP (one-time password / 2FA code)\nop item get \"Item Title\" --vault \"VAULT_NAME\" --otp\n\n# Get specific fields\nop item get \"Item Title\" --vault \"VAULT_NAME\" --fields label=username --format=json\nop item get \"Item Title\" --vault \"VAULT_NAME\" --fields label=password --format=json\nop item get \"Item Title\" --vault \"VAULT_NAME\" --fields label=username,label=password --format=json\n\n# Get fields by type\nop item get \"Item Title\" --vault \"VAULT_NAME\" --fields type=CONCEALED --format=json\n```\n\n### Read Individual Secret\n\n```bash\n# Read a specific field value directly\nop read \"op://VAULT_NAME/Item Title/username\"\nop read \"op://VAULT_NAME/Item Title/password\"\nop read \"op://VAULT_NAME/Item Title/Section Name/field\"\n```\n\n### List Vaults\n\n```bash\nop vault list --format=json\n```\n\n## JSON Response Structures\n\n**`op vault list --format=json`:**\n```json\n[\n  {\"id\": \"abc123...\", \"name\": \"My Vault\", \"content_version\": 42}\n]\n```\n\n**`op item list --format=json`:**\n```json\n[\n  {\n    \"id\": \"abc123...\",\n    \"title\": \"Example Service\",\n    \"version\": 1,\n    \"vault\": {\"id\": \"xyz...\", \"name\": \"My Vault\"},\n    \"category\": \"LOGIN\",\n    \"last_edited_by\": \"...\",\n    \"created_at\": \"2025-01-01T00:00:00Z\",\n    \"updated_at\": \"2025-01-02T00:00:00Z\",\n    \"additional_information\": \"user@example.com\",\n    \"urls\": [{\"primary\": true, \"href\": \"https://example.com\"}]\n  }\n]\n```\n\n**`op item get --format=json`:**\n```json\n{\n  \"id\": \"abc123...\",\n  \"title\": \"Example Service\",\n  \"category\": \"LOGIN\",\n  \"vault\": {\"id\": \"xyz...\", \"name\": \"My Vault\"},\n  \"fields\": [\n    {\n      \"id\": \"username\",\n      \"type\": \"STRING\",\n      \"purpose\": \"USERNAME\",\n      \"label\": \"email\",\n      \"value\": \"user@example.com\",\n      \"reference\": \"op://My Vault/Example Service/email\"\n    },\n    {\n      \"id\": \"password\",\n      \"type\": \"CONCEALED\",\n      \"purpose\": \"PASSWORD\",\n      \"label\": \"password\",\n      \"value\": \"secret_value\",\n      \"reference\": \"op://My Vault/Example Service/password\"\n    },\n    {\n      \"id\": \"TOTP_xxx\",\n      \"type\": \"OTP\",\n      \"label\": \"one-time password\",\n      \"value\": \"otpauth://totp/...\",\n      \"totp\": \"123456\"\n    }\n  ],\n  \"urls\": [{\"primary\": true, \"href\": \"https://example.com\"}]\n}\n```\n\n**`op item get --otp`:**\nReturns just the 6-digit TOTP code as plain text (e.g., `182448`).\n\n**`op item get --fields --format=json`:**\n```json\n[\n  {\"id\": \"username\", \"type\": \"STRING\", \"label\": \"email\", \"value\": \"user@example.com\"},\n  {\"id\": \"password\", \"type\": \"CONCEALED\", \"label\": \"password\", \"value\": \"secret_value\"}\n]\n```\n\n## Important Notes\n\n- **Service account requires `--vault`** — always discover vault name via `op vault list` first, then use it in all commands\n- **`--otp` returns plain text** — do not combine with `--format=json`\n- **OTP field in JSON** — when getting full item, the current TOTP code is in the `totp` key of OTP-type fields\n- **Categories:** Login, Password, API Credential, Secure Note, Database, SSH Key, Credit Card, Identity, Document, Server, Software License\n\n## Instructions\n\n1. Parse the user''s natural language request to determine what they need\n2. **First, run `op vault list --format=json`** to discover the available vault name(s)\n3. Determine the appropriate `op` command, using the discovered vault name\n4. **Always use `--format=json`** except for `--otp` (which returns plain text)\n5. Execute the command via Bash\n6. Parse the JSON response and present results clearly to the user\n7. For OTP requests, just return the code prominently\n8. For credential requests, format as a clear key-value list\n9. **Never log or echo secrets unnecessarily** — only show what was requested\n\nIf the request is ambiguous, ask for clarification.\n"},"lastSynced":"2026-03-08T02:13:45.460Z","agentAnalysis":{"suitability":{"en":"Perfect for Security Agents needing secure secret management via the 1Password CLI","zh":"非常适合需要通过 1Password CLI 进行安全密钥管理的安全代理","ja":"1Password CLI を使用して安全なシークレット管理が必要なセキュリティ エージェントに最適","ko":"1Password CLI를 통해 보안 키 관리가 필요한 보안 에이전트에 적합","es":"Perfecto para Agents de Seguridad que necesitan una gestión segura de secretos a través de la CLI de 1Password","fr":"Parfait pour les Agents de Sécurité ayant besoin d''une gestion sécurisée des secrets via la CLI de 1Password","de":"Perfekt für Sicherheitsagenten, die eine sichere Verwaltung von Geheimnissen über die 1Password-CLI benötigen","pt":"Perfeito para Agentes de Segurança que necessitam de gerenciamento de segredos seguro via 1Password CLI","ru":"Идеально для агентов безопасности, которым требуется безопасное управление секретами через 1Password CLI","ar":"مثالي للوكلاء الأمنيين الذين يحتاجون إلى إدارة أمين سر آمنة عبر 1Password CLI"},"recommendation":{"en":"Empowers agents to manage secrets in 1Password using the op command, authenticated via service account, enabling secure interactions with vaults and items using JSON format, and leveraging commands like op vault list and op item list","zh":"赋予代理通过 op 命令管理 1Password 中的密钥的能力，通过服务账户进行身份验证，启用与密钥库和项目使用 JSON 格式的安全交互，并利用诸如 op vault list 和 op item list 的命令","ja":"エージェントが op コマンドを使用して 1Password 内のシークレットを管理できるようにし、サービス アカウントを介して認証を行い、JSON フォーマットを使用して金庫とアイテムとの安全なやり取りを可能にし、op vault list や op item list などのコマンドを利用できる","ko":"에이전트가 op 명령을 사용하여 1Password 내의 시크릿을 관리할 수 있도록 하며, 서비스 계정을 통해 인증을 수행하고, JSON 형식을 사용하여 보관소와 항목과의 보안 상호 작용을 가능하게 하며, op vault list 및 op item list와 같은 명령을 활용할 수 있도록 함","es":"Habilita a los agentes a gestionar secretos en 1Password utilizando el comando op, autenticados a través de una cuenta de servicio, lo que permite interacciones seguras con vaults y elementos utilizando formato JSON, y aprovechando comandos como op vault list y op item list","fr":"Permet aux agents de gérer les secrets dans 1Password en utilisant la commande op, authentifiés via un compte de service, ce qui permet des interactions sécurisées avec les vaults et les éléments en utilisant le format JSON, et en exploitant des commandes comme op vault list et op item list","de":"Ermächtigt Agenten, Geheimnisse in 1Password mithilfe des op-Befehls zu verwalten, der über ein Dienstkonto authentifiziert wird, wodurch sichere Interaktionen mit Vault und Elementen im JSON-Format ermöglicht werden und Befehle wie op vault list und op item list genutzt werden","pt":"Habilita os agentes a gerenciar segredos no 1Password usando o comando op, autenticado por meio de conta de serviço, permitindo interações seguras com cofres e itens usando formato JSON, e aproveitando comandos como op vault list e op item list","ru":"Позволяет агентам управлять секретами в 1Password с помощью команды op, аутентифицированной через учетную запись службы, обеспечивая безопасное взаимодействие с хранилищами и элементами в формате JSON, и использует команды типа op vault list и op item list","ar":"يسمح للوكلاء بإدارة الأسرار في 1Password باستخدام الأمر op، المصادق عليه من خلال حساب الخدمة، وتمكين التفاعلات الآمنة مع الخزائن والأصناف باستخدام تنسيق JSON، وتحقيق أوامر مثل op vault list وop item list"},"useCases":{"en":["Listing items in a vault","Authenticating via service account for secur