INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('boshu2/agentops/update', 'update', 'boshu2', 'agentops', 'community', 'update boshu2 agentops community The update skill automates code deployment for AI agents, allowing developers to pull and install the latest skills globally. This skill benefits developers by simplifying the deployment process. update技能是AIエージェント的代码更新和验证工具，使用bash脚本实现代码更新 updateスキルはAIエージェントのコード更新と検証ツールで、bashスクリプトを使用してコードを更新します update 스킬은 AI 에이전트의 코드 업데이트 및 검증 도구로, bash 스크립트를 사용하여 코드를 업데이트합니다 La actualización de AgentOps permite reinstalar habilidades y mejorar la eficiencia de los agentes de código La mise à jour d''AgentOps permet de réinstaller des compétences et d''améliorer l''efficacité des agents de code Die Aktualisierung von AgentOps ermöglicht die Neuinstallation von Fähigkeiten und verbessert die Effizienz von Code-Agents O update é uma camada de DevOps que permite instalar skills de AgentOps e melhorar a eficiência do seu fluxo de trabalho. Update - это слой DevOps, который позволяет устанавливать навыки AgentOps и улучшать эффективность вашего рабочего процесса для ИИ Агентов التحديث هو طبقة من DevOps التي تمكنك من تثبيت مهارات AgentOps و تحسين كفاءة تدفق عملك لأدوات الذكاء الاصطناعي how to use update skill update skill setup guide update alternative update vs agentops update install bash script what is update skill AIエージェント代码更新 update技能 bash脚本 代码更新和验证 AI工具 代码更新最佳实践 Installs skills globally across all agents using a single command Pulls the latest skills from the repository via curl Executes a bash script for installation Verifies skill installation with no failures Supports reinstalling AgentOps skills update is a DevOps layer for coding agents that enables automated deployment of validated code and skill updates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TT-AIXion/github-kanri/gkn-cli', 'community', 'TT-AIXion', 'github-kanri', 'TT-AIXion/github-kanri', 'gkn-cli', 0, 0, 54, '2026-03-08T01:57:15.651Z', '2026-03-08T02:13:53.429Z', '4d33936e5ad230cac467e4edc32bd173a31fc236a3ecd223adf61817f8db52fc', '{"id":"TT-AIXion/github-kanri/gkn-cli","name":"gkn-cli","description":{"en":"The gkn-cli skill simplifies common git operations for AI agents, including config initialization and repository management. It benefits developers working with GitHub repositories.","zh":"gkn-cli 是一个 GitHub 仓库管理 CLI 工具，用于简化常见的 Git 操作，如配置初始化和仓库克隆","ja":"gkn-cli は、構成の初期化やリポジトリのクローンなどの一般的な Git 操作を簡略化する GitHub リポジトリ管理 CLI ツールです","ko":"gkn-cli는 설정 초기화 및 저장소 클론 등의 일반적인 Git 작업을 단순화하는 GitHub 저장소 관리 CLI 도구입니다","es":"gkn-cli es una herramienta de línea de comandos para gestionar repositorios de GitHub para agentes de AI, simplificando operaciones de git comunes","fr":"gkn-cli est un outil en ligne de commande pour gérer les référentiels GitHub pour les agents d''IA, simplifiant les opérations Git courantes","de":"gkn-cli ist ein Kommandozeilen-Tool zum Verwalten von GitHub-Repositorys für KI-Agents, das gängige Git-Operationen vereinfacht","pt":"O gkn-cli é uma ferramenta de linha de comando para gerenciar repositórios GitHub para agentes de IA, simplificando operações git comuns.","ru":"gkn-cli - это инструмент командной строки для управления репозиториями GitHub для ИИ Агентов, упрощающий общие операции git.","ar":"gkn-cli هو أداة سطر أوامر لإدارة مستودعات جيت هاب للوكلاء الذكية، وتبسيط العمليات جيت الشائعة."},"seo":{"title":{"en":"gkn-cli: GitHub Repository Management CLI Tool for AI Age...","zh":"gkn-cli 设置指南：GitHub 仓库管理 CLI 工具","ja":"gkn-cli セットアップガイド：GitHub リポジトリ管理 CLI ツール for AIエージェント","ko":"gkn-cli 설정 가이드: GitHub 저장소 관리 CLI 도구","es":"Guía de configuración de gkn-cli para agentes de AI","fr