INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('edwardmonteiro/Aiskillinpractice/definition.tech_spike', 'definition.tech_spike', 'edwardmonteiro', 'Aiskillinpractice', 'community', 'definition.tech_spike edwardmonteiro Aiskillinpractice community The definition.tech_spike skill helps engineering leaders define spikes, reducing uncertainty and feeding into planning conversations. It works with Codex and requires a small enumerator script. definition.tech_spike 技能帮助工程领导者快速定义减少不确定性的技术探索，并自信地将其纳入规划对话中 definition.tech_spike スキルは、エンジニアリングリーダーが不確実性を減らし、計画会議に自信を持って取り組むことができるスパイクを迅速に定義するのに役立ちます definition.tech_spike 기능은 엔지니어링 리더가 불확실성을 줄이고 계획 회의에 자신 있게 참여할 수 있는 기술 스파이크를 빠르게 정의하는 데 도움이 됩니다 Definition.tech_spike es una habilidad que permite a los líderes de ingeniería definir picos que reducen la incertidumbre y alimentan conversaciones de planificación con confianza Definition.tech_spike est une compétence qui permet aux leaders d''ingénierie de définir des pics qui réduisent l''incertitude et alimentent les conversations de planification avec confiance Definition.tech_spike ist eine Fähigkeit, die es Ingenieurleitern ermöglicht, Spitzen zu definieren, die die Unsicherheit reduzieren und Planungsgespräche mit Vertrauen speisen O definition.tech_spike é uma habilidade que ajuda líderes de engenharia a definir spikes que reduzem a incerteza e alimentam conversas de planejamento com confiança Definition.tech_spike - это навык, который помогает инженерным лидерам определять спайки, снижающие неопределенность и питающие планировочные разговоры с уверенностью definition.tech_spike هو مهارة تساعد قادة الهندسة على تعريف النقاط التي تقلل من عدم اليقين وتغذي محادثات التخطيط بثقة how to use definition.tech_spike definition.tech_spike setup guide what is definition.tech_spike definition.tech_spike alternative definition.tech_spike vs Codex install definition.tech_spike definition.tech_spike for AI agents running definition.tech_spike with Codex definition.tech_spike technical requirements AI 代理技术 definition.tech_spike 集成 Codex 技术文档 减少不确定性 提高规划效率 AI 技能开发 技术探索 Runs with Codex using the `codex skills run` command Requires a small enumerator script for compatibility Takes variables such as `topic`, `desired_outcome`, and `constraints` Helps clarify decisions to be unlocked by the spike Aligns with timebox and resourcing availability Gathers related research or prior explorations definition.tech_spike is a skill that enables the creation of spikes to reduce uncertainty and inform planning decisions, utilizing a small enumerator script for compatibility with agents like Codex.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('45black/uk-legal-plugins/ui-architect', 'community', '45black', 'uk-legal-plugins', '45black/uk-legal-plugins', 'ui-architect', 0, 0, 54, '2026-03-08T01:57:15.661Z', '2026-03-08T02:14:05.597Z', '720a0dabd4322f652b92184c603724d78fbc82661be3234157e0684c97e9820f', '{"id":"45black/uk-legal-plugins/ui-architect","name":"ui-architect","description":{"en":"The ui-architect skill designs component architecture for 45Black legaltech products, aiding non-coders in planning UI structure and selecting design systems. It helps in separating product layers and planning component hierarchy.","zh":"UI架构师技能帮助非编码人员设计和规划UI组件架构和层次结构，适用于AIエージェント和AI工具","ja":"UIアーキテクトスキルは、非コーダーがコンポーネントアーキテクチャとレイヤー構造を設計および計画できるようにします","ko":"UI 아키텍트 스킬은 비코더가 컴포넌트 아키텍처와 계층 구조를 설계하고 계획할 수 있도록 도와줍니다","es":"ui-architect ayuda a diseñar arquitecturas de componentes para productos legales, separando capas de producto y seleccionando sistemas de diseño adecuados","fr":"ui-architect aide à concevoir des architectures de composants pour les produits juridiques, en séparant les couches de produit et en sélectionnant des systèmes de conception appropriés","de":"ui-architect unterstützt den Entwurf von Komponentenarchitekturen für legale Produkte, indem es Produktlayer trennt und geeignete Designsysteme auswählt","pt":"O ui-architect é uma habilidade que ajuda a planejar a estrutura de UI e separar camadas de produto. É útil para iniciar novos produtos ou recursos de UI","ru":"ui-architect - это навык, который помогает планировать структуру UI и разделять слои продукта. Он полезен для начала новых продуктов или функций UI","ar":"ui-architect هو مهارة تساعد في تخطيط هيكل الواجهة و فصل طبقات المنتج. هو مفيد لبدء منتجات أو ميزات واجهة جديدة"},"seo":{"title":{"en":"ui-architect: Design Component Architecture Setup Guide |...","zh":"UI架构师技能：设计组件架构和层次结构","ja":"UIアー