INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('45black/uk-legal-plugins/ui-architect', 'ui-architect', '45black', 'uk-legal-plugins', 'community', 'ui-architect 45black uk-legal-plugins community The ui-architect skill designs component architecture for 45Black legaltech products, aiding non-coders in planning UI structure and selecting design systems. It helps in separating product layers and planning component hierarchy. UI架构师技能帮助非编码人员设计和规划UI组件架构和层次结构，适用于AIエージェント和AI工具 UIアーキテクトスキルは、非コーダーがコンポーネントアーキテクチャとレイヤー構造を設計および計画できるようにします UI 아키텍트 스킬은 비코더가 컴포넌트 아키텍처와 계층 구조를 설계하고 계획할 수 있도록 도와줍니다 ui-architect ayuda a diseñar arquitecturas de componentes para productos legales, separando capas de producto y seleccionando sistemas de diseño adecuados ui-architect aide à concevoir des architectures de composants pour les produits juridiques, en séparant les couches de produit et en sélectionnant des systèmes de conception appropriés ui-architect unterstützt den Entwurf von Komponentenarchitekturen für legale Produkte, indem es Produktlayer trennt und geeignete Designsysteme auswählt O ui-architect é uma habilidade que ajuda a planejar a estrutura de UI e separar camadas de produto. É útil para iniciar novos produtos ou recursos de UI ui-architect - это навык, который помогает планировать структуру UI и разделять слои продукта. Он полезен для начала новых продуктов или функций UI ui-architect هو مهارة تساعد في تخطيط هيكل الواجهة و فصل طبقات المنتج. هو مفيد لبدء منتجات أو ميزات واجهة جديدة how to use ui-architect ui-architect setup guide what is ui-architect ui-architect alternative ui-architect vs other design tools install ui-architect plugin ui-architect for legaltech products 45Black Claude Code plugin ui-architect for non-coders ui-architect design system UI架构师技能 AIエージェント AI工具 组件架构设计 UI层次结构规划 设计系统选择 产品层分离 组件层次结构设计 Designs component architecture for 45Black legaltech products Helps non-coders plan UI structure and select design systems Separates concerns between product layers Plans component hierarchy for apex products Utilizes the 45Black Claude Code plugin with 23 skills and 6 commands Supports UK legal skills for England and Wales ui-architect is a skill that helps design component architecture for legaltech products, separating product layers and planning UI structure using the 45Black Claude Code plugin.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kidow/dongwook.kim/deepwiki', 'community', 'kidow', 'dongwook.kim', 'kidow/dongwook.kim', 'deepwiki', 0, 0, 54, '2026-03-07T15:58:00Z', '2026-03-08T02:14:25.756Z', 'cd0dadf31266cdf2ecbe9c129357133f105078d93e9c714d929378feaf3c4e63', '{"id":"kidow/dongwook.kim/deepwiki","name":"deepwiki","description":{"en":"deepwiki is a tool for developers to query public GitHub repositories from the terminal. It provides access to table of contents, full wiki content, and AI-powered Q&A.","zh":"DeepWiki Node.js","ja":"DeepWiki Node.js","ko":"DeepWiki Node.js","es":"deepwiki es una herramienta que permite consultar la documentación de repositorios GitHub públicos desde la terminal mediante comandos como toc, wiki y ask","fr":"deepwiki est un outil qui permet d''interroger la documentation des dépôts GitHub publics depuis le terminal via des commandes comme toc, wiki et ask","de":"deepwiki ist ein Tool, das den Zugriff auf die Dokumentation öffentlicher GitHub-Repositorys über die Terminal mittels Befehlen wie toc, wiki und ask ermöglicht","pt":"O DeepWiki é uma ferramenta de consulta de repositórios GitHub que permite acessar documentos de repositórios públicos via terminal com Node.js.","ru":"DeepWiki — это инструмент запроса репозиториев GitHub, который позволяет получить доступ к документам из публичных репозиториев через терминал с помощью Node.js.","ar":"ديبويكي هو أداة للاستعلام عن مستودعات جيثب التي تمكن الوصول إلى مستندات المستودعات العامة عبر الطرفية باستخدام نود.جس"},"seo":{"title":{"en":"deepwiki: Query GitHub Repositories from Terminal | AI Ag...","zh":"DeepWiki_setup_guide","ja":"DeepWiki_Setup_Guide","ko":"DeepWiki_","es":"Guía de configuración de deepwiki: Accede a documentación...","fr":"Guide d''installation de deepwiki: Accédez à la documentat...","de":"Einrichtungsleitfaden für deepwiki: Greifen Sie auf GitHu...","pt":"Guia de Configuração do DeepWiki: Ferramenta de Consulta ...","ru":"Руководство по настройке DeepWiki: Инструмент запроса реп...","ar":"دليل إعداد ديبويكي: أداة الاستعلام عن مستودعات جيثب باستخ..."},"description":{"en":"Discover how to access public GitHub repo docs using deepwiki. Learn to query tables of contents, full wiki content, and get AI-powered answers from the term...","zh":"DeepWiki","ja":"DeepWiki","ko":"DeepWiki ","es":"Descubre cómo utilizar deepwiki para consultar la documentación de repositorios GitHub públicos desde la terminal","fr":"Découvrez comment utiliser deepwiki pour interroger la documentation des dépôts GitHub publics depuis le terminal","de":"Erfahren Sie, wie Sie deepwiki verwenden können, um auf die Dokumentation öffentlicher GitHub-Repositorys über die Terminal zuzugreifen","pt":"Aprenda a configurar e usar o DeepWiki para consultar documentos de repositórios GitHub públicos via terminal com Node.js","ru":"Узнайте, как настроить и использовать DeepWiki для запроса документов из публичных репозиториев GitHub через терминал с помощью Node.js и ИИ Агентов","ar":"تعرف على كيفية إعداد وتشغيل ديبويكي للاستعلام عن مستندات مستودعات جيثب العامة عبر الطرفية باستخدام نود.جس وأدوات الذكاء الاصطناعي"},"definition":{"en":"deepwiki is a Node.js-based tool that allows developers to query public GitHub repositories from the terminal via commands like `toc`, `wiki`, and `ask`","zh":"DeepWiki AI","ja":"DeepWiki AI","ko":"DeepWiki AI","es":"deepwiki es una herramienta de línea de comandos que utiliza AI para consultar documentación de GitHub","fr":"deepwiki est un outil en ligne de commande qui utilise l''IA pour interroger la documentation GitHub","de":"deepwiki ist ein Kommandozeilen-Tool, das KI verwendet, um auf GitHub-Dokumentation zuzugreifen","pt":"O DeepWiki é uma ferramenta de linha de comando que consulta repositórios GitHub públicos","ru":"DeepWiki — это командная утилита, которая запрашивает публичные репозитории GitHub","ar":"ديبويكي هو أداة سطر أوامر للاستعلام عن مستودعات جيثب العامة"},"features":{"en":["Generates table of contents for GitHub repositories using `npx @seflless/deepwiki toc <owner/repo>`","Retrieves full wiki content from GitHub repositories using `npx @seflless/deepwiki wiki <owner/repo>`","Provides AI-powered Q&A for GitHub repositories using `npx @seflless/deepwiki ask <owner/repo> \"<question>\"`","Supports multiple repository queries using `npx @seflless/deepwiki ask <repo1> <repo2> \"<question>\"`","Assumes Node.js installation for seamless execution","Utilizes GitHub repository data for accurate query results"],"zh":["toc","wiki","ask","Node.js","GitHub","AI"],"ja":["toc","wiki","ask","Node.js","GitHub","AI"],"ko":["toc","wiki","ask","Node.js","GitHub","AI"],"es":["Acceso a la documentación de repositorios GitHub públicos","Comandos como toc, wiki y ask para consultar documentación","Soporte para Node.js","Capacidad de búsqueda de respuestas en la documentación","Compatibilidad con múltiples repositorios"],"fr":["Accès à la documentation des dépôts GitHub publics","Commandes comme toc, wiki et ask pour interroger la documentation","Prise en charge de Node.js","Capacité de recherche de réponses dans la documentation","Compatibilité avec plusieurs dépôts"],"de":["Zugriff auf die Dokumentation öffentlicher GitHub-Repositorys","Befehle wie toc, wiki und ask zum Abfragen von Dokumentation","Unterstützung für Node.js","Fähigkeit, Antworten in der Dokumentation zu suchen","Kompatibilität mit mehreren Repositorys"],"pt":["Acesso a documentos de repositórios GitHub públicos via terminal","Comando `toc` para visualizar a tabela de conteúdo","Comando `wiki` para visualizar o conteúdo completo da wiki","Comando `ask` para realizar perguntas e obter respostas com suporte a IA","Suporte a múltiplos repositórios com o comando `ask`"],"ru":["Доступ к документам из публичных репозиториев GitHub через терминал","Команда `toc` для отображения таблицы содержания","Команда `wiki` для отображения полного содержания вики","Команда `ask` для задания вопросов и получения ответов с поддержкой ИИ","Поддержка нескольких репозиториев с помощью команды `ask`"],"ar":["الوصول إلى مستندات مستودعات جيثب العامة عبر الطرفية","الأمر `toc` لعرض جدول المحتويات","الأمر `wiki` لعرض المحتوى الكامل للويكي","الأمر `ask` لإصدار الأسئلة والحصول على الإجابات بدعم من الذكاء الاصطناعي","دعم عدة مستودعات مع الأمر `ask`"]},"keywords":{"en":["how to use deepwiki","what is deepwiki","deepwiki alternative","deepwiki vs git wiki","deepwiki install","deepwiki setup guide","github repository query","nodejs github integration","ai powered q&a for github"],"zh":["DeepWiki","AI","Node.js","GitHub","toc","wiki","ask","AI"],"ja":["DeepWiki","AI","Node.js","GitHub","toc","wiki","ask","AI"],"ko":["DeepWiki","AI","Node.js","GitHub","toc","wiki","ask","AI"],"es":["deepwiki","herramienta de línea de comandos","documentación de GitHub","repositorios GitHub públicos","AI para desarrolladores","Node.js","terminal","consulta de documentación"],"fr":["deepwiki","outil en ligne de commande","documentation GitHub","dépôts GitHub publics","IA pour les développeurs","Node.js","terminal","interrogation de documentation"],"de":["deepwiki","Kommandozeilen-Tool","GitHub-Dokumentation","öffentliches GitHub-Repository","KI für Entwickler","Node.js","Terminal","Abfrage von Dokumentation"],"pt":["DeepWiki","GitHub","terminal","Node.js","ferramenta de consulta","repositórios públicos","tabela de conteúdo","wiki","perguntas e respostas","IA"],"ru":["DeepWiki","GitHub","терминал","Node.js","инструмент запроса","публичные репозитории","таблица содержания","вики","вопросы и ответы","ИИ Агенты"],"ar":["ديبويكي","جيثب","الطرفية","نود.جس","أداة الاستعلام","مستودعات عامة","جدول المحتويات","الويكي","الأسئلة والإجابات","أدوات الذكاء الاصطناعي"]}},"owner":"kidow","repo":"dongwook.kim","repoPath":"kidow/dongwook.kim","stars":0,"forks":0,"updatedAt":"2026-03-07T15:58:00Z","topics":[],"category":"community","skillMd":{"name":"deepwiki","description":">","bodyPreview":"# deepwiki\n\nQuery any public GitHub repo''s docs from the terminal via DeepWiki. Assumes Node.js is installed.\n\n## Commands\n\n| Command | Usage | Description |\n|---------|-------|-------------|\n| `toc`   | `npx @seflless/deepwiki toc <owner/repo>` | Table of contents |\n| `wiki`  | `npx @seflless/deepwiki wiki <owner/repo>` | Full wiki content |\n| `ask`   | `npx @seflless/deepwiki ask <owner/repo> \"<question>\"` | AI-powered Q&A |\n| `ask`   | `npx @seflless/deepwiki ask <repo1> <repo2> \"<question>\"`","body":"# deepwiki\n\nQuery any public GitHub repo''s docs from the terminal via DeepWiki. Assumes Node.js is installed.\n\n## Commands\n\n| Command | Usage | Description |\n|---------|-------|-------------|\n| `toc`   | `npx @seflless/deepwiki toc <owner/repo>` | Table of contents |\n| `wiki`  | `npx @seflless/deepwiki wiki <owner/repo>` | Full wiki content |\n| `ask`   | `npx @seflless/deepwiki ask <owner/repo> \"<question>\"` | AI-powered Q&A |\n| `ask`   | `npx @seflless/deepwiki ask <repo1> <repo2> \"<question>\"` | Multi-repo Q&A (max 10) |\n\n## Flags\n\n| Flag | Purpose |\n|------|---------|\n| `--json` | Raw JSON output (good for piping) |\n| `-q, --quiet` | No spinners/progress |\n| `--no-color` | Disable colors |\n\n## Examples\n\n```bash\n# Understand a library''s structure\nnpx @seflless/deepwiki toc facebook/react\n\n# Get full docs for reference\nnpx @seflless/deepwiki wiki oven-sh/bun --json > bun-docs.json\n\n# Ask a specific question\nnpx @seflless/deepwiki ask anthropics/claude-code \"How does the tool permission system work?\"\n\n# Cross-project question\nnpx @seflless/deepwiki ask facebook/react vercel/next.js \"How do server components work across these projects?\"\n```\n\n## Tips\n\n- Use `--json` when you need structured data to parse\n- Use `toc` first to understand what docs exist, then `ask` for specifics\n- Multi-repo `ask` is great for understanding how libraries interact\n"},"lastSynced":"2026-03-08T02:14:25.756Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub Repository Analysis Agents needing direct access to table of contents, wiki content, and AI-powered Q&A capabilities.","zh":"适用于需要直接访问目录、Wiki 内容和 AI 驱动的 Q&A 能力的 GitHub 仓库分析代理。","ja":"GitHub リポジトリ分析エージェントが目次、Wiki コンテンツ、AI駆動のQ&A機能に直接アクセスする必要がある場合に最適です。","ko":"목차, 위키 내용, AI 기반 Q&A 기능에 직접 액세스해야 하는 GitHub 리포지토리 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis de Repositorios de GitHub que necesitan acceso directo a la tabla de contenidos, contenido de la wiki y capacidades de Preguntas y Respuestas impulsadas por IA.","fr":"Idéal pour les Agents d''Analyse de Repositories GitHub ayant besoin d''un accès direct au tableau de contenu, au contenu de la wiki et aux capacités de Questions et Réponses alimentées par l''IA.","de":"Ideal für GitHub-Repository-Analyse-Agents, die direkten Zugriff auf die Inhaltsverzeichnis, Wiki-Inhalt und künstliche Intelligenz-basierte Q&A-Funktionen benötigen.","pt":"Ideal para Agentes de Análise de Repositório do GitHub que precisam de acesso direto à tabela de conteúdo, conteúdo da wiki e capacidades de Q&A impulsionadas por IA.","ru":"Идеально для агентов анализа репозитория GitHub, которым требуется прямой доступ к таблице содержания, содержанию вики и возможностям Q&A, работающим на основе ИИ.","ar":"مثالي لعميل تحليل مخزن GitHub الذي يحتاج إلى وصول مباشر إلى جدول المحتويات ومحتوى الويكي وقدرات الإجابة والأسئلة المدعومة بالذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to query public GitHub repositories via Node.js, providing access to table of contents, full wiki content, and AI-powered Q&A using commands like `toc`, `wiki`, and `ask`, facilitating informed decision-making and automated documentation analysis.","zh":"赋予代理通过 Node.js 查询公共 GitHub 仓库的能力，提供访问目录、完整的 Wiki 内容和使用命令如 `toc`、`wiki` 和 `ask` 的 AI 驱动的 Q&A 能力，有助于明智的决策和自动化文档分析。","ja":"エージェントが Node.js 経由でパブリック GitHub リポジトリを照会する機能を提供し、目次へのアクセス、完全な Wiki コンテンツ、およびコマンド `toc`、`wiki`、`ask` を使用した AI ドライブの Q&A 機能を提供し、情報に基づいた意思決定と自動化されたドキュメント分析を促進します。","ko":"에이전트가 Node.js를 통해 공용 GitHub 리포지토리를 쿼리할 수 있는 기능을 제공하여 목차, 전체 위키 콘텐츠 및 명령 `toc`, `wiki`, `ask`를 사용하는 AI 기반 Q&A 기능에 액세스할 수 있으며, 이는 정보에 기반한 의사 결정 및 자동화된 문서 분석을 촉진합니다.","es":"Habilita a los agentes a consultar repositorios públicos de GitHub a través de Node.js, proporcionando acceso a la tabla de contenidos, contenido completo de la wiki y capacidades de Preguntas y Respuestas impulsadas por IA utilizando comandos como `toc`, `wiki` y `ask`, facilitando la toma de decisiones informadas y el análisis de documentación automatizado.","fr":"Permet aux agents d''interroger les repositories GitHub publics via Node.js, fournissant l''accès au tableau de contenu, au contenu complet de la wiki et aux capacités de Questions et Réponses alimentées par l''IA en utilisant des commandes comme `toc`, `wiki` et `ask`, facilitant la prise de décision éclairée et l''analyse de documentation automatisée.","de":"Ermächtigt die Agenten, öffentliche GitHub-Repositorys über Node.js abzufragen, indem sie Zugriff auf die Inhaltsverzeichnis, vollständigen Wiki-Inhalt und künstliche Intelligenz-basierte Q&A-Funktionen mithilfe von Befehlen wie `toc`, `wiki` und `ask` ermöglicht, um fundierte Entscheidungen und automatisierte Dokumentenanalyse zu erleichtern.","pt":"Permite que os agentes consultem repositórios públicos do GitHub por meio do Node.js, fornecendo acesso à tabela de conteúdo, ao conteúdo completo da wiki e às capacidades de Q&A impulsionadas por IA, utilizando comandos como `toc`, `wiki` e `ask`, facilitando a tomada de decisões informadas e a análise automatizada de documentação.","ru":"Позволяет агентам запрашивать публичные репозитории GitHub через Node.js, обеспечивая доступ к таблице содержания, полному содержанию вики и возможностям Q&A, работающим на основе ИИ, с использованием команд типа `toc`, `wiki` и `ask`, что облегчает принятие обоснованных решений и автоматизированный анализ документации.","ar":"تمكن العميل من استفسار مستودعات GitHub العامة عبر Node.js، وتوفير الوصول إلى جدول المحتويات ومحتوى الويكي الكامل وقدرات الإجابة والأسئلة المدعومة بالذكاء الاصطناعي باستخدام أوامر مثل `toc` و `wiki` و `ask`، وتسهيل اتخاذ القرارات المتعلقة بالاستفادة من المعلومات وتحليل الوثائق الآلي."},"useCases":{"en":["Querying table of contents for public GitHub repositories","Retrieving full wiki content for documentation analysis","Utilizing AI-powered Q&A for automated support and troubleshooting"],"zh":["查询公共 GitHub 仓库的目录","检索用于文档分析的完整 Wiki 内容","利用 AI 驱动的 Q&A 实现自动化支持和故障排除"],"ja":["パブリック GitHub リポジトリの目次を照会する","ドキュメント分析のための完全な Wiki コンテンツを取得する","自動化されたサポートとトラブルシューティングのために AI ドライブの Q&A を利用する"],"ko":["공용 GitHub 리포지토리의 목차 쿼리","문서 분석을 위한 전체 위키 콘텐츠 가져오기","자동화된 지원 및 문제 해결을 위한 AI 기반 Q&A 활용"],"es":["Consulta de la tabla de contenidos para repositorios públicos de GitHub","Recuperación de contenido completo de la wiki para análisis de documentación","Uso de Preguntas y Respuestas impulsadas por IA para soporte y solución de problemas automatizados"],"fr":["Interrogation du tableau de contenu pour les repositories GitHub publics","Récupération du contenu complet de la wiki pour l''analyse de documentation","Utilisation de Questions et Réponses alimentées par l''IA pour un support et une résolution de problèmes automatisés"],"de":["Abfrage der Inhaltsverzeichnis für öffentliche GitHub-Repositorys","Abruf des vollständigen Wiki-Inhalts für die Dokumentenanalyse","Verwendung von künstliche Intelligenz-basierten Q&A-Funktionen für automatisierten Support und Fehlerbehebung"],"pt":["Consulta de tabela de conteúdo para repositórios públicos do GitHub","Recuperação de conteúdo completo da wiki para análise de documentação","Utilização de Q&A impulsionada por IA para suporte automatizado e solução de problemas"],"ru":["Запрос таблицы содержания для публичных репозиториев GitHub","Получение полного содержания вики для анализа документации","Использование Q&A, работающей на основе ИИ, для автоматизированной поддержки и устранения неполадок"],"ar":["استفسار جدول المحتويات لمستودعات GitHub العامة","استرجاع محتوى الويكي الكامل لتحليل الوثائق","استخدام الإجابة والأسئلة المدعومة بالذكاء الاصطناعي للدعم الآلي ومعالجة الأعطال"]},"limitations":{"en":["Requires Node.js installation","Limited to public GitHub repositories","Dependent on repository maintainers for up-to-date documentation"],"zh":["需要 Node.js 安装","仅限公共 GitHub 仓库","依赖于仓库维护者以获取最新文档"],"ja":["Node.js のインストールが必要","パブリック GitHub リポジトリのみ","最新のドキュメントを取得するためにリポジトリのメンテナに依存"],"ko":["Node.js 설치가 필요함","공용 GitHub 리포지토리만 해당","최신 문서를 얻기 위해 리포지토리 유지 관리자에 의존"],"es":["Requiere instalación de Node.js","Limitado a repositorios públicos de GitHub","Dependiente de los mantenedores del repositorio para la documentación actualizada"],"fr":["Nécessite l''installation de Node.js","Limité aux repositories GitHub publics","Dépend des maintainers du repository pour la documentation à jour"],"de":["Benötigt Node.js-Installation","Begrenzt auf öffentliche GitHub-Repositorys","Abhängig von den Repository-Betreuern für aktuelle Dokumentation"],"pt":["Requer instalação do Node.js","Limitado a repositórios públicos do GitHub","Dependente dos mantenedores do repositório para documentação atualizada"],"ru":["Требуется установка Node.js","Ограничен публичными репозиториями GitHub","Зависит от обслуживающих репозиторий для актуальной документации"],"ar":["يتطلب تثبيت Node.js","محدود بمستودعات GitHub العامة","يعتمد على من يصون المستودع للحصول على وثائق محدثة"]},"version":4},"contentHash":"cd0dadf31266cdf2ecbe9c129357133f105078d93e9c714d929378feaf3c4e63","qualityScore":54}');
