INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('skilluse/skilluse/work', 'work', 'skilluse', 'skilluse', 'community', 'work skilluse skilluse community AI智能代理工作涉及Agent Skills Registry和CLI，帮助开发者高效管理和部署AI代理 AIエージェントの仕事にはAgent Skills RegistryとCLIが含まれており、開発者がAIエージェントを効率的に管理およびデプロイできるようにします AI 에이전트 작업에는 Agent Skills Registry와 CLI가 포함되어 있으며 개발자가 AI 에이전트를 효율적으로 관리하고 배포할 수 있도록 합니다 El Registro de Agentes y la CLI permite a los desarrolladores interactuar con herramientas de AI de manera eficiente Le Registre des Agents et la CLI permet aux développeurs d''interagir avec des outils IA de manière efficace Das Registry und die CLI ermöglicht es Entwicklern, mit AI-Tools effizient zu interagieren O Registo e CLI de Agente de IA é uma ferramenta poderosa para desenvolvedores que trabalham com aplicações de trabalho. Ele fornece uma interface de linha de comando para gerenciar Agentes de IA. Регистр и CLI ИИ Агентов - это мощный инструмент для разработчиков, работающих с приложениями для работы. Он предоставляет командную строку для управления ИИ Агентами. سجل و CLI للوكيل الذكي هو أداة قوية للمطورين الذين يعملون على تطبيقات العمل. يوفر واجهة سطر الأوامر لإدارة الوكيل الذكي. Agent Skills Registry & CLI AI智能代理工作 Agent Skills Registry CLI工具 AI代理管理 AI代理部署 开发效率提升 如何使用AI智能代理 AI智能代理工作原理 Agent Skills Registry & CLI');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ssdeanx/AgentStack/ai-elements', 'community', 'ssdeanx', 'AgentStack', 'ssdeanx/AgentStack', 'ai-elements', 17, 4, 54, '2026-02-28T10:10:13Z', '2026-03-01T05:18:11.216Z', '7e36e211495cf1ecfa6791c1e91cc53e253375cc5ee939d98656cc5a44d41fda', '{"id":"ssdeanx/AgentStack/ai-elements","name":"ai-elements","description":{"zh":"AgentStack是一种生产级的多智能体框架，提供企业工具和专业智能体，用于构建可扩展的AI系统","ja":"AgentStackは生産レベルのマルチエージェントフレームワークで、企業ツールと専門エージェントを提供して拡張可能なAIシステムを構築する","ko":"AgentStack는 생산급의 다중 에이전트 프레임워크로, 기업 도구와 전문 에이전트를 제공하여 확장 가능한 AI 시스템을 구축한다","es":"ai-elements es un framework de agentes de IA para sistemas escalables con 50+ herramientas empresariales y 25+ agentes especializados","fr":"ai-elements est un framework d''agents IA pour des systèmes évolutifs avec 50+ outils d''entreprise et 25+ agents spécialisés","de":"ai-elements ist ein Framework für KI-Agenten für skalierbare Systeme mit 50+ Unternehmens-Tools und 25+ spezialisierten Agenten","pt":"O AgentStack é um framework de multi-agente para sistemas de IA escaláveis, com foco em inteligência financeira, pipelines RAG e governança segura","ru":"AgentStack - это фреймворк для многоагентных систем ИИ, ориентированный на финансовую разведку, конвейеры RAG и безопасное управление","ar":"AgentStack هو إطار عمل متعدد الوكلاء لنظم الذكاء الاصطناعي القابلة للتوسيع، يركز على الذكاء المالي ومواقف RAG والحوكمة الآمنة","en":"AgentStack is a production-grade multi-agent framework built on Mastra, delivering 50+ enterprise tools, 25+ specialized agents, and A2A/MCP orchestration for scalable AI systems. Focuses on financial intelligence, RAG pipelines, observability, and secure governance. ACP Openclaw, Gemini CLI, Ope..."},"seo":{"title":{"zh":"AI智能代理 - AgentStack","ja":"AIエージェント - AgentStack","ko":"AI 에이전트 - AgentStack","es":"Agentes de IA: ai-elements para sistemas escalables","