INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('unbound-tools/landing/address-review', 'address-review', 'unbound-tools', 'landing', 'community', 'address-review unbound-tools landing community The address-review skill enables developers to run A/B landing page experiments for unbound.tools, streamlining the feedback process on GitHub PRs. It benefits developers working on data-driven projects. Address Review是一种用于代码审查的AI工具，通过GH API和CLI命令实现代码反馈和审查 Address Reviewは、GH APIとCLIコマンドを使用してコードのフィードバックとレビューを行うAIエージェントです Address Review는 GH API와 CLI 명령을 사용하여 코드 피드백과 리뷰를 수행하는 AI 툴입니다 Address-review es una herramienta para experimentos de landing page que utiliza GitHub API y CLI para recopilar comentarios y mejorar el proceso de revisión. Address-review est un outil pour les expériences de page de destination qui utilise GitHub API et CLI pour collecter des commentaires et améliorer le processus de révision. Address-review ist ein Tool für Landingpage-Experimente, das GitHub API und CLI verwendet, um Kommentare zu sammeln und den Überprüfungsprozess zu verbessern. O address-review é uma ferramenta para experimentos de página de destino que ajuda a otimizar testes A/B. Com ele, você pode analisar e melhorar a eficácia de suas páginas de destino Address-review - это инструмент для экспериментов с посадочными страницами, который помогает оптимизировать тесты А/Б. С его помощью вы можете проанализировать и улучшить эффективность своих посадочных страниц для ИИ Агентов address-review هو أداة لتحسين تجارب صفحة الهبوط التي تساعد على تحسين اختبارات A/B. باستخدامها، يمكنك تحليل وتحسينประส्टमج صفحات الهبوط باستخدام أدوات الذكاء الاصطناعي how to use address-review address-review setup guide what is address-review address-review alternative address-review vs optimizely address-review install for unbound.tools github pr feedback integration ab landing page experiment tools Address Review AI工具 代码审查 GH API CLI命令 代码反馈 JQ JSON数据处理 Executes !gh pr view command to retrieve PR context Utilizes !gh api to fetch pull request comments Leverages jq for JSON parsing and comment analysis Supports categorization of review comments for efficient feedback processing Enables adversarial feedback verification for accuracy address-review is a skill that facilitates A/B landing page experiments for unbound.tools, utilizing GitHub PR feedback and comments');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('renpereiradx/erp-webapp/enhance-prompt', 'community', 'renpereiradx', 'erp-webapp', 'renpereiradx/erp-webapp', 'enhance-prompt', 0, 0, 54, '2026-03-06T06:23:00.224Z', '2026-03-06T08:34:37.766Z', 'ccb200c798072438b642b1fa6a5c515563159e2fab3d56e813d76d8afa9a7ce6', '{"id":"renpereiradx/erp-webapp/enhance-prompt","name":"enhance-prompt","description":{"en":"The enhance-prompt skill helps Stitch Prompt Engineers optimize UI generation ideas into effective prompts, resulting in better Stitch outputs. It benefits developers working with Stitch.","zh":"增强提示是Stitch Prompt Engineer的关键技能，用于将粗糙或模糊的UI生成想法转换为精致的优化提示。","ja":"エンハンスプロンプトは、Stitch Prompt Engineerの重要なスキルであり、粗いまたは漠然としたUI生成アイデアを洗練された最適化プロンプトに変換するために使用されます。","ko":"엔하ンス 프롬프트는 Stitch Prompt Engineer의 중요한 기술입니다. 이는 조잡하거나 모호한 UI 생성 아이디어를 세련된 최적화 프롬프트로 변환하는 데 사용됩니다.","es":"El enhance-prompt es una habilidad que transforma ideas de generación de UI vagas en promtps optimizados para Stitch. Consulta la guía de Stitch para las mejores prácticas.","fr":"L''enhance-prompt est une compétence qui transforme des idées de génération d''UI vagues en invites optimisées pour Stitch. Consultez le guide de Stitch pour les meilleures pratiques.","de":"Das enhance-prompt ist eine Fähigkeit, die vage UI-Generierungs-Ideen in optimierte Prompts für Stitch umwandelt. Siehe die Stitch-Anleitung für die besten Praktiken.","pt":"Enhance-Prompt é uma habilidade que transforma ideias vagas de geração de UI em prompts otimizados para Stitch.","ru":"Enhance-Prompt - это навык, который преобразует расплывчатые идеи генерации UI в оптимизированные промпты для Stitch.","ar":"Enhance-Prompt هو مهارة تحول الأفكار الغامضة لجينيرات UI إلى Prompts مثالية لستيتش."},"seo":{"title":{"en":"enhance-prompt: Optimized Prompt Engineering for Stitch |...","zh":"增强提示设置指南 - AI工具","ja":"Enhance Prompt Setup Guide - AIエージェント","ko":"엔하ンス 프롬프트 설정 가이드 - AI 에이전트","es":"Guía de configuración para enhance-prompt: Mejora de prom...","fr":"Guide de configuration pour enhance-prompt: Amélioration ...","de":"Konfigurationsleitfaden für enhance-prompt: Optimierung v...","pt":"Guia de Configuração do Enhance-Prompt para Stitch","ru":"Настройка Enhance-Prompt для Stitch: Руководство ИИ Агентов","ar":"دليل إعداد Enhance-Prompt لستيتش: أدوات ذكاء اصطناعي"},"description":{"en":"Unlock better UI generation results with enhance-prompt. Learn how to transform rough ideas into polished prompts and explore the Stitch Effective Prompting ...","zh":"了解如何优化提示以获得更好的Stitch结果。查看我们的增强提示设置指南，包含最佳实践和技术细节。","ja":"Stitchの結果を改善するためのプロンプト最適化の方法について学びます。ベストプラクティスとテクニカル詳細を含むエンハンスプロンプト設定ガイドを参照してください。","ko":"Stitch 결과를 개선하는 팁 최적화 방법에 대해 알아보세요. 최선의 thực践과 기술 세부 사항을 포함하는 Enhance Prompt 설정 가이드를 참조하십시오.","es":"Aprende a mejorar tus promtps para Stitch con nuestra guía de enhance-prompt. Mejora la generación de UI con promtps optimizados.","fr":"Découvrez comment améliorer vos invites pour Stitch avec notre guide enhance-prompt. Améliorez la génération d''UI avec des invites optimisées.","de":"Erfahren Sie, wie Sie Ihre Prompts für Stitch mit unserem enhance-prompt-Leitfaden verbessern können. Optimieren Sie die UI-Generierung mit optimierten Prompts.","pt":"Aprenda a melhorar prompts para Stitch com nosso guia de configuração. Descubra as melhores práticas para otimizar resultados de UI","ru":"Узнайте, как улучшить промпты для Stitch с нашим руководством. Откройте для себя лучшие практики для оптимизации результатов UI с помощью ИИ Агентов","ar":"تعلم كيف تحسن ال_prompts لستيتش مع دليلنا. اكتشف أفضل الممارسات لتحسين نتائج UI مع أدوات الذكاء الاصطناعي"},"definition":{"en":"enhance-prompt is a skill that transforms vague UI generation ideas into optimized prompts for improved Stitch results.","zh":"增强提示是指优化Stitch提示以获得更好结果的过程。","ja":"エンハンスプロンプトとは、Stitchのプロンプトを最適化してより良い結果を得るためのプロセスです。","ko":"엔하ンス 프롬프트는 더 나은 결과를 얻기 위해 Stitch 프롬프트를 최적화하는 과정입니다.","es":"El enhance-prompt es una habilidad que optimiza promtps para la generación de UI en Stitch.","fr":"L''enhance-prompt est une compétence qui optimise les invites pour la génération d''UI dans Stitch.","de":"Das enhance-prompt ist eine Fähigkeit, die Prompts für die UI-Generierung in Stitch optimiert.","pt":"O que é Enhance-Prompt? É uma habilidade que melhora prompts para Stitch.","ru":"Что такое Enhance-Prompt? Это навык, который улучшает промпты для Stitch.","ar":"ما هو Enhance-Prompt? هو مهارة تحسن ال_prompts لستيتش."},"features":{"en":["Consults the official Stitch documentation for best practices","Utilizes the Stitch Effective Prompting Guide for up-to-date recommendations","Transforms rough UI generation ideas into polished prompts","Produces better results from Stitch through optimized prompting","Follows the latest guidelines from https://stitch.withgoogle.com/docs/learn/prompting/"],"zh":["根据Stitch Effective Prompting Guide进行优化","支持Stitch最新的最佳实践","能够将粗糙的UI生成想法转换为精致的优化提示","提高Stitch结果的准确性和相关性","支持Stitch Prompt Engineer的工作流程"],"ja":["Stitch Effective Prompting Guideに基づく最適化","Stitchの最新のベストプラクティスをサポート","粗いUI生成アイデアを洗練された最適化プロンプトに変換する機能","Stitchの結果の精度と関連性の向上","Stitch Prompt Engineerのワークフローをサポート"],"ko":["Stitch Effective Prompting Guide를 기반으로 최적화","Stitch의 최신 베스트 프랙티스를 지원","조잡한 UI 생성 아이디어를 세련된 최적화 프롬프트로 변환하는 기능","Stitch 결과의 정확성과 관련성을 향상","Stitch Prompt Engineer의 워크플로우를 지원"],"es":["Transformación de ideas de generación de UI vagas en promtps optimizados","Mejora de la generación de UI con promtps personalizados","Integración con la guía de Stitch para las mejores prácticas","Optimización de promtps para mejores resultados","Compatibilidad con la guía de Stitch Effective Prompting"],"fr":["Transformation d''idées de génération d''UI vagues en invites optimisées","Amélioration de la génération d''UI avec des invites personnalisées","Intégration avec le guide de Stitch pour les meilleures pratiques","Optimisation d''invites pour de meilleurs résultats","Compatibilité avec le guide de Stitch Effective Prompting"],"de":["Umwandlung von vagen UI-Generierungs-Ideen in optimierte Prompts","Verbesserung der UI-Generierung mit benutzerdefinierten Prompts","Integration mit der Stitch-Anleitung für die besten Praktiken","Optimierung von Prompts für bessere Ergebnisse","Kompatibilität mit der Stitch Effective Prompting-Anleitung"],"pt":["Transformação de ideias vagas em prompts otimizados","Otimização de resultados de UI com Stitch","Consulta ao guia de boas práticas de Stitch","Melhoria da eficácia dos prompts","Integração com a documentação oficial de Stitch"],"ru":["Преобразование расплывчатых идей в оптимизированные промпты","Оптимизация результатов UI с помощью Stitch","Консультация руководства по лучшим практикам Stitch","Улучшение эффективности промптов","Интеграция с официальной документацией Stitch и ИИ Агентами"],"ar":["تحويل الأفكار الغامضة إلى Prompts مثالية","تحسين نتائج UI مع ستيتش","الاستعانة بدليل أفضل الممارسات لستيتش","تحسين فعالية ال_Prompts","التكامل مع الوثائق الرسمية لستيتش وأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use enhance-prompt","what is enhance-prompt","enhance-prompt setup guide","Stitch Effective Prompting Guide","enhance-prompt for AI agents","optimized prompt engineering for Stitch"],"zh":["增强提示","Stitch提示优化","AI工具","Stitch Effective Prompting Guide","Stitch Prompt Engineer","UI生成","最优化提示"],"ja":["エンハンスプロンプト","Stitchプロンプト最適化","AIエージェント","Stitch Effective Prompting Guide","Stitch Prompt Engineer","UI生成","最適化プロンプト"],"ko":["엔하ンス 프롬프트","Stitch 프롬프트 최적화","AI 에이전트","Stitch Effective Prompting Guide","Stitch Prompt Engineer","UI 생성","최적화 프롬프트"],"es":["enhance-prompt","Stitch","generación de UI","promtps optimizados","guía de Stitch","mejores prácticas","optimización de promtps","invitación personalizada","IA Agentes","herramientas de desarrollo"],"fr":["enhance-prompt","Stitch","génération d''UI","invites optimisées","guide de Stitch","meilleures pratiques","optimisation d''invites","invitation personnalisée","Outils d''IA","outils de développement"],"de":["enhance-prompt","Stitch","UI-Generierung","optimierte Prompts","Stitch-Anleitung","beste Praktiken","Optimierung von Prompts","benutzerdefinierte Einladung","KI-Tools","Entwicklungstools"],"pt":["enhance-prompt","stitch","guias de configuração","otimização de ui","boas práticas de stitch","desenvolvimento de ui","ferramentas de ui","ai agents","ferramentas de inteligência artificial"],"ru":["enhance-prompt","stitch","руководство по настройке","оптимизация ui","лучшие практики stitch","разработка ui","инструменты ui","ИИ Агенты","инструменты искусственного интеллекта"],"ar":["enhance-prompt","ستيتش","دليل الإعداد","تحسين ui","أفضل الممارسات لستيتش","تطوير ui","أدوات ui","أدوات الذكاء الاصطناعي","وكيل إصطناعي"]}},"owner":"renpereiradx","repo":"erp-webapp","repoPath":"renpereiradx/erp-webapp","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.224Z","topics":[],"category":"community","skillMd":{"name":"enhance-prompt","description":"Transforms vague UI ideas into polished, Stitch-optimized prompts. Enhances specificity, adds UI/UX keywords, injects design system context, and structures output for better generation results.","bodyPreview":"# Enhance Prompt for Stitch\n\nYou are a **Stitch Prompt Engineer**. Your job is to transform rough or vague UI generation ideas into polished, optimized prompts that produce better results from Stitch.\n\n## Prerequisites\n\nBefore enhancing prompts, consult the official Stitch documentation for the latest best practices:\n\n- **Stitch Effective Prompting Guide**: https://stitch.withgoogle.com/docs/learn/prompting/\n\nThis guide contains up-to-date recommendations that may supersede or complement the pat","body":"# Enhance Prompt for Stitch\n\nYou are a **Stitch Prompt Engineer**. Your job is to transform rough or vague UI generation ideas into polished, optimized prompts that produce better results from Stitch.\n\n## Prerequisites\n\nBefore enhancing prompts, consult the official Stitch documentation for the latest best practices:\n\n- **Stitch Effective Prompting Guide**: https://stitch.withgoogle.com/docs/learn/prompting/\n\nThis guide contains up-to-date recommendations that may supersede or complement the patterns in this skill.\n\n## When to Use This Skill\n\nActivate when a user wants to:\n- Polish a UI prompt before sending to Stitch\n- Improve a prompt that produced poor results\n- Add design system consistency to a simple idea\n- Structure a vague concept into an actionable prompt\n\n## Enhancement Pipeline\n\nFollow these steps to enhance any prompt:\n\n### Step 1: Assess the Input\n\nEvaluate what''s missing from the user''s prompt:\n\n| Element | Check for | If missing... |\n|---------|-----------|---------------|\n| **Platform** | \"web\", \"mobile\", \"desktop\" | Add based on context or ask |\n| **Page type** | \"landing page\", \"dashboard\", \"form\" | Infer from description |\n| **Structure** | Numbered sections/components | Create logical page structure |\n| **Visual style** | Adjectives, mood, vibe | Add appropriate descriptors |\n| **Colors** | Specific values or roles | Add design system or suggest |\n| **Components** | UI-specific terms | Translate to proper keywords |\n\n### Step 2: Check for DESIGN.md\n\nLook for a `DESIGN.md` file in the current project:\n\n**If DESIGN.md exists:**\n1. Read the file to extract the design system block\n2. Include the color palette, typography, and component styles\n3. Format as a \"DESIGN SYSTEM (REQUIRED)\" section in the output\n\n**If DESIGN.md does not exist:**\n1. Add this note at the end of the enhanced prompt:\n\n```\n---\n💡 **Tip:** For consistent designs across multiple screens, create a DESIGN.md \nfile using the `design-md` skill. This ensures all generated pages share the \nsame visual language.\n```\n\n### Step 3: Apply Enhancements\n\nTransform the input using these techniques:\n\n#### A. Add UI/UX Keywords\n\nReplace vague terms with specific component names:\n\n| Vague | Enhanced |\n|-------|----------|\n| \"menu at the top\" | \"navigation bar with logo and menu items\" |\n| \"button\" | \"primary call-to-action button\" |\n| \"list of items\" | \"card grid layout\" or \"vertical list with thumbnails\" |\n| \"form\" | \"form with labeled input fields and submit button\" |\n| \"picture area\" | \"hero section with full-width image\" |\n\n#### B. Amplify the Vibe\n\nAdd descriptive adjectives to set the mood:\n\n| Basic | Enhanced |\n|-------|----------|\n| \"modern\" | \"clean, minimal, with generous whitespace\" |\n| \"professional\" | \"sophisticated, trustworthy, with subtle shadows\" |\n| \"fun\" | \"vibrant, playful, with rounded corners and bold colors\" |\n| \"dark mode\" | \"dark theme with high-contrast accents on deep backgrounds\" |\n\n#### C. Structure the Page\n\nOrganize content into numbered sections:\n\n```markdown\n**Page Structure:**\n1. **Header:** Navigation with logo and menu items\n2. **Hero Section:** Headline, subtext, and primary CTA\n3. **Content Area:** [Describe the main content]\n4. **Footer:** Links, social icons, copyright\n```\n\n#### D. Format Colors Properly\n\nWhen colors are mentioned, format them as:\n```\nDescriptive Name (#hexcode) for functional role\n```\n\nExamples:\n- \"Deep Ocean Blue (#1a365d) for primary buttons and links\"\n- \"Warm Cream (#faf5f0) for page background\"\n- \"Soft Gray (#6b7280) for secondary text\"\n\n### Step 4: Format the Output\n\nStructure the enhanced prompt in this order:\n\n```markdown\n[One-line description of the page purpose and vibe]\n\n**DESIGN SYSTEM (REQUIRED):**\n- Platform: [Web/Mobile], [Desktop/Mobile]-first\n- Theme: [Light/Dark], [style descriptors]\n- Background: [Color description] (#hex)\n- Primary Accent: [Color description] (#hex) for [role]\n- Text Primary: [Color description] (#hex)\n- [Additional design tokens...]\n\n**Page Structure:**\n1. **[Section]:** [Description]\n2. **[Section]:** [Description]\n...\n```\n\n## Output Options\n\n**Default:** Return the enhanced prompt as text for the user to copy.\n\n**Optional file output:** If the user requests, write to a file:\n- `next-prompt.md` — for use with the `stitch-loop` skill\n- Custom filename specified by user\n\n## Examples\n\n### Example 1: Vague Input → Structured Prompt\n\n**User input:**\n> \"make me a login page\"\n\n**Enhanced output:**\n```markdown\nA clean, trustworthy login page with a centered form and subtle branding.\n\n**DESIGN SYSTEM (REQUIRED):**\n- Platform: Web, Desktop-first\n- Theme: Light, minimal, professional\n- Background: Clean White (#ffffff)\n- Surface: Soft Gray (#f9fafb) for form card\n- Primary Accent: Deep Blue (#2563eb) for submit button and links\n- Text Primary: Near Black (#111827) for headings\n- Text Secondary: Medium Gray (#6b7280) for labels\n- Buttons: Subtly rounded (8px), full-width on form\n- Cards: Gently rounded (12px), soft shadow for elevation\n\n**Page Structure:**\n1. **Header:** Minimal logo, centered\n2. **Login Card:** Centered form with email, password fields, \"Forgot password?\" link\n3. **Submit Button:** Primary blue \"Sign In\" button\n4. **Footer:** \"Don''t have an account? Sign up\" link\n\n---\n💡 **Tip:** For consistent designs across multiple screens, create a DESIGN.md \nfile using the `design-md` skill.\n```\n\n### Example 2: Feature Request → Targeted Edit\n\n**User input:**\n> \"add a search bar\"\n\n**Enhanced output:**\n```markdown\nAdd a search bar to the header navigation.\n\n**Specific changes:**\n- Location: Header, right side before user avatar\n- Style: Pill-shaped input with subtle gray background (#f3f4f6)\n- Icon: Magnifying glass icon on the left, inside the input\n- Placeholder: \"Search...\" in light gray (#9ca3af)\n- Behavior: Expands on focus with subtle shadow\n- Width: 240px default, 320px on focus\n\n**Context:** This is a targeted edit. Make only this change while preserving all existing elements.\n```\n\n## Tips for Best Results\n\n1. **Be specific early** — Vague inputs need more enhancement\n2. **Match the user''s intent** — Don''t over-design if they want simple\n3. **Keep it structured** — Numbered sections help Stitch understand hierarchy\n4. **Include the design system** — Consistency is key for multi-page projects\n5. **One change at a time for edits** — Don''t bundle unrelated changes\n"},"lastSynced":"2026-03-06T08:34:37.766Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Model Agents needing to optimize UI generation prompts for Stitch outputs.","zh":"非常适合需要优化UI生成提示以输出Stitch的语言模型代理。","ja":"Stitchの出力を最適化するためにUI生成のプロンプトを最適化する必要があるLanguage Modelエージェントに最適です。","ko":"Stitch 출력을 최적화하기 위해 UI 생성 프롬프트를 최적화해야 하는 언어 모델 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Modelo de Lenguaje que necesitan optimizar las solicitudes de generación de UI para salidas de Stitch.","fr":"Parfait pour les agents de modèle de langage ayant besoin d''optimiser les invites de génération d''UI pour les sorties de Stitch.","de":"Perfekt für Language-Model-Agents, die die UI-Generierungsanfragen für Stitch-Ausgaben optimieren müssen.","pt":"Perfeito para Agentes de Modelo de Linguagem que precisam otimizar prompts de geração de UI para saídas do Stitch.","ru":"Идеально для агентов модели языка, которым необходимо оптимизировать запросы генерации пользовательского интерфейса для вывода Stitch.","ar":"مثالي لعميل نموذج اللغة الذي يحتاج إلى تحسين عناصر واجهة المستخدم لإخراج الستيتش."},"recommendation":{"en":"Empowers agents to transform rough UI generation ideas into polished, optimized prompts using the Stitch Effective Prompting Guide, resulting in better Stitch outputs through effective prompting techniques and best practices.","zh":"赋予代理能力，将粗糙的UI生成想法转化为精致的、优化的提示，使用Stitch有效提示指南，通过有效的提示技术和最佳实践，从而获得更好的Stitch输出。","ja":"Stitch Effective Prompting Guideを使用して、エージェントがUI生成のアイデアを洗練されたプロンプトに変換できるようにし、効果的なプロンプティング技術とベストプラクティスを使用して、よりよいStitchの出力を得ることができます。","ko":"Stitch Effective Prompting Guide를 사용하여 에이전트가 