INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ksolomon68/CaltransBizConnect/enhance-prompt', 'enhance-prompt', 'ksolomon68', 'CaltransBizConnect', 'community', 'enhance-prompt ksolomon68 CaltransBizConnect community The enhance-prompt skill transforms rough UI generation ideas into optimized prompts for Stitch, benefiting Stitch Prompt Engineers. It consults the official Stitch documentation for best practices. 增强提示是Stitch Prompt Engineer的主要职责，通过优化提示提高UI生成结果质量 エンハンスプロンプトはStitch Prompt Engineerの主な責任で、プロンプトを最適化してUI生成の結果を向上させる 프롬프트 강화는 Stitch 프롬프트 엔지니어의 주요 책임으로, 프롬프트를 최적화하여 UI 생성 결과의 품질을 높입니다 El skill enhance-prompt te permite transformar ideas vagas en prompts pulidos y optimizados para Stitch. Le skill enhance-prompt vous permet de transformer des idées vagues en prompts optimisés pour Stitch. Das Skill enhance-prompt ermöglicht es Ihnen, vage Ideen in polierte und optimierte Prompts für Stitch umzuwandeln. Melhore prompts para Stitch com nosso guia de configuração e obtenha resultados mais precisos Улучшите промпты для Stitch с помощью нашего руководства и получите более точные результаты حسن الإشعارات لستيتش مع دليلنا الإرشادي و احصل على نتائج أكثر دقة how to use enhance-prompt what is enhance-prompt enhance-prompt setup guide Stitch Effective Prompting Guide enhance-prompt for Stitch optimized prompt engineering Stitch prompt optimization enhance-prompt install enhance-prompt tutorial 增强提示 Stitch Prompt Engineer AI工具 UI生成 提示优化 Stitch Effective Prompting Guide Consults the official Stitch documentation for the latest best practices Follows the Stitch Effective Prompting Guide for optimized prompts Transforms rough or vague UI generation ideas into polished prompts Produces better results from Stitch using optimized prompts Utilizes the https://stitch.withgoogle.com/docs/learn/prompting/ guide for up-to-date recommendations enhance-prompt is a skill that optimizes prompts for Stitch, a UI generation tool, to produce better results by following the Stitch Effective Prompting Guide.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('leboncoin/spark-web/run-quality-checks', 'community', 'leboncoin', 'spark-web', 'leboncoin/spark-web', 'run-quality-checks', 87, 21, 53, '2026-02-23T15:02:50Z', '2026-03-06T06:33:21.937Z', '5b96db7ce1d21d07794bb2eb33664e14700125d431253748ace969bc2f43c6cb', '{"id":"leboncoin/spark-web/run-quality-checks","name":"run-quality-checks","description":{"en":"The run-quality-checks skill executes all code quality checks for React applications, benefiting developers who want to verify code quality before committing or preparing a PR.","zh":"运行质量检查工具是一种用于检查React代码质量的工具，包括linting、type checking和formatting","ja":"コード品質チェックツールは、Reactコードの品質をチェックするためのツールです","ko":"코드 품질检查 도구는 React 코드 품질을 확인하는 도구입니다","es":"Ejecuta comprobaciones de calidad de código para tu proyecto React con herramientas como ESLint, Type Checking y Prettier","fr":"Exécutez des vérifications de qualité de code pour votre projet React avec des outils tels que ESLint, Type Checking et Prettier","de":"Führen Sie Code-Quality-Checks für Ihr React-Projekt mit Tools wie ESLint, Type Checking und Prettier durch","pt":"O run-quality-checks é uma ferramenta que executa verificações de qualidade de código para o projeto Spark UI, incluindo linting, type checking e formatação","ru":"ИИ Агент run-quality-checks выполняет проверки качества кода для проекта Spark UI, включая linting, type checking и форматирование","ar":"أداة الذكاء الاصطناعي run-quality-checks تقوم بتشغيل عمليات فحص الجودة للكود في مشروع Spark UI، بما في ذلك فحص الأخطاء و فحص الأنواع و التنسيق"},"seo":{"title":{"en":"run-quality-checks: Code Quality Setup Guide | AI Agent S...","zh":"运行质量检查工具：React代码质量检查Setup Guide","ja":"コード品質チェックツール：React AIエージェントのBest Practices","ko":"코드 품질检查 도구: React AI Tools Setup Guide","es":"Herramientas de calidad de código para React: Guía de con...","fr":"Outils de qualité de code pour React: Meilleures pratiques","de":"Code-Quality-Tools für React: Einrichtungsleitfaden","pt":"Guia de Configuração do run-quality-checks para Desenvolv...","ru":"Настройка ИИ Агента run-quality-checks: Лучшие Практики","ar":"إعداد أداة الذكاء الاصطناعي run-quality-checks: دليل المس..."},"description":{"en":"Discover how to ensure code integrity with run-quality-checks. Learn to execute linting, type checking, and formatting with ease. Get started now!","zh":"使用运行质量检查工具，确保React代码质量，包括linting、type checking和formatting","ja":"Reactコードの品質をチェックするためのツール。linting、type checking、formattingを実行します","ko":"React 코드 품질을 확인하는 도구입니다. linting, type checking, formatting을 지원합니다","es":"Aprende a ejecutar comprobaciones de calidad de código para tu proyecto React con ESLint, Type Checking y Prettier","fr":"Découvrez comment exécuter des vérifications de qualité de code pour votre projet React avec ESLint, Type Checking et Prettier","de":"Erfahren Sie, wie Sie Code-Quality-Checks für Ihr React-Projekt mit ESLint, Type Checking und Prettier durchführen","pt":"Aprenda a executar verificações de qualidade de código com o run-quality-checks, incluindo linting, type checking e formatação com ESLint e TypeScript","ru":"Выполните проверки качества кода с помощью ИИ Агента run-quality-checks, включая linting, type checking и форматирование с ESLint и TypeScript","ar":"تعلم كيفية تشغيل عمليات فحص الجودة باستخدام أداة الذكاء الاصطناعي run-quality-checks، بما في ذلك فحص الأخطاء و فحص الأنواع و التنسيق باستخدام ESLint و TypeSc..."},"definition":{"en":"run-quality-checks is a skill that executes code quality checks, including linting, type checking, and formatting, to ensure high-quality code in React applications.","zh":"运行质量检查工具是一种用于检查代码质量的工具，确保代码符合一定的标准","ja":"コード品質チェックツールは、コードの品質をチェックするためのツールです","ko":"코드 품질检查 도구는 코드 품질을 확인하는 도구입니다","es":"Un conjunto de herramientas para comprobar la calidad del código en proyectos React","fr":"Un ensemble d''outils pour vérifier la qualité du code dans les projets React","de":"Eine Sammlung von Tools zur Überprüfung der Code-Qualität in React-Projekten","pt":"O run-quality-checks é uma ferramenta de verificação de qualidade de código que executa linting, type checking e formatação","ru":"ИИ Агент run-quality-checks - это инструмент проверки качества кода, который выполняет linting, type checking и форматирование","ar":"أداة الذكاء الاصطناعي run-quality-checks هي أداة فحص الجودة للكود التي تقوم بتشغيل عمليات فحص الأخطاء و فحص الأنواع و التنسيق"},"features":{"en":["Executes linting with ESLint via npm run lint","Performs type checking with TypeScript via npm run typecheck","Enforces code formatting with Prettier via npm run prettier","Supports React applications with modular and accessible UI components","Utilizes Tailwind CSS for styling and design system consistency","Leverages React Hooks for efficient and scalable component development"],"zh":["支持linting，使用ESLint检查代码风格和质量","支持type checking，使用TypeScript检查类型","支持formatting，使用Prettier格式化代码"],"ja":["lintingをサポートし、ESLintを使用してコードスタイルと品質をチェックします","type checkingをサポートし、TypeScriptを使用して型をチェックします","formattingをサポートし、Prettierを使用してコードを整形します"],"ko":["linting을 지원하여 ESLint를 사용하여 코드 스타일과 품질을 확인합니다","type checking을 지원하여 TypeScript를 사용하여 유형을 확인합니다","formatting을 지원하여 Prettier를 사용하여 코드를 정렬합니다"],"es":["Ejecución de comprobaciones de estilo de código con ESLint","Verificación de tipos con Type Checking","Formato de código con Prettier","Compatibilidad con React y TypeScript","Integración con Tailwind CSS","Soporte para comandos de línea de comando (CLI)"],"fr":["Exécution de vérifications de style de code avec ESLint","Vérification de types avec Type Checking","Formatage de code avec Prettier","Compatibilité avec React et TypeScript","Intégration avec Tailwind CSS","Prise en charge des commandes de ligne de commande (CLI)"],"de":["Ausführung von Code-Stil-Checks mit ESLint","Überprüfung von Typen mit Type Checking","Code-Formatierung mit Prettier","Kompatibilität mit React und TypeScript","Integration mit Tailwind CSS","Unterstützung für Befehlszeilen-Tools (CLI)"],"pt":["Execução de linting com ESLint","Verificação de tipos com TypeScript","Formatação de código com Prettier","Suporte ao projeto Spark UI","Integração com React e Tailwind CSS","Compatibilidade com npm e CLI"],"ru":["Выполнение linting с помощью ESLint","Проверка типов с помощью TypeScript","Форматирование кода с помощью Prettier","Поддержка проекта Spark UI","Интеграция с React и Tailwind CSS","Совместимость с npm и CLI"],"ar":["تشغيل فحص الأخطاء باستخدام ESLint","فحص الأنواع باستخدام TypeScript","تنسيق الكود باستخدام Prettier","دعم مشروع Spark UI","التكامل مع React و Tailwind CSS","التوافق مع npm و CLI"]},"keywords":{"en":["how to use run-quality-checks","run-quality-checks setup guide","run-quality-checks alternative","run-quality-checks vs eslint","install run-quality-checks","run-quality-checks for React developers","code quality checks for React","run-quality-checks tutorial","run-quality-checks best practices"],"zh":["React代码质量检查","运行质量检查工具","linting","type checking","formatting","ESLint","TypeScript","Prettier"],"ja":["Reactコード品質チェック","コード品質チェックツール","linting","type checking","formatting","ESLint","TypeScript","Prettier","AIエージェント"],"ko":["React 코드 품질检查","코드 품질检查 도구","linting","type checking","formatting","ESLint","TypeScript","Prettier","AI Tools"],"es":["herramientas de calidad de código","React","ESLint","Type Checking","Prettier","TypeScript","Tailwind CSS","CLI","comprobaciones de código","desarrollo de software"],"fr":["outils de qualité de code","React","ESLint","Type Checking","Prettier","TypeScript","Tailwind CSS","CLI","vérifications de code","développement de logiciels"],"de":["Code-Quality-Tools","React","ESLint","Type Checking","Prettier","TypeScript","Tailwind CSS","CLI","Code-Checks","Software-Entwicklung"],"pt":["run-quality-checks","verificação de qualidade de código","linting","type checking","formatação de código","ESLint","TypeScript","Prettier","React","Tailwind CSS"],"ru":["ИИ Агент run-quality-checks","проверка качества кода","linting","type checking","форматирование кода","ESLint","TypeScript","Prettier","React","Tailwind CSS"],"ar":["أداة الذكاء الاصطناعي run-quality-checks","فحص الجودة للكود","فحص الأخطاء","فحص الأنواع","تنسيق الكود","ESLint","TypeScript","Prettier","React","Tailwind CSS"]}},"owner":"leboncoin","repo":"spark-web","repoPath":"leboncoin/spark-web","stars":87,"forks":21,"updatedAt":"2026-02-23T15:02:50Z","topics":["a11y","design-system","react","react-components","react-hooks","tailwindcss","typescript","ui-library"],"category":"community","skillMd":{"name":"run-quality-checks","description":"Run all quality checks including linting, type checking, and tests. Use when the user wants to verify code quality, before committing, or when preparing a PR.","bodyPreview":"# Run Quality Checks\n\nExecute all code quality checks for the Spark UI project.\n\n## When to Use\n\n- Before committing code\n- When preparing a PR\n- User wants to verify code quality\n- User mentions \"lint\", \"typecheck\", or \"quality\"\n\n## Instructions\n\n1. **Linting**:\n   ```bash\n   npm run lint\n   ```\n   Checks code style and quality with ESLint.\n\n2. **Type Checking**:\n   ```bash\n   npm run typecheck\n   ```\n   Verifies TypeScript types are correct.\n\n3. **Formatting**:\n   ```bash\n   npm run prettier","body":"# Run Quality Checks\n\nExecute all code quality checks for the Spark UI project.\n\n## When to Use\n\n- Before committing code\n- When preparing a PR\n- User wants to verify code quality\n- User mentions \"lint\", \"typecheck\", or \"quality\"\n\n## Instructions\n\n1. **Linting**:\n   ```bash\n   npm run lint\n   ```\n   Checks code style and quality with ESLint.\n\n2. **Type Checking**:\n   ```bash\n   npm run typecheck\n   ```\n   Verifies TypeScript types are correct.\n\n3. **Formatting**:\n   ```bash\n   npm run prettier\n   ```\n   Checks and fixes code formatting.\n\n4. **All Formatting Checks**:\n   ```bash\n   npm run prettify\n   ```\n   Runs both lint and prettier.\n\n5. **Tests**:\n   ```bash\n   npm run test:run\n   ```\n   Runs all unit tests.\n\n6. **Test Coverage**:\n   ```bash\n   npm run test:coverage\n   ```\n   Generates coverage report.\n\n7. **E2E Tests**:\n   ```bash\n   npm run test:e2e\n   ```\n   Runs end-to-end tests with Playwright.\n\n8. **Accessibility Tests**:\n   ```bash\n   npm run test:a11y\n   ```\n   Runs accessibility tests.\n\n## Complete Quality Pipeline\n\nFor a complete check before PR:\n```bash\nnpm run lint && npm run typecheck && npm run test:run && npm run test:a11y\n```\n"},"lastSynced":"2026-03-06T06:33:21.937Z","agentAnalysis":{"suitability":{"en":"Ideal for React Development Agents requiring automated code quality validation using ESLint and TypeScript","zh":"适用于需要使用ESLint和TypeScript进行自动代码质量验证的React开发代理","ja":"React開発エージェントが自動的なコード品質の検証を使用するESLintとTypeScriptを必要とする場合に適しています","ko":"ESLint와 TypeScript를 사용하여 자동 코드 품질 검증이 필요한 React 개발 에이전트에 적합합니다","es":"Ideal para agentes de desarrollo de React que requieren una validación automática de la calidad del código utilizando ESLint y TypeScript","fr":"Idéal pour les agents de développement React nécessitant une validation automatique de la qualité du code à l''aide d''ESLint et de TypeScript","de":"Ideal für React-Entwicklungsagenten, die eine automatisierte Code-Qualitätsvalidierung mit ESLint und TypeScript erfordern","pt":"Ideal para Agentes de Desenvolvimento React que exigem validação automatizada da qualidade do código usando ESLint e TypeScript","ru":"Идеально для агентов разработки React, требующих автоматизированной проверки качества кода с помощью ESLint и TypeScript","ar":"مثالي لعمليات تطوير React التي تتطلب التحقق التلقائي من جودة الشفرة باستخدام ESLint وTypeScript"},"recommendation":{"en":"Empowers agents to enforce code standards and best practices by executing npm scripts for linting, type checking, and formatting, ensuring high-quality React applications with consistent coding styles and correct TypeScript types","zh":"通过执行npm脚本进行linting、类型检查和格式化，赋予代理执行代码标准和最佳实践的能力，确保高质量的React应用程序具有统一的编码风格和正确的TypeScript类型","ja":"npmスクリプトの実行によるlinting、型チェック、フォーマットなどを通じて、コード規範とベストプラクティスを実施するエージェントの能力を提供し、高品質のReactアプリケーションを一貫したコードスタイルと正しいTypeScriptの型を持つことを保証する","ko":"linting, 유형 확인 및 형식 지정 등을 위한 npm 스크립트 실행을 통해 코드 표준 및 모범 사례를 시행할 수 있는 에이전트의 능력을 제공하여, 일관된 코드 스타일 및 올바른 TypeScript 유형을 갖춘 고품질의 React 애플리케이션을 보장합니다","es":"Habilita a los agentes a aplicar normas de código y mejores prácticas ejecutando scripts de npm para la verificación de errores, la comprobación de tipos y el formato, garantizando aplicaciones React de alta calidad con estilos de codificación coherentes y tipos de TypeScript correctos","fr":"Permet aux agents d''appliquer des normes de code et des meilleures pratiques en exécutant des scripts npm pour la vérification des erreurs, la vérification des types et la mise en forme, garantissant des applications React de haute qualité avec des styles de codage cohérents et des types TypeScript corrects","de":"Ermächtigt Agenten, Code-Standards und Best Practices durchzusetzen, indem npm-Skripte für die Überprüfung von Fehlern, die Typüberprüfung und das Formatieren ausgeführt werden, um hochwertige React-Anwendungen mit konsistenten Codierungsstilen und korrekten TypeScript-Typen sicherzustellen","pt":"Habilita os agentes a impor padrões de código e as melhores práticas, executando scripts npm para linting, verificação de tipo e formatação, garantindo aplicações React de alta qualidade com estilos de codificação consistentes e tipos TypeScript corretos","ru":"Наделяет агентов возможностью обеспечивать соблюдение стандартов кода и лучших практик, выполняя скрипты npm для проверки, проверки типов и форматирования, обеспечивая высококачественные приложения React с последовательными стилями кодирования и правильными типами TypeScript","ar":"يمنح الوكلاء القدرة على فرض معايير الشفرة وأفضل الممارسات من خلال تشغيل سكريبتات npm للتحقق والتحقق من النوع والتنسيق، مما يضمن تطبيقات React عالية الجودة بأسلوب 코딩 متسق و أنواع TypeScript صحيحة"},"useCases":{"en":["Automating code quality checks before committing","Validating TypeScript types in React projects","Enforcing consistent code formatting with Prettier"],"zh":["提交前自动执行代码质量检查","验证React项目中的TypeScript类型","使用Prettier强制执行一致的代码格式"],"ja":["コミット前に自動的にコード品質のチェックを実行する","Reactプロジェクト内のTypeScriptの型を検証する","Prettierを使用して一貫したコード形式を強制する"],"ko":["提交 전에 자동으로 코드 품질 확인을 실행하는 것","React 프로젝트 내의 TypeScript 유형을 확인하는 것","Prettier를 사용하여 일관된 코드 형식을 적용하는 것"],"es":["Automatizar las verificaciones de calidad del código antes de confirmar","Validar los tipos de TypeScript en proyectos de React","Aplicar un formato de código coherente con Prettier"],"fr":["Automatiser les vérifications de la qualité du code avant de valider","Valider les types TypeScript dans les projets React"," Appliquer un formatage de code cohérent avec Prettier"],"de":["Automatisieren von Code-Qualitätsprüfungen vor dem Committen","Validieren von TypeScript-Typen in React-Projekten","Durchsetzen eines konsistenten Code-Formats mit Prettier"],"pt":["Automatizar verificações de qualidade de código antes de confirmar","Validar tipos TypeScript em projetos React","Impor formatação de código consistente com Prettier"],"ru":["Автоматизировать проверку качества кода перед фиксацией","Проверять типы TypeScript в проектах React","Обеспечивать последовательное форматирование кода с помощью Prettier"],"ar":["التحقق التلقائي من جودة الشفرة قبل الإلتزام","التحقق من أنواع TypeScript في مشاريع React","فرض تنسيق الشفرة الثابت مع Prettier"]},"limitations":{"en":["Requires npm and React project setup","Limited to React applications with configured ESLint and TypeScript"],"zh":["需要npm和React项目设置","仅限于配置了ESLint和TypeScript的React应用程序"],"ja":["npmとReactプロジェクトの設定が必要","ESLintとTypeScriptが設定されたReactアプリケーションに限定される"],"ko":["npm 및 React 프로젝트 설정이 필요합니다","ESLint 및 TypeScript가 구성된 React 애플리케이션으로 제한됩니다"],"es":["Requiere configuración de npm y proyecto de React","Limitado a aplicaciones de React con ESLint y TypeScript configurados"],"fr":["Nécessite une configuration de npm et de projet React","Limité aux applications React avec ESLint et TypeScript configurés"],"de":["Benötigt npm- und React-Projektsetup","Begrenzt auf React-Anwendungen mit konfiguriertem ESLint und TypeScript"],"pt":["Exige configuração do projeto npm e React","Limitado a aplicações React com ESLint e TypeScript configurados"],"ru":["Требует настройки проекта npm и React","Ограничен для приложений React с настроенным ESLint и TypeScript"],"ar":["يتطلب إعداد مشروع npm و React","محدود لتطبيقات React مع ESLint وTypeScript معدة مسبقا"]},"version":4},"contentHash":"5b96db7ce1d21d07794bb2eb33664e14700125d431253748ace969bc2f43c6cb","qualityScore":53}');
