INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('leboncoin/spark-web/run-quality-checks', 'run-quality-checks', 'leboncoin', 'spark-web', 'community', 'run-quality-checks leboncoin spark-web community a11y design-system react react-components react-hooks tailwindcss typescript ui-library The run-quality-checks skill executes all code quality checks for React applications, benefiting developers who want to verify code quality before committing or preparing a PR. 运行质量检查工具是一种用于检查React代码质量的工具，包括linting、type checking和formatting コード品質チェックツールは、Reactコードの品質をチェックするためのツールです 코드 품질检查 도구는 React 코드 품질을 확인하는 도구입니다 Ejecuta comprobaciones de calidad de código para tu proyecto React con herramientas como ESLint, Type Checking y Prettier Exécutez des vérifications de qualité de code pour votre projet React avec des outils tels que ESLint, Type Checking et Prettier Führen Sie Code-Quality-Checks für Ihr React-Projekt mit Tools wie ESLint, Type Checking und Prettier durch O run-quality-checks é uma ferramenta que executa verificações de qualidade de código para o projeto Spark UI, incluindo linting, type checking e formatação ИИ Агент run-quality-checks выполняет проверки качества кода для проекта Spark UI, включая linting, type checking и форматирование أداة الذكاء الاصطناعي run-quality-checks تقوم بتشغيل عمليات فحص الجودة للكود في مشروع Spark UI، بما في ذلك فحص الأخطاء و فحص الأنواع و التنسيق how to use run-quality-checks run-quality-checks setup guide run-quality-checks alternative run-quality-checks vs eslint install run-quality-checks run-quality-checks for React developers code quality checks for React run-quality-checks tutorial run-quality-checks best practices React代码质量检查 运行质量检查工具 linting type checking formatting ESLint TypeScript Prettier Executes linting with ESLint via npm run lint Performs type checking with TypeScript via npm run typecheck Enforces code formatting with Prettier via npm run prettier Supports React applications with modular and accessible UI components Utilizes Tailwind CSS for styling and design system consistency Leverages React Hooks for efficient and scalable component development run-quality-checks is a skill that executes code quality checks, including linting, type checking, and formatting, to ensure high-quality code in React applications.');
