INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Strategy11/formidable-forms/fix-bug', 'fix-bug', 'Strategy11', 'formidable-forms', 'community', 'fix-bug Strategy11 formidable-forms community The fix-bug skill provides a structured bug-fixing workflow for the Formidable Forms plugin ecosystem, following WordPress and WordPress VIP coding standards, benefiting developers and QA teams. Fix Bug 是一个用于调试 Formidable Forms 代码的 AI 工具，遵循 WordPress 和 WordPress VIP 编码标准。它提供了结构化的 bug 修复工作流程 Fix Bug は、Formidable Forms コードをデバッグするための AI エージェントです。WordPress と WordPress VIP のコーディング規約に従った構造化されたバグ修正ワークフローを提供 Fix Bug는 Formidable Forms 플러그인 코드를 디버깅하기 위한 AI 도구입니다. 워드프레스 및 워드프레스 VIP 코딩 표준을 준수하는 구조화된 버그 수정 워크플로우를 제공 El skill fix-bug ofrece un flujo de trabajo estructurado para solucionar errores en Formidable Forms, siguiendo los estándares de codificación de WordPress y WordPress VIP. Le skill fix-bug propose un workflow structuré pour résoudre les erreurs dans Formidable Forms, en suivant les normes de codage de WordPress et WordPress VIP. Der Skill fix-bug bietet einen strukturierten Workflow zur Fehlerbehebung in Formidable Forms, der den Codierungsstandards von WordPress und WordPress VIP entspricht. O Fix-Bug é um fluxo de trabalho estruturado para resolver bugs no Formidable Forms LITE, seguindo os padrões de codificação do WordPress e Formidable Forms. ИИ Агент Fix-Bug представляет собой структурированный рабочий процесс для исправления ошибок в Formidable Forms LITE, следуя стандартам кодирования WordPress и Formidable Forms. يعد Fix-Bug عملية عمل مهيكلة ل修复 العيوب في Formidable Forms LITE، متبعًا معايير الترميز الخاصة بـ WordPress و Formidable Forms. how to use fix-bug fix-bug alternative fix-bug setup guide what is fix-bug fix-bug vs WordPress VIP fix-bug install Formidable Forms bug fixing WordPress bug-fixing workflow fix-bug for developers Fix Bug Formidable Forms WordPress WordPress VIP AI 工具 代码调试 结构化 bug 修复 自动化代码审查 Follows WordPress, Formidable Forms, and WordPress VIP coding standards Extends always-on rules in .windsurf/rules/enterprise/ with bug-fix-specific steps Automates core principles, code change phases, writing style, and commit message format Supports debugging unexpected behavior and fixing reported bugs Integrates with Formidable Forms LITE Plugin for seamless bug-fixing fix-bug is a structured bug-fixing workflow for the Formidable Forms plugin ecosystem, extending always-on rules with bug-fix-specific steps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vitalyiegorov/suuudokuuu/native-data-fetching', 'community', 'vitalyiegorov', 'suuudokuuu', 'vitalyiegorov/suuudokuuu', 'native-data-fetching', 7, 2, 53, '2026-02-16T07:17:47Z', '2026-03-06T13:04:14.292Z', 'b4e72ed9215cac46f40a461e816acd634797512d97e39477925087eccc6220be', '{"id":"vitalyiegorov/suuudokuuu/native-data-fetching","name":"native-data-fetching","description":{"en":"The native-data-fetching skill enables developers to handle networking tasks, including API requests and data fetching, for Expo and React Native applications.","zh":"Native Data Fetching 是 Expo 网络请求和数据缓存的必备技能，支持 React Query 和 SWR","ja":"ネイティブデータフェッチングは Expo ネットワークリクエストとデータキャッシュの必須スキルで、React Query と SWR をサポート","ko":"네이티브 데이터 Fetching은 Expo 네트워크 요청과 데이터 캐싱의 필수적인 기술로 React Query와 SWR을 지원","es":"Native-data-fetching es una habilidad para Expo y React Native que permite solicitudes de API, caché y depuración de redes. Utilice esta habilidad para cualquier trabajo de red.","fr":"Native-data-fetching est une compétence pour Expo et React Native qui permet les requêtes API, le cache et le débogage réseau. Utilisez cette compétence pour tout travail réseau.","de":"Native-data-fetching ist eine Fähigkeit für Expo und React Native, die API-Anfragen, Caching und Netzwerk-Debugging ermöglicht. Verwenden Sie diese Fähigkeit für alle Netzwerkaufgaben.","pt":"O native-data-fetching é uma habilidade essencial para trabalhar com networking em Expo e React Native, incluindo solicitações de API e gerenciamento de cache.","ru":"Native-data-fetching - это необходимый навык для работы с сетью в Expo и React Native, включая запросы API и управление кешем.","ar":"أداة native-data-fetching هي مهارة أساسية للعمل مع الشبكات في Expo و React Native، بما في ذلك طلبات API وإدارة الذاكرة المؤقتة."},"seo":{"title":{"en":"native-data-fetching: Expo Networking Setup Guide | AI Ag...","zh":"Native Data Fetching Setup Guide - AIエージェント","ja":"ネイティブデータフェッチングベストプラクティス - AIエージェント","ko":"네이티브 데이터 Fetching 설정 가이드 - AI 에이전트","es":"Guía de configuración de native-data-fetching para Expo y...","fr":"Guide de mise en place de native-data-fetching pour Expo ...","de":"Einrichtungsleitfaden für native-data-fetching mit Expo u...","pt":"Guia de Configuração para native-data-fetching com Expo e...","ru":"Настройка native-data-fetching: Лучшие Практики для Expo ...","ar":"دليل الإعداد لأداة native-data-fetching مع Expo و React N..."},"description":{"en":"Unlock seamless data fetching with native-data-fetching! Learn how to implement API requests, caching, and network debugging for your Expo projects.","zh":"了解 Native Data Fetching 的技术细节，实现 Expo 网络请求、数据缓存和调试","ja":"ネイティブデータフェッチングの技術的詳細を学び、Expo ネットワークリクエスト、データキャッシュ、デバッグを実現","ko":"네이티브 데이터 Fetching의 기술적 세부 사항을 배우고 Expo 네트워크 요청, 데이터 캐싱 및 디버깅을 구현","es":"Aprende a utilizar native-data-fetching para solicitudes de API, caché y depuración de redes en Expo y React Native","fr":"Découvrez comment utiliser native-data-fetching pour les requêtes API, le cache et le débogage réseau dans Expo et React Native","de":"Erfahren Sie, wie Sie native-data-fetching für API-Anfragen, Caching und Netzwerk-Debugging in Expo und React Native verwenden","pt":"Aprenda a configurar o native-data-fetching para suas necessidades de networking, incluindo solicitações de API e gerenciamento de cache","ru":"Узнайте, как настроить native-data-fetching для своих нужд сети, включая запросы API и управление кешем","ar":"تعلم كيفية ضبط أداة native-data-fetching لاحتياجات الشبكة الخاصة بك، بما في ذلك طلبات API وإدارة الذاكرة المؤقتة"},"definition":{"en":"native-data-fetching is a skill for managing networking tasks, such as API requests, data fetching, and caching, in Expo and React Native environments.","zh":"Native Data Fetching 是一种用于 Expo 的网络请求和数据缓存技术","ja":"ネイティブデータフェッチングは Expo 用のネットワークリクエストとデータキャッシュ技術","ko":"네이티브 데이터 Fetching은 Expo용 네트워크 요청과 데이터 캐싱 기술","es":"Native-data-fetching es una habilidad que permite la realización de solicitudes de API y la gestión de datos en aplicaciones Expo y React Native","fr":"Native-data-fetching est une compétence qui permet la réalisation de requêtes API et la gestion de données dans les applications Expo et React Native","de":"Native-data-fetching ist eine Fähigkeit, die die Durchführung von API-Anfragen und die Datenverwaltung in Expo- und React-Native-Anwendungen ermöglicht","pt":"O native-data-fetching é uma habilidade que permite configurar e gerenciar solicitações de API e cache em aplicativos Expo e React Native","ru":"Native-data-fetching - это навык, который позволяет настроить и управлять запросами API и кешем в приложениях Expo и React Native","ar":"أداة native-data-fetching هي مهارة تسمح بضبط و إدارة طلبات API والذاكرة المؤقتة في تطبيقات Expo و React Native"},"features":{"en":["Implements API requests using expo/fetch","Sets up data fetching with React Query and SWR","Handles network debugging and offline scenarios","Manages authentication and token management","Configures API URLs and environment variables"],"zh":["支持 React Query 和 SWR","实现 Expo 网络请求和数据缓存","支持离线场景和鉴权/令牌管理","配置 API URL 和环境变量","调试网络故障","使用 expo/fetch 代替 axios"],"ja":["React Query と SWR をサポート","Expo ネットワークリクエストとデータキャッシュを実現","オフラインシナリオと認証/トークン管理をサポート","API URL と環境変数を設定","ネットワーク障害をデバッグ","axios の代わりに expo/fetch を使用"],"ko":["React Query와 SWR 지원","Expo 네트워크 요청과 데이터 캐싱 구현","오프라인 시나리오와 인증/토큰 관리 지원","API URL과 환경 변수 설정","네트워크 오류 디버깅","axios 대신 expo/fetch 사용"],"es":["Solicitudes de API con expo/fetch","Implementación de caché con React Query o SWR","Depuración de redes y manejo de errores","Gestión de tokens de autenticación y variables de entorno","Compatibilidad con escenarios sin conexión"],"fr":["Requêtes API avec expo/fetch","Mise en œuvre du cache avec React Query ou SWR","Débogage réseau et gestion des erreurs","Gestion des jetons d''authentification et des variables d''environnement","Compatibilité avec les scénarios hors ligne"],"de":["API-Anfragen mit expo/fetch","Implementierung von Caching mit React Query oder SWR","Netzwerk-Debugging und Fehlerbehandlung","Verwaltung von Authentifizierungstoken und Umgebungsvariablen","Unterstützung für Offline-Szenarien"],"pt":["Implementação de solicitações de API com expo/fetch","Configuração de gerenciamento de cache com React Query e SWR","Depuração de falhas de rede","Implementação de estratégias de cache","Gerenciamento de cenários offline","Autenticação e gerenciamento de tokens"],"ru":["Реализация запросов API с помощью expo/fetch","Настройка управления кешем с помощью React Query и SWR","Отладка сетевых сбоев","Реализация стратегий кеша","Управление офлайн-сценариями","Аутентификация и управление токенами"],"ar":["تنفيذ طلبات API باستخدام expo/fetch","ضبط إدارة الذاكرة المؤقتة مع React Query و SWR","تصحيح أخطاء الشبكة","تنفيذ استراتيجيات الذاكرة المؤقتة","إدارة سيناريوهات غير متصل","التحقق و إدارة الرموز"]},"keywords":{"en":["how to use native-data-fetching","native-data-fetching expo","react native data fetching","native-data-fetching vs axios","native-data-fetching install guide","expo networking setup"],"zh":["Native Data Fetching","Expo 网络请求","数据缓存","React Query","SWR","离线场景","鉴权/令牌管理","AIエージェント"],"ja":["ネイティブデータフェッチング","Expo ネットワークリクエスト","データキャッシュ","React Query","SWR","オフラインシナリオ","認証/トークン管理","AIエージェント"],"ko":["네이티브 데이터 Fetching","Expo 네트워크 요청","데이터 캐싱","React Query","SWR","오프라인 시나리오","인증/토큰 관리","AI 에이전트"],"es":["native-data-fetching","Expo","React Native","solicitudes de API","caché","depuración de redes","autenticación","variables de entorno","Herramientas de AI para desarrollo"],"fr":["native-data-fetching","Expo","React Native","requêtes API","cache","débogage réseau","authentification","variables d''environnement","Outils d''IA pour le développement"],"de":["native-data-fetching","Expo","React Native","API-Anfragen","Caching","Netzwerk-Debugging","Authentifizierung","Umgebungsvariablen","KI-Tools für die Entwicklung"],"pt":["native-data-fetching","expo","react native","solicitações de API","gerenciamento de cache","react query","swr","depuração de rede","estratégias de cache","cenários offline","autenticação"],"ru":["native-data-fetching","expo","react native","запросы API","управление кешем","react query","swr","отладка сети","стратегии кеша","офлайн-сценарии","аутентификация"],"ar":["native-data-fetching","expo","react native","طلبات API","إدارة الذاكرة المؤقتة","react query","swr","تصحيح أخطاء الشبكة","استراتيجيات الذاكرة المؤقتة","سيناريوهات غير متصل","التحقق"]}},"owner":"vitalyiegorov","repo":"suuudokuuu","repoPath":"vitalyiegorov/suuudokuuu","stars":7,"forks":2,"updatedAt":"2026-02-16T07:17:47Z","topics":["expo","react-native","sudoku","sudoku-game","sudoku-generator","sudoku-solver"],"category":"community","skillMd":{"name":"native-data-fetching","description":"Use when implementing or debugging ANY network request, API call, or data fetching. Covers fetch API, axios, React Query, SWR, error handling, caching strategies, offline support.","version":"1.0.0","bodyPreview":"# Expo Networking\n\n**You MUST use this skill for ANY networking work including API requests, data fetching, caching, or network debugging.**\n\n## When to Use\n\nUse this router when:\n\n- Implementing API requests\n- Setting up data fetching (React Query, SWR)\n- Debugging network failures\n- Implementing caching strategies\n- Handling offline scenarios\n- Authentication/token management\n- Configuring API URLs and environment variables\n\n## Preferences\n\n- Avoid axios, prefer expo/fetch\n\n## Common Issues &","body":"# Expo Networking\n\n**You MUST use this skill for ANY networking work including API requests, data fetching, caching, or network debugging.**\n\n## When to Use\n\nUse this router when:\n\n- Implementing API requests\n- Setting up data fetching (React Query, SWR)\n- Debugging network failures\n- Implementing caching strategies\n- Handling offline scenarios\n- Authentication/token management\n- Configuring API URLs and environment variables\n\n## Preferences\n\n- Avoid axios, prefer expo/fetch\n\n## Common Issues & Solutions\n\n### 1. Basic Fetch Usage\n\n**Simple GET request**:\n\n```tsx\nconst fetchUser = async (userId: string) => {\n  const response = await fetch(`https://api.example.com/users/${userId}`);\n\n  if (!response.ok) {\n    throw new Error(`HTTP error! status: ${response.status}`);\n  }\n\n  return response.json();\n};\n```\n\n**POST request with body**:\n\n```tsx\nconst createUser = async (userData: UserData) => {\n  const response = await fetch(\"https://api.example.com/users\", {\n    method: \"POST\",\n    headers: {\n      \"Content-Type\": \"application/json\",\n      Authorization: `Bearer ${token}`,\n    },\n    body: JSON.stringify(userData),\n  });\n\n  if (!response.ok) {\n    const error = await response.json();\n    throw new Error(error.message);\n  }\n\n  return response.json();\n};\n```\n\n---\n\n### 2. React Query (TanStack Query)\n\n**Setup**:\n\n```tsx\n// app/_layout.tsx\nimport { QueryClient, QueryClientProvider } from \"@tanstack/react-query\";\n\nconst queryClient = new QueryClient({\n  defaultOptions: {\n    queries: {\n      staleTime: 1000 * 60 * 5, // 5 minutes\n      retry: 2,\n    },\n  },\n});\n\nexport default function RootLayout() {\n  return (\n    <QueryClientProvider client={queryClient}>\n      <Stack />\n    </QueryClientProvider>\n  );\n}\n```\n\n**Fetching data**:\n\n```tsx\nimport { useQuery } from \"@tanstack/react-query\";\n\nfunction UserProfile({ userId }: { userId: string }) {\n  const { data, isLoading, error, refetch } = useQuery({\n    queryKey: [\"user\", userId],\n    queryFn: () => fetchUser(userId),\n  });\n\n  if (isLoading) return <Loading />;\n  if (error) return <Error message={error.message} />;\n\n  return <Profile user={data} />;\n}\n```\n\n**Mutations**:\n\n```tsx\nimport { useMutation, useQueryClient } from \"@tanstack/react-query\";\n\nfunction CreateUserForm() {\n  const queryClient = useQueryClient();\n\n  const mutation = useMutation({\n    mutationFn: createUser,\n    onSuccess: () => {\n      // Invalidate and refetch\n      queryClient.invalidateQueries({ queryKey: [\"users\"] });\n    },\n  });\n\n  const handleSubmit = (data: UserData) => {\n    mutation.mutate(data);\n  };\n\n  return <Form onSubmit={handleSubmit} isLoading={mutation.isPending} />;\n}\n```\n\n---\n\n### 3. Error Handling\n\n**Comprehensive error handling**:\n\n```tsx\nclass ApiError extends Error {\n  constructor(message: string, public status: number, public code?: string) {\n    super(message);\n    this.name = \"ApiError\";\n  }\n}\n\nconst fetchWithErrorHandling = async (url: string, options?: RequestInit) => {\n  try {\n    const response = await fetch(url, options);\n\n    if (!response.ok) {\n      const error = await response.json().catch(() => ({}));\n      throw new ApiError(\n        error.message || \"Request failed\",\n        response.status,\n        error.code\n      );\n    }\n\n    return response.json();\n  } catch (error) {\n    if (error instanceof ApiError) {\n      throw error;\n    }\n    // Network error (no internet, timeout, etc.)\n    throw new ApiError(\"Network error\", 0, \"NETWORK_ERROR\");\n  }\n};\n```\n\n**Retry logic**:\n\n```tsx\nconst fetchWithRetry = async (\n  url: string,\n  options?: RequestInit,\n  retries = 3\n) => {\n  for (let i = 0; i < retries; i++) {\n    try {\n      return await fetchWithErrorHandling(url, options);\n    } catch (error) {\n      if (i === retries - 1) throw error;\n      // Exponential backoff\n      await new Promise((r) => setTimeout(r, Math.pow(2, i) * 1000));\n    }\n  }\n};\n```\n\n---\n\n### 4. Authentication\n\n**Token management**:\n\n```tsx\nimport * as SecureStore from \"expo-secure-store\";\n\nconst TOKEN_KEY = \"auth_token\";\n\nexport const auth = {\n  getToken: () => SecureStore.getItemAsync(TOKEN_KEY),\n  setToken: (token: string) => SecureStore.setItemAsync(TOKEN_KEY, token),\n  removeToken: () => SecureStore.deleteItemAsync(TOKEN_KEY),\n};\n\n// Authenticated fetch wrapper\nconst authFetch = async (url: string, options: RequestInit = {}) => {\n  const token = await auth.getToken();\n\n  return fetch(url, {\n    ...options,\n    headers: {\n      ...options.headers,\n      Authorization: token ? `Bearer ${token}` : \"\",\n    },\n  });\n};\n```\n\n**Token refresh**:\n\n```tsx\nlet isRefreshing = false;\nlet refreshPromise: Promise<string> | null = null;\n\nconst getValidToken = async (): Promise<string> => {\n  const token = await auth.getToken();\n\n  if (!token || isTokenExpired(token)) {\n    if (!isRefreshing) {\n      isRefreshing = true;\n      refreshPromise = refreshToken().finally(() => {\n        isRefreshing = false;\n        refreshPromise = null;\n      });\n    }\n    return refreshPromise!;\n  }\n\n  return token;\n};\n```\n\n---\n\n### 5. Offline Support\n\n**Check network status**:\n\n```tsx\nimport NetInfo from \"@react-native-community/netinfo\";\n\n// Hook for network status\nfunction useNetworkStatus() {\n  const [isOnline, setIsOnline] = useState(true);\n\n  useEffect(() => {\n    return NetInfo.addEventListener((state) => {\n      setIsOnline(state.isConnected ?? true);\n    });\n  }, []);\n\n  return isOnline;\n}\n```\n\n**Offline-first with React Query**:\n\n```tsx\nimport { onlineManager } from \"@tanstack/react-query\";\nimport NetInfo from \"@react-native-community/netinfo\";\n\n// Sync React Query with network status\nonlineManager.setEventListener((setOnline) => {\n  return NetInfo.addEventListener((state) => {\n    setOnline(state.isConnected ?? true);\n  });\n});\n\n// Queries will pause when offline and resume when online\n```\n\n---\n\n### 6. Environment Variables\n\n**Using environment variables for API configuration**:\n\nExpo supports environment variables with the `EXPO_PUBLIC_` prefix. These are inlined at build time and available in your JavaScript code.\n\n```tsx\n// .env\nEXPO_PUBLIC_API_URL=https://api.example.com\nEXPO_PUBLIC_API_VERSION=v1\n\n// Usage in code\nconst API_URL = process.env.EXPO_PUBLIC_API_URL;\n\nconst fetchUsers = async () => {\n  const response = await fetch(`${API_URL}/users`);\n  return response.json();\n};\n```\n\n**Environment-specific configuration**:\n\n```tsx\n// .env.development\nEXPO_PUBLIC_API_URL=http://localhost:3000\n\n// .env.production\nEXPO_PUBLIC_API_URL=https://api.production.com\n```\n\n**Creating an API client with environment config**:\n\n```tsx\n// api/client.ts\nconst BASE_URL = process.env.EXPO_PUBLIC_API_URL;\n\nif (!BASE_URL) {\n  throw new Error(\"EXPO_PUBLIC_API_URL is not defined\");\n}\n\nexport const apiClient = {\n  get: async <T,>(path: string): Promise<T> => {\n    const response = await fetch(`${BASE_URL}${path}`);\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    return response.json();\n  },\n\n  post: async <T,>(path: string, body: unknown): Promise<T> => {\n    const response = await fetch(`${BASE_URL}${path}`, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(body),\n    });\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    return response.json();\n  },\n};\n```\n\n**Important notes**:\n\n- Only variables prefixed with `EXPO_PUBLIC_` are exposed to the client bundle\n- Never put secrets (API keys with write access, database passwords) in `EXPO_PUBLIC_` variables—they''re visible in the built app\n- Environment variables are inlined at **build time**, not runtime\n- Restart the dev server after changing `.env` files\n- For server-side secrets in API routes, use variables without the `EXPO_PUBLIC_` prefix\n\n**TypeScript support**:\n\n```tsx\n// types/env.d.ts\ndeclare global {\n  namespace NodeJS {\n    interface ProcessEnv {\n      EXPO_PUBLIC_API_URL: string;\n      EXPO_PUBLIC_API_VERSION?: string;\n    }\n  }\n}\n\nexport {};\n```\n\n---\n\n### 7. Request Cancellation\n\n**Cancel on unmount**:\n\n```tsx\nuseEffect(() => {\n  const controller = new AbortController();\n\n  fetch(url, { signal: controller.signal })\n    .then((response) => response.json())\n    .then(setData)\n    .catch((error) => {\n      if (error.name !== \"AbortError\") {\n        setError(error);\n      }\n    });\n\n  return () => controller.abort();\n}, [url]);\n```\n\n**With React Query** (automatic):\n\n```tsx\n// React Query automatically cancels requests when queries are invalidated\n// or components unmount\n```\n\n---\n\n## Decision Tree\n\n```\nUser asks about networking\n  |-- Basic fetch?\n  |   \\-- Use fetch API with error handling\n  |\n  |-- Need caching/state management?\n  |   |-- Complex app -> React Query (TanStack Query)\n  |   \\-- Simpler needs -> SWR or custom hooks\n  |\n  |-- Authentication?\n  |   |-- Token storage -> expo-secure-store\n  |   \\-- Token refresh -> Implement refresh flow\n  |\n  |-- Error handling?\n  |   |-- Network errors -> Check connectivity first\n  |   |-- HTTP errors -> Parse response, throw typed errors\n  |   \\-- Retries -> Exponential backoff\n  |\n  |-- Offline support?\n  |   |-- Check status -> NetInfo\n  |   \\-- Queue requests -> React Query persistence\n  |\n  |-- Environment/API config?\n  |   |-- Client-side URLs -> EXPO_PUBLIC_ prefix in .env\n  |   |-- Server secrets -> Non-prefixed env vars (API routes only)\n  |   \\-- Multiple environments -> .env.development, .env.production\n  |\n  \\-- Performance?\n      |-- Caching -> React Query with staleTime\n      |-- Deduplication -> React Query handles this\n      \\-- Cancellation -> AbortController or React Query\n```\n\n## Common Mistakes\n\n**Wrong: No error handling**\n\n```tsx\nconst data = await fetch(url).then((r) => r.json());\n```\n\n**Right: Check response status**\n\n```tsx\nconst response = await fetch(url);\nif (!response.ok) throw new Error(`HTTP ${response.status}`);\nconst data = await response.json();\n```\n\n**Wrong: Storing tokens in AsyncStorage**\n\n```tsx\nawait AsyncStorage.setItem(\"token\", token); // Not secure!\n```\n\n**Right: Use SecureStore for sensitive data**\n\n```tsx\nawait SecureStore.setItemAsync(\"token\", token);\n```\n\n## Example Invocations\n\nUser: \"How do I make API calls in React Native?\"\n-> Use fetch, wrap with error handling\n\nUser: \"Should I use React Query or SWR?\"\n-> React Query for complex apps, SWR for simpler needs\n\nUser: \"My app needs to work offline\"\n-> Use NetInfo for status, React Query persistence for caching\n\nUser: \"How do I handle authentication tokens?\"\n-> Store in expo-secure-store, implement refresh flow\n\nUser: \"API calls are slow\"\n-> Check caching strategy, use React Query staleTime\n\nUser: \"How do I configure different API URLs for dev and prod?\"\n-> Use EXPO*PUBLIC* env vars with .env.development and .env.production files\n\nUser: \"Where should I put my API key?\"\n-> Client-safe keys: EXPO*PUBLIC* in .env. Secret keys: non-prefixed env vars in API routes only\n"},"lastSynced":"2026-03-06T13:04:14.292Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile Agents needing seamless Expo and React Native networking capabilities.","zh":"适用于需要无缝 Expo 和 React Native 网络功能的移动代理。","ja":"Expo と React Native のシームレスなネットワーク機能を必要とするモバイル エージェントに適しています。","ko":"무결점한 Expo와 React Native 네트워킹 기능이 필요한 모바일 에이전트에 적합합니다.","es":"Perfecto para Agentes Móviles que necesitan capacidades de networking de Expo y React Native sin problemas.","fr":"Parfait pour les agents mobiles ayant besoin de capacités de réseau Expo et React Native sans interruption.","de":"Perfekt für Mobile Agents, die eine nahtlose Expo- und React-Native-Netzwerkfunktion benötigen.","pt":"Perfeito para Agentes Móveis que necessitam de capacidades de rede Expo e React Native sem interrupções.","ru":"Идеально подходит для Мобильных Агентов, которым необходимы бесперебойные возможности сети Expo и React Native.","ar":"مثالي للوكلاء المحمولين الذين يحتاجون إلى قدرات الشبكة Expo و React Native دون انقطاع."},"recommendation":{"en":"Empowers agents to handle API requests, data fetching, and caching using expo/fetch, while avoiding axios, and supports debugging network failures, implementing caching strategies, and handling offline scenarios with React Query and SWR.","zh":"赋予代理处理 API 请求、数据获取和缓存的能力，使用 expo/fetch，同时避免使用 axios，并支持使用 React Query 和 SWR 进行网络故障调试、缓存策略实现和离线场景处理。","ja":"エージェントに API リクエスト、データ取得、キャッシュの処理能力を与え、expo/fetch を使用し、axios の使用を避け、React Query と SWR を使用したネットワーク障害のデバッグ、キャッシュ戦略の実装、オフラインシナリオの処理をサポートします。","ko":"에이전트가 API 요청, 데이터 가져오기, 캐싱을 처리할 수 있도록 하고, expo/fetch를 사용하며, axios를 피하며, React Query 및 SWR을 사용한 네트워크 오류 디버깅, 캐싱 전략 구현 및 오프라인 시나리오 처리를 지원합니다.","es":"Habilita a los agentes a manejar solicitudes de API, recuperación de datos y almacenamiento en caché utilizando expo/fetch, evitando axios, y admite la depuración de fallos de red, la implementación de estrategias de almacenamiento en caché y el manejo de escenarios sin conexión con React Query y SWR.","fr":"Permet aux agents de gérer les requêtes API, la récupération de données et le cache en utilisant expo/fetch, en évitant axios, et prend en charge le débogage des défaillances réseau, la mise en œuvre de stratégies de cache et la gestion des scénarios hors ligne avec React Query et SWR.","de":"Ermöglicht es den Agenten, API-Anfragen, Datenabruf und Caching mithilfe von expo/fetch zu verarbeiten, axios zu vermeiden und unterstützt das Debuggen von Netzwerkfehlern, die Implementierung von Caching-Strategien und die Verarbeitung von Offline-Szenarien mit React Query und SWR.","pt":"Habilita os agentes a lidar com solicitações de API, busca de dados e cache usando expo/fetch, evitando axios, e suporta depuração de falhas de rede, implementação de estratégias de cache e tratamento de cenários offline com React Query e SWR.","ru":"Наделяет агентов возможностью обрабатывать запросы API, получать данные и использовать кэш с помощью expo/fetch, избегая axios, и поддерживает отладку сбоев сети, реализацию стратегий кэширования и обработку offline-сценариев с React Query и SWR.","ar":"تمكّن الوكلاء من التعامل مع طلبات API واسترجاع البيانات والแคش باستخدام expo/fetch، وتجنب axios، ودعم تصحيح الأعطال الشبكية وتنفيذ استراتيجيات الكैश ومعالجة السيناريوهات دون اتصال مع React Query وSWR."},"useCases":{"en":["Implementing API requests with expo/fetch","Setting up data fetching with React Query and SWR","Debugging network failures and implementing caching strategies"],"zh":["使用 expo/fetch 实现 API 请求","使用 React Query 和 SWR 设置数据获取","调试网络故障并实现缓存策略"],"ja":["expo/fetch を使用した API リクエストの実装","React Query と SWR を使用したデータ取得の設定","ネットワーク障害のデバッグとキャッシュ戦略の実装"],"ko":["expo/fetch를 사용하여 API 요청 구현","React Query 및 SWR을 사용한 데이터 가져오기 설정","네트워크 오류 디버깅 및 캐싱 전략 구현"],"es":["Implementar solicitudes de API con expo/fetch","Configurar la recuperación de datos con React Query y SWR","Depurar fallos de red e implementar estrategias de almacenamiento en caché"],"fr":["Mettre en œuvre des requêtes API avec expo/fetch","Configurer la récupération de données avec React Query et SWR","Déboguer les défaillances réseau et mettre en œuvre des stratégies de cache"],"de":["Implementierung von API-Anfragen mit expo/fetch","Einrichten des Datenabrufs mit React Query und SWR","Debuggen von Netzwerkfehlern und Implementierung von Caching-Strategien"],"pt":["Implementação de solicitações de API com expo/fetch","Configuração de busca de dados com React Query e SWR","Depuração de falhas de rede e implementação de estratégias de cache"],"ru":["Реализация запросов API с помощью expo/fetch","Настройка получения данных с React Query и SWR","Отладка сбоев сети и реализация стратегий кэширования"],"ar":["تنفيذ طلبات API مع expo/fetch","تهيئة استرجاع البيانات مع React Query وSWR","تصحيح الأعطال الشبكية وتنفيذ استراتيجيات الكاش"]},"limitations":{"en":["Expo and React Native applications only","Avoid using axios, prefer expo/fetch"],"zh":["仅适用于 Expo 和 React Native 应用","避免使用 axios，推荐使用 expo/fetch"],"ja":["Expo と React Native アプリケーションのみ","axios の使用を避け、expo/fetch を推奨"],"ko":["Expo 및 React Native 애플리케이션 전용","axios 사용을 피하고, expo/fetch 사용을 선호"],"es":["Solamente aplicaciones Expo y React Native","Evitar el uso de axios, preferir expo/fetch"],"fr":["Uniquement les applications Expo et React Native","Éviter d''utiliser axios, préférer expo/fetch"],"de":["Nur Expo- und React-Native-Anwendungen","Vermeiden Sie die Verwendung von axios, bevorzugen Sie expo/fetch"],"pt":["Apenas aplicações Expo e React Native","Evite usar axios, prefira expo/fetch"],"ru":["Только приложения Expo и React Native","Избегайте использования axios, предпочитайте expo/fetch"],"ar":["تطبيقات Expo وReact Native فقط","تجنب استخدام axios، افضل expo/fetch"]},"version":4},"contentHash":"b4e72ed9215cac46f40a461e816acd634797512d97e39477925087eccc6220be","qualityScore":53}');
