INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('agents-infrastructure/licell/alicloud-redis', 'alicloud-redis', 'agents-infrastructure', 'licell', 'community', 'alicloud-redis agents-infrastructure licell community The alicloud-redis skill manages Redis and Tair instances via the @alicloud/r-kvstore20150101 TypeScript SDK, targeting production environments. 阿里云Redis部署CLI工具，使用TypeScript + Bun实现一键化流程，适用于生产环境 Alibaba Cloud RedisデプロイCLIツール。TypeScript + Bunで一键化流程を実現。生産環境で使用可能 알리바바 클라우드 Redis 배포 CLI 도구, TypeScript + Bun으로 일键화 과정 구현, 생산 환경에서 사용 가능 El skill alicloud-redis utiliza TypeScript y Bun para proporcionar una experiencia de implementación de una sola clave en la nube de Alibaba Le skill alicloud-redis utilise TypeScript et Bun pour offrir une expérience de déploiement d''une seule clé dans le cloud d''Alibaba Der alicloud-redis-Skill verwendet TypeScript und Bun, um eine Ein-Klick-Implementierung in der Alibaba-Cloud zu ermöglichen O alicloud-redis é uma ferramenta de gerenciamento de instâncias Redis e Tair com o SDK TypeScript @alicloud/r-kvstore20150101. Alicloud-redis - это инструмент управления экземплярами Redis и Tair с помощью SDK TypeScript @alicloud/r-kvstore20150101. alicloud-redis هو أداة لإدارة مثيلات Redis و Tair باستخدام SDK TypeScript @alicloud/r-kvstore20150101. how to use alicloud-redis alicloud-redis setup guide what is alicloud-redis alicloud-redis vs redis-cli alicloud-redis install typescript redis deployment alibaba cloud redis tutorial alicloud-redis alternative redis instance management 阿里云Redis TypeScript Bun CLI工具 一键化部署 生产环境 AI工具 云计算 Utilizes the @alicloud/r-kvstore20150101 TypeScript SDK for Redis and Tair instance management Employs the @alicloud/openapi-core library for streamlined API interactions Leverages the @darabonba/typescript package for enhanced type safety Supports environment variable configuration via ALIBABA_CLOUD_ACCESS_KEY_ID and ALIBABA_CLOUD_ACCESS_KEY_SECRET Includes a reusable client factory in scripts/setup_client.ts Provides a quickstart guide in references/quickstart.md for rapid deployment alicloud-redis is a TypeScript-based CLI for deploying Alibaba Cloud Redis, utilizing the @alicloud/r-kvstore20150101 SDK for seamless instance management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('percy-main/web/clarify', 'community', 'percy-main', 'web', 'percy-main/web', 'clarify', 1, 2, 53, '2026-02-28T16:52:52Z', '2026-03-06T07:15:05.176Z', 'a4efe9aaacecc9aab2a0c60711178846fbde5442cfad82819c9b26a6e574fbf3', '{"id":"percy-main/web/clarify","name":"clarify","description":{"en":"The Clarify skill helps developers resolve open questions on triaged GitHub issues. It enables them to work through requirements and approaches before starting development.","zh":"Clarify 技术是一种交互式解决 GitHub 问题的方法，用于澄清代码疑问和解决问题","ja":"Clarify AI エージェントは、GitHub の問題を解決するために使用される技術です","ko":"클라리파이는 깃허브 이슈를 위한 상호작용 해결 기술입니다","es":"Clarify es una habilidad que resuelve preguntas abiertas en GitHub de manera interactiva. Utilízala para aclarar requisitos o enfoques para tickets específicos","fr":"Clarify est une compétence qui résout les questions ouvertes sur GitHub de manière interactive. Utilisez-la pour clarifier les exigences ou les approches pour des tickets spécifiques","de":"Clarify ist eine Fähigkeit, die offene Fragen auf GitHub interaktiv löst. Verwenden Sie sie, um Anforderungen oder Ansätze für bestimmte Tickets zu klären","pt":"O Clarify é uma habilidade que resolve dúvidas em issues do GitHub de forma interativa. Ele funciona lendo a issue e seus comentários e permite esclarecer requisitos ou abordagens para tickets específicos.","ru":"ИИ Агент Clarify - это способность, которая интерактивно решает открытые вопросы на GitHub. Он работает, читая вопрос и его комментарии, и позволяет уточнить требования или подходы для конкретных тикетов.","ar":"Clarify هو قدرة لحل الأسئلة المفتوحة في قضايا GitHub بشكل تفاعلي. يعمل عن طريق قراءة القضية و σχολιασμούςها و يسمح بتوضيح المتطلبات أو المناهج للطوابع النوعية."},"seo":{"title":{"en":"Clarify: Interactively Resolve GitHub Issues | AI Agent S...","zh":"Clarify 技术指南：交互式解决 GitHub 问