INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('percy-main/web/clarify', 'clarify', 'percy-main', 'web', 'community', 'clarify percy-main web community cricket sport The Clarify skill helps developers resolve open questions on triaged GitHub issues. It enables them to work through requirements and approaches before starting development. Clarify 技术是一种交互式解决 GitHub 问题的方法，用于澄清代码疑问和解决问题 Clarify AI エージェントは、GitHub の問題を解決するために使用される技術です 클라리파이는 깃허브 이슈를 위한 상호작용 해결 기술입니다 Clarify es una habilidad que resuelve preguntas abiertas en GitHub de manera interactiva. Utilízala para aclarar requisitos o enfoques para tickets específicos Clarify est une compétence qui résout les questions ouvertes sur GitHub de manière interactive. Utilisez-la pour clarifier les exigences ou les approches pour des tickets spécifiques Clarify ist eine Fähigkeit, die offene Fragen auf GitHub interaktiv löst. Verwenden Sie sie, um Anforderungen oder Ansätze für bestimmte Tickets zu klären O Clarify é uma habilidade que resolve dúvidas em issues do GitHub de forma interativa. Ele funciona lendo a issue e seus comentários e permite esclarecer requisitos ou abordagens para tickets específicos. ИИ Агент Clarify - это способность, которая интерактивно решает открытые вопросы на GitHub. Он работает, читая вопрос и его комментарии, и позволяет уточнить требования или подходы для конкретных тикетов. Clarify هو قدرة لحل الأسئلة المفتوحة في قضايا GitHub بشكل تفاعلي. يعمل عن طريق قراءة القضية و σχολιασμούςها و يسمح بتوضيح المتطلبات أو المناهج للطوابع النوعية. how to use clarify what is clarify clarify alternative clarify vs github clarify install clarify setup guide github issue resolution interactive issue resolution clarify ai agent Clarify 技术 GitHub 问题解决 交互式解决 gh 命令行工具 JSON 数据输出 代码疑问解决 Fetches GitHub issues with all comments using `gh issue view` command Takes a single argument, the issue number (e.g., `/clarify 42`) Works through open questions on a triaged issue before development Clarifies requirements or approach for a specific ticket Uses JSON format to fetch issue details like number, title, body, and comments Clarify is an AI agent skill that interactively resolves open questions on triaged GitHub issues using commands like `gh issue view`.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TechNickAI/openclaw-config/quo', 'community', 'TechNickAI', 'openclaw-config', 'TechNickAI/openclaw-config', 'quo', 0, 0, 53, '2026-03-08T01:57:15.272Z', '2026-03-08T02:00:23.675Z', 'ab08563a5e61d83e9615415373a6b0016eb8ea907698f22ee4330d92dbb8fe4d', '{"id":"TechNickAI/openclaw-config/quo","name":"quo","description":{"en":"The quo skill enables AI agents to query Quo business phone data, including calls, texts, contacts, and transcripts, benefiting developers and businesses. It provides a shareable OpenClaw configuration for memory system, skills, and agent instructions.","zh":"Quo 是一个可分享的 OpenClaw 配置，包括内存系统、技能和代理指令","ja":"Quo は、メモリシステム、スキル、およびエージェント指令を含む共有可能な OpenClaw 構成です","ko":"quo는 메모리 시스템, 스킬 및 에이전트 지침을 포함하는 공유 가능한 OpenClaw 구성입니다","es":"Quo es una habilidad que permite a los usuarios gestionar sus llamadas y contactos de negocio. Se integra con la API de Quo para proporcionar funcionalidades como la visualización de conversaciones recientes y la búsqueda de transcritos.","fr":"Quo est une compétence qui permet aux utilisateurs de gérer leurs appels et contacts professionnels. Elle s''intègre à l''API Quo pour fournir des fonctionnalités telles que l''affichage des conversations récentes et la recherche de transcriptions.","de":"Quo ist eine Fähigkeit, die es Benutzern ermöglicht, ihre Geschäftsanrufe und -kontakte zu verwalten. Sie integriert sich mit der Quo-API, um Funktionen wie die Anzeige vonRecent Conversations und die Suche nach Transkripten bereitzustellen.","pt":"O Quo é uma habilidade de configuração compartilhada do OpenClaw, permitindo o acesso a chamadas, textos e contatos de negócios","ru":"Quo - это共享ная конфигурация OpenClaw, позволяющая получить доступ к звонкам, текстам и контактам бизнеса для ИИ Агентов","ar":"Quo هو تكوين مفتوح لمشروع OpenClaw، يسمح بالوصول إلى المكالمات و الرسائل و جهات الاتصال التجارية لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"quo: Setup Guide for AI Agents | AI Agent Skill","zh":"Quo Setup Guide: OpenClaw 配置和 API 集成","ja":"Quo のセットアップガイド: OpenClaw 構成と API 統合","ko":"quo 설정 가이드: OpenClaw 구성 및 API 통합","es":"Guía de configuración de Quo: API y gestión de llamadas","fr":"Guide de configuration de Quo : API et gestion d''appels","de":"Quo-Konfigurationsleitfaden: API und Anrufverwaltung","pt":"Guia de Configuração Quo: Integração com OpenClaw","ru":"Настройка Quo: Интеграция с OpenClaw для ИИ Агентов","ar":"دليل تكوين Quo: تكامل مع OpenClaw لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to configure quo for your AI agent, unlock call, text, and contact management, and get started with the OpenClaw configuration today!","zh":"了解 Quo 的技术细节，包括 OpenClaw 配置、API 集成和技能指令","ja":"Quo の技術的詳細を学ぶ: OpenClaw 構成、API 統合、スキル指令","ko":"quo의 기술적 세부 정보를 알아보세요: OpenClaw 구성, API 통합 및 스킬 지침","es":"Aprende a configurar Quo con nuestra guía paso a paso. Descubre cómo integrar la API y gestionar llamadas y contactos.","fr":"Découvrez comment configurer Quo avec notre guide étape par étape. Apprenez à intégrer l''API et à gérer les appels et les contacts.","de":"Erfahren Sie, wie Sie Quo mit unserem Schritt-für-Schritt-Leitfaden konfigurieren. Entdecken Sie, wie Sie die API integrieren und Anrufe und Kontakte verwalten.","pt":"Aprenda a configurar o Quo com OpenClaw e acesse chamadas, textos e contatos de negócios","ru":"Узнайте, как настроить Quo с OpenClaw и получить доступ к звонкам, текстам и контактам бизнеса для ИИ Агентов","ar":"تعرف على كيفية تكوين Quo مع OpenClaw و الوصول إلى المكالمات و الرسائل و جهات الاتصال التجارية لأدوات الذكاء الاصطناعي"},"definition":{"en":"quo is a shareable OpenClaw configuration that allows AI agents to access Quo business phone data, including memory system, skills, and agent instructions.","zh":"Quo 是一个 AI 工具，用于查询 Quo 业务电话的调用、短信、联系人和转录","ja":"Quo は、Quo ビジネス電話の呼び出し、テキスト、連絡先、および転送を照会するための AI エージェントです","ko":"quo는 Quo 비즈니스 전화의 호출, 텍스트, 연락처 및 전사를 조회하는 데 사용되는 AI 에이전트입니다","es":"Quo es una habilidad de AI que permite a los usuarios interactuar con su sistema de telefonía de negocio","fr":"Quo est une compétence d''IA qui permet aux utilisateurs d''interagir avec leur système de téléphonie professionnelle","de":"Quo ist eine KI-Fähigkeit, die es Benutzern ermöglicht, mit ihrem Geschäftstelefon-System zu interagieren","pt":"Quo é uma habilidade de configuração do OpenClaw que permite o acesso a chamadas, textos e contatos de negócios","ru":"Quo - это конфигурация OpenClaw, позволяющая получить доступ к звонкам, текстам и контактам бизнеса","ar":"Quo هو تكوين لمشروع OpenClaw يسمح بالوصول إلى المكالمات و الرسائل و جهات الاتصال التجارية"},"features":{"en":["Configures via gateway under `skills.entries.quo.apiKey`","Injects API key as `QUO_API_KEY` automatically","Supports retrieval of recent conversations and call transcripts","Enables listing of business contacts and sending texts to specific numbers","Allows querying of call summaries and transcripts"],"zh":["OpenClaw 配置","API 集成","技能指令","调用和短信记录","联系人管理","转录查询"],"ja":["OpenClaw 構成","API 統合","スキル指令","呼び出しとテキスト記録","連絡先管理","転送照会"],"ko":["OpenClaw 구성","API 통합","스킬 지침","호출 및 문자 기록","연락처 관리","전사 조회"],"es":["Integración con la API de Quo","Visualización de conversaciones recientes","Búsqueda de transcritos de llamadas","Gestión de contactos de negocio","Envío de mensajes de texto","Configuración de la clave de API a través de la consola de Quo"],"fr":["Intégration à l''API Quo","Affichage des conversations récentes","Recherche de transcriptions d''appels","Gestion des contacts professionnels","Envoi de messages texte","Configuration de la clé d''API via la console Quo"],"de":["Integration mit der Quo-API","Anzeige von Recent Conversations","Suche nach Transkripten von Anrufen","Verwaltung von Geschäftskontakten","Versenden von Textnachrichten","Konfiguration des API-Schlüssels über die Quo-Konsole"],"pt":["Acesso a chamadas e textos de negócios","Gerenciamento de contatos de negócios","Integração com API do Quo","Configuração via gateway do OpenClaw","Suporte a transcrição de chamadas","Listagem de contatos de negócios"],"ru":["Доступ к звонкам и текстам бизнеса","Управление контактами бизнеса","Интеграция с API Quo","Настройка через шлюз OpenClaw","Поддержка транскрипции звонков","Список контактов бизнеса для ИИ Агентов"],"ar":["الوصول إلى المكالمات و الرسائل التجارية","إدارة جهات الاتصال التجارية","التكامل مع واجهة برمجة التطبيقات Quo","التكوين عبر بوابة OpenClaw","الدعم للنسخ الصوتي للمكالمات","قائمة جهات الاتصال التجارية لأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use quo","quo setup guide","quo api key configuration","quo vs OpenPhone","quo install for AI agents","what is quo","quo business phone integration","quo contact management","quo call transcript retrieval"],"zh":["Quo Setup","OpenClaw 配置","API 集成","AI 工具","业务电话","调用记录","短信记录","联系人管理"],"ja":["Quo セットアップ","OpenClaw 構成","API 統合","AI エージェント","ビジネス電話","呼び出し記録","テキスト記録","連絡先管理"],"ko":["quo 설정","OpenClaw 구성","API 통합","AI 에이전트","비즈니스 전화","호출 기록","문자 기록","연락처 관리"],"es":["Quo API","gestión de llamadas","contactos de negocio","transcritos de llamadas","envío de mensajes de texto","configuración de Quo","integración con Quo","herramientas de AI para telefonía","soluciones de telefonía de negocio"],"fr":["API Quo","gestion d''appels","contacts professionnels","transcriptions d''appels","envoi de messages texte","configuration de Quo","intégration avec Quo","outils d''IA pour la téléphonie","solutions de téléphonie professionnelle"],"de":["Quo-API","Anrufverwaltung","Geschäftskontakte","Transkripte von Anrufen","Versenden von Textnachrichten","Konfiguration von Quo","Integration mit Quo","KI-Tools für Telefonie","Lösungen für Geschäftstelefonie"],"pt":["Quo configuração","OpenClaw integração","API Quo","contatos de negócios","chamadas de negócios","textos de negócios","transcrição de chamadas","gerenciamento de contatos"],"ru":["Quo настройка","OpenClaw интеграция","API Quo","контакты бизнеса","звонки бизнеса","тексты бизнеса","транскрипция звонков","управление контактами для ИИ Агентов"],"ar":["تكوين Quo","تكامل OpenClaw","واجهة برمجة التطبيقات Quo","جهات الاتصال التجارية","المكالمات التجارية","الرسائل التجارية","النسخ الصوتي للمكالمات","إدارة جهات الاتصال لأدوات الذكاء الاصطناعي"]}},"owner":"TechNickAI","repo":"openclaw-config","repoPath":"TechNickAI/openclaw-config","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.272Z","topics":[],"category":"community","skillMd":{"name":"quo","description":"","version":"0.6.0","bodyPreview":"# Quo 📞\n\nQuery your Quo (formerly OpenPhone) business phone — calls, texts, contacts,\ntranscripts.\n\n## Setup\n\nAPI key from my.quo.com → Settings → API. Configure via gateway under\n`skills.entries.quo.apiKey`. OpenClaw injects it as `QUO_API_KEY` automatically.\n\n## What Users Ask\n\n- \"What''s my Quo number?\"\n- \"Show recent conversations\"\n- \"Get the transcript from that call\"\n- \"What was the summary of my call with [person]?\"\n- \"List my business contacts\"\n- \"Send a text to [number]\"\n- \"Show my rece","body":"# Quo 📞\n\nQuery your Quo (formerly OpenPhone) business phone — calls, texts, contacts,\ntranscripts.\n\n## Setup\n\nAPI key from my.quo.com → Settings → API. Configure via gateway under\n`skills.entries.quo.apiKey`. OpenClaw injects it as `QUO_API_KEY` automatically.\n\n## What Users Ask\n\n- \"What''s my Quo number?\"\n- \"Show recent conversations\"\n- \"Get the transcript from that call\"\n- \"What was the summary of my call with [person]?\"\n- \"List my business contacts\"\n- \"Send a text to [number]\"\n- \"Show my recent calls with [number]\"\n- \"Any missed calls today?\"\n- \"Who called the office?\"\n- \"Text [person] from my work number\"\n- \"Check my voicemails\"\n- \"What messages came in on the business line?\"\n- \"Who is this number?\"\n- \"Show me everything from this number\"\n- \"Show conversations from unknown numbers\"\n\n## CLI Reference\n\n```\n{baseDir}/quo numbers                    List phone numbers\n{baseDir}/quo conversations [filters]    List conversations\n{baseDir}/quo contacts [--limit N]       List contacts\n{baseDir}/quo search-phone <phone> [--refresh]  Find contact by phone (cached)\n{baseDir}/quo gather <phone> [--since ISO] [--until ISO] [--limit N] [--refresh]\n{baseDir}/quo custom-fields              List contact custom fields\n{baseDir}/quo users                      List workspace users\n{baseDir}/quo summary <callId>           Get AI call summary\n{baseDir}/quo transcript <callId>        Get full dialogue transcript\n{baseDir}/quo recordings <callId>        Get recording URLs\n{baseDir}/quo voicemails <callId>        Get voicemail + transcript\n{baseDir}/quo send --from <num> --to <num> <message>\n{baseDir}/quo messages --number-id <id> --participant <phone> [--limit N]\n{baseDir}/quo calls --number-id <id> --participant <phone> [--limit N] [--created-after ISO] [--created-before ISO]\n{baseDir}/quo raw [METHOD] <endpoint> [json-body]\n```\n\n### Conversation Filters\n\n```\n--phone <number-or-id>    Filter by Quo phone line (repeatable)\n--updated-after ISO       Conversations updated after date\n--updated-before ISO      Conversations updated before date\n--created-after ISO       Conversations created after date\n--created-before ISO      Conversations created before date\n--include-inactive        Include inactive/snoozed conversations\n--unknown                 Only show conversations with unrecognized numbers\n--limit N                 Max results (default 10)\n```\n\n## API Endpoints\n\nFull OpenAPI spec:\nhttps://openphone-public-api-prod.s3.us-west-2.amazonaws.com/public/openphone-public-api-v1-prod.json\n\n| Endpoint                       | Method  | Description                                                    |\n| ------------------------------ | ------- | -------------------------------------------------------------- |\n| `/v1/phone-numbers`            | GET     | List phone numbers                                             |\n| `/v1/conversations`            | GET     | List conversations (filterable)                                |\n| `/v1/messages`                 | GET     | List messages for a conversation                               |\n| `/v1/messages`                 | POST    | Send a text message                                            |\n| `/v1/messages/{id}`            | GET     | Get message by ID                                              |\n| `/v1/calls`                    | GET     | List calls (with date filters)                                 |\n| `/v1/calls/{callId}`           | GET     | Get call by ID                                                 |\n| `/v1/call-summaries/{callId}`  | GET     | AI-generated call summary                                      |\n| `/v1/call-transcripts/{id}`    | GET     | Full dialogue transcript with speaker attribution              |\n| `/v1/call-recordings/{callId}` | GET     | Recording URLs (MP3)                                           |\n| `/v1/call-voicemails/{callId}` | GET     | Voicemail + transcript                                         |\n| `/v1/contacts`                 | GET     | List contacts (paginated)                                      |\n| `/v1/contacts`                 | POST    | Create a contact                                               |\n| `/v1/contacts/{id}`            | GET     | Get contact by ID                                              |\n| `/v1/contacts/{id}`            | PATCH   | Update contact (**replaces entire defaultFields!**)            |\n| `/v1/contacts/{id}`            | DELETE  | Delete a contact                                               |\n| `/v1/contact-custom-fields`    | GET     | List custom contact fields                                     |\n| `/v1/users`                    | GET     | List workspace users                                           |\n| `/v1/webhooks/*`               | Various | Webhook management for messages, calls, summaries, transcripts |\n\n## Key Data Formats\n\n### Transcript Response\n\nReturns `dialogue[]` array with speaker-attributed entries:\n\n```json\n{\n  \"data\": {\n    \"callId\": \"AC...\",\n    \"dialogue\": [\n      {\n        \"content\": \"Hello\",\n        \"start\": 0.16,\n        \"end\": 0.48,\n        \"identifier\": \"+15551234567\",\n        \"userId\": \"US...\"\n      },\n      {\n        \"content\": \"Hi, my name is Jane\",\n        \"start\": 1.0,\n        \"end\": 2.5,\n        \"identifier\": \"+15559876543\",\n        \"userId\": null\n      }\n    ]\n  }\n}\n```\n\n### Contact Fields\n\n- `defaultFields`: firstName, lastName, company, role, emails[], phoneNumbers[]\n- `customFields`: Array of {key, value} pairs (keys from `/contact-custom-fields`)\n- ⚠️ PATCH replaces entire `defaultFields` — always include ALL existing fields\n\n### Custom Fields (Julianna''s workspace)\n\n- `Property Associated` (key: `1712532493777`, type: string)\n- `Address` (key: `1700067557182`, type: address)\n\n## Notes\n\n- Transcripts require call recording enabled in Quo settings\n- Phone numbers in E.164 format (+1XXXXXXXXXX)\n- Contacts API has no phone number search — `search-phone`, `--unknown`, and `gather`\n  use a local cache at `/tmp/quo-contacts-cache.json` (5-min TTL, use `--refresh` to\n  rebuild)\n- Voicemail endpoint returns single object (not array)\n- `gather` defaults to last 30 days, text only (no audio URLs or media)\n"},"lastSynced":"2026-03-08T02:00:23.675Z","agentAnalysis":{"suitability":{"en":"Ideal for Business Automation Agents requiring seamless integration with Quo business phone data, including calls, texts, contacts, and transcripts.","zh":"适用于需要与Quo商务电话数据（包括呼叫、短信、联系人和转录）进行无缝集成的商务自动化Agent。","ja":"Quoビジネスフォン데이터（呼叫、テキスト、連絡先、トランスクリプトなど）とのシームレスな統合を必要とするビジネスオートメーションエージェントに適しています。","ko":"Quo 비즈니스 전화 데이터(발신, 문자, 연락처, 기록 등)와의 무제한 통합을 요구하는 비즈니스 자동화 에이전트에 적합합니다.","es":"Ideal para agentes de automatización de empresas que requieren una integración sin problemas con los datos del teléfono de negocios Quo, incluidas llamadas, textos, contactos y transcripciones.","fr":"Idéal pour les agents d''automatisation commerciale nécessitant une intégration transparente avec les données du téléphone d''entreprise Quo, notamment les appels, les textes, les contacts et les transcriptions.","de":"Ideal für Geschäftautomatisierungsagenten, die eine nahtlose Integration mit Quo-Geschäftstelefon-Daten erfordern, einschließlich Anrufen, Texten, Kontakten und Transkriptionen.","pt":"Ideal para Agentes de Automação de Negócios que requerem integração perfeita com dados de telefone de negócios Quo, incluindo chamadas, textos, contatos e transcrições.","ru":"Идеально для агентов бизнес-автоматизации, требующих бесшовной интеграции с данными бизнес-телефона Quo, включая звонки, тексты, контакты и транскрипты.","ar":"مثالي لعمليات تحسين الأعمال التي تتطلب تكاملًا دون عيوب مع بيانات هاتف أعمال Quo، بما في ذلك المكالمات والنصوص والاتصال والمحاضرات."},"recommendation":{"en":"Empowers agents to query Quo data using the Quo API, providing access to call transcripts, contact lists, and conversation history, all through a shareable OpenClaw configuration, leveraging API keys for secure authentication and injecting them as environment variables like QUO_API_KEY.","zh":"赋予代理查询Quo数据的能力，使用Quo API提供对呼叫转录、联系人列表和对话历史的访问，所有这些都通过可共享的OpenClaw配置实现，利用API密钥进行安全身份验证，并将其作为环境变量（如QUO_API_KEY）注入。","ja":"エージェントにQuoデータの照会機能を提供し、Quo APIを使用して呼叫トランスクリプト、連絡先リスト、会話履歴へのアクセスを提供します。すべてこれらの機能は、共有可能なOpenClaw構成を介して実現され、APIキーを使用したセキュアな認証を行い、QUO_API_KEYなどの環境変数として注入します。","ko":"에이전트가 Quo 데이터를 쿼리할 수 있는 기능을 제공하며, Quo API를 사용하여 호출 기록, 연락처 목록, 대화 기록에 액세스할 수 있습니다. 모든 이러한 기능은 공유 가능한 OpenClaw 구성 통해 제공되며, API 키를 사용한 보안 인증을 수행하고, QUO_API_KEY와 같은 환경 변수로 주입합니다.","es":"Habilita a los agentes a consultar los datos de Quo mediante la API de Quo, proporcionando acceso a transcripciones de llamadas, listas de contactos e historial de conversaciones, todo a través de una configuración de OpenClaw compartible, aprovechando claves de API para la autenticación segura e inyectándolas como variables de entorno como QUO_API_KEY.","fr":"Permet aux agents d''interroger les données Quo à l''aide de l''API Quo, fournissant un accès aux transcriptions d''appels, listes de contacts et historique de conversations, le tout via une configuration OpenClaw partageable, en exploitant les clés d''API pour une authentification sécurisée et en les injectant comme variables d''environnement telles que QUO_API_KEY.","de":"Ermächtigt die Agenten, Quo-Daten mit der Quo-API abzufragen, und bietet Zugriff auf Anruftexte, Kontaktlisten und Konversationsverlauf, all dies über eine teilbare OpenClaw-Konfiguration, die API-Schlüssel für sichere Authentifizierung nutzt und sie als Umgebungsvariablen wie QUO_API_KEY einfügt.","pt":"Habilita os agentes a consultar dados Quo usando a Quo API, fornecendo acesso a transcrições de chamadas, listas de contatos e histórico de conversas, tudo por meio de uma configuração OpenClaw compartilhável, utilizando chaves de API para autenticação segura e injetando-as como variáveis de ambiente como QUO_API_KEY.","ru":"Наделяет агентов возможностью запрашивать данные Quo с помощью Quo API, обеспечивая доступ к транскриптам звонков, спискам контактов и истории разговоров, все через настраиваемую конфигурацию OpenClaw, использующую ключи API для безопасной аутентификации и впрыскивая их как переменные среды, такие как QUO_API_KEY.","ar":"تمكّن الوكلاء من استفسار بيانات Quo باستخدام Quo API، وصولاً إلى نصوص المحادثات وقوائم الاتصال وتسجيلات المحادثات، كل ذلك من خلال إعدادات OpenClaw القابلة للمشاركة، بالاعتماد على مفتاح API من أجل التأكد من الأمان أثناء المصادقة، وإدخالها كمتغيرات بيئة مثل QUO_API_KEY."},"useCases":{"en":["Retrieving recent conversation transcripts","Listing business contacts and their associated call logs","Sending automated texts to contacts using the Quo API","Analyzing call summaries for specific contacts or time frames","Automating customer support workflows by integrating Quo data"],"zh":["检索最近的对话转录","列出商务联系人及其关联的呼叫记录","使用Quo API向联系人发送自动短信","分析特定联系人或时间范围的呼叫摘要","通过集成Quo数据来自动化客户支持工作流"],"ja":["最近の会話トランスクリプトの取得","ビジネス連絡先とその関連する呼叫ログのリスト表示","Quo APIを使用した連絡先への自動テキスト送信","特定の連絡先または時間枠の呼叫サマリーの分析","Quoデータの統合によるカスタマーサポートワークフローの自動化"],"ko":["최근 대화 기록을 검색","비즈니스 연락처 및 해당 호출 로그 목록","Quo API를 사용하여 연락처에 자동 문자 보내기","특정 연락처 또는 시간 프레임에 대한 호출 요약 분석","Quo 데이터 통합을 통한 고객 지원 워크플로 자동화"],"es":["Recuperar transcripciones de conversaciones recientes","Listar contactos comerciales y sus registros de llamadas asociados","Enviar textos automatizados a contactos mediante la API de Quo","Analizar resúmenes de llamadas para contactos o marcos de tiempo específicos","Automatizar flujos de trabajo de soporte al cliente integrando datos de Quo"],"fr":["Récupérer les transcriptions de conversations récentes","Lister les contacts commerciaux et leurs journaux d''appels associés","Envoyer des textes automatisés aux contacts à l''aide de l''API Quo","Analyser les résumés d''appels pour des contacts ou des périodes de temps spécifiques","Automatiser les flux de travail de support client en intégrant les données Quo"],"de":["Abrufen von Transkriptionen kürzlicher Konversationen","Auflisten von Geschäftskontakten und deren zugehörigen Anrufprotokollen","Senden automatisierter Textnachrichten an Kontakte über die Quo-API","Analysieren von Anrufzusammenfassungen für bestimmte Kontakte oder Zeitrahmen","Automatisieren von Kundenunterstützungsworkflows durch die Integration von Quo-Daten"],"pt":["Recuperar transcrições de conversas recentes","Listar contatos de negócios e seus registros de chamadas associados","Enviar textos automatizados para contatos usando a Quo API","Analizar resumos de chamadas para contatos ou intervalos de tempo específicos","Automatizar fluxos de trabalho de suporte ao cliente integrando dados Quo"],"ru":["Получение транскриптов недавних разговоров","Перечисление бизнес-контактов и их связанных журналов звонков","Отправка автоматических текстов контактам с помощью Quo API","Анализ сводок звонков для определенных контактов или временных интервалов","Автоматизация рабочих процессов поддержки клиентов, интегрируя данные Quo"],"ar":["استرجاع نصوص المحادثات الحديثة","قائمة بأسماء أعمال الاتصال وسجلات المكالمات المرتبطة بها","إرسال رسائل نصية آلية إلى أسماء الاتصال باستخدام Quo API","تحليل ملخصات المكالمات لأسماء الاتصال أو الفترات الزمنية المحددة","تأتميم سير عمل دعم العملاء من خلال دمج بيانات Quo"]},"limitations":{"en":["Requires a Quo API key from my.quo.com","Needs configuration via the gateway under skills.entries.quo.apiKey","Dependent on OpenClaw for automatic injection of the QUO_API_KEY environment variable"],"zh":["需要从my.quo.com获取Quo API密钥","需要通过网关在skills.entries.quo.apiKey下进行配置","依赖OpenClaw来自动注入QUO_API_KEY环境变量"],"ja":["my.quo.comからQuo APIキーを取得する必要がある","skills.entries.quo.apiKey下のゲートウェイ経由で構成する必要がある","QUO_API_KEY環境変数の自動注入にOpenClawに依存する"],"ko":["my.quo.com에서 Quo API 키를 가져와야 함","스킬 엔트리 Quo API 키 아래에서 게이트웨이를 통해 구성해야 함","QUO_API_KEY 환경 변수를 자동으로 주입하기 위해 OpenClaw에 의존"],"es":["Requiere una clave de API de Quo desde my.quo.com","Necesita configuración a través de la pasarela en skills.entries.quo.apiKey","Depende de OpenClaw para la inyección automática de la variable de entorno QUO_API_KEY"],"fr":["Nécessite une clé d''API Quo à partir de my.quo.com","Nécessite une configuration via la passerelle sous skills.entries.quo.apiKey","Dépend de OpenClaw pour l''injection automatique de la variable d''environnement QUO_API_KEY"],"de":["Benötigt einen Quo-API-Schlüssel von my.quo.com","Benötigt eine Konfiguration über das Gateway unter skills.entries.quo.apiKey","Hängt von OpenClaw für die automatische Einschleusung der Umgebungsvariable QUO_API_KEY ab"],"pt":["Exige uma chave de API Quo de my.quo.com","Necessita de configuração via gateway em skills.entries.quo.apiKey","Depende do OpenClaw para injeção automática da variável de ambiente QUO_API_KEY"],"ru":["Требует ключа API Quo с my.quo.com","Требует настройки через шлюз в skills.entries.quo.apiKey","Зависит от OpenClaw для автоматического впрыскивания переменной среды QUO_API_KEY"],"ar":["يتطلب مفتاح API Quo من my.quo.com","يحتاج إلى إعداد من خلال البوابة في skills.entries.quo.apiKey","يعتمد على OpenClaw من أجل الحقن التلقائي لمتغير البيئة QUO_API_KEY"]},"version":4},"contentHash":"ab08563a5e61d83e9615415373a6b0016eb8ea907698f22ee4330d92dbb8fe4d","qualityScore":53}');
DELETE FROM skills_fts WHERE id = 'TechNickAI/openclaw-config/quo';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TechNickAI/openclaw-config/quo', 'quo', 'TechNickAI', 'openclaw-config', 'community', 'quo TechNickAI openclaw-config community The quo skill enables AI agents to query Quo business phone data, including calls, texts, contacts, and transcripts, benefiting developers and businesses. It provides a shareable OpenClaw configuration for memory system, skills, and agent instructions. Quo 是一个可分享的 OpenClaw 配置，包括内存系统、技能和代理指令 Quo は、メモリシステム、スキル、およびエージェント指令を含む共有可能な OpenClaw 構成です quo는 메모리 시스템, 스킬 및 에이전트 지침을 포함하는 공유 가능한 OpenClaw 구성입니다 Quo es una habilidad que permite a los usuarios gestionar sus llamadas y contactos de negocio. Se integra con la API de Quo para proporcionar funcionalidades como la visualización de conversaciones recientes y la búsqueda de transcritos. Quo est une compétence qui permet aux utilisateurs de gérer leurs appels et contacts professionnels. Elle s''intègre à l''API Quo pour fournir des fonctionnalités telles que l''affichage des conversations récentes et la recherche de transcriptions. Quo ist eine Fähigkeit, die es Benutzern ermöglicht, ihre Geschäftsanrufe und -kontakte zu verwalten. Sie integriert sich mit der Quo-API, um Funktionen wie die Anzeige vonRecent Conversations und die Suche nach Transkripten bereitzustellen. O Quo é uma habilidade de configuração compartilhada do OpenClaw, permitindo o acesso a chamadas, textos e contatos de negócios Quo - это共享ная конфигурация OpenClaw, позволяющая получить доступ к звонкам, текстам и контактам бизнеса для ИИ Агентов Quo هو تكوين مفتوح لمشروع OpenClaw، يسمح بالوصول إلى المكالمات و الرسائل و جهات الاتصال التجارية لأدوات الذكاء الاصطناعي how to use quo quo setup guide quo api key configuration quo vs OpenPhone quo install for AI agents what is quo quo business phone integration quo contact management quo call transcript retrieval Quo Setup OpenClaw 配置 API 集成 AI 工具 业务电话 调用记录 短信记录 联系人管理 Configures via gateway under `skills.entries.quo.apiKey` Injects API key as `QUO_API_KEY` automatically Supports retrieval of recent conversations and call transcripts Enables listing of business contacts and sending texts to specific numbers Allows querying of call summaries and transcripts quo is a shareable OpenClaw configuration that allows AI agents to access Quo business phone data, including memory system, skills, and agent instructions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('raphaelsalaja/userinterface-wiki/morphing-icons', 'community', 'raphaelsalaja', 'userinterface-wiki', 'raphaelsalaja/userinterface-wiki', 'morphing-icons', 0, 0, 53, '2026-03-08T01:57:15.286Z', '2026-03-08T02:00:59.817Z', '690cb3ebe7860f77b4fedd6f951aba6aff129faa84a98849489de4338c88f97f', '{"id":"raphaelsalaja/userinterface-wiki/morphing-icons","name":"morphing-icons","description":{"en":"Morphing-icons is a technical solution for creating icons that transform through shape transformation, benefiting developers and designers. It utilizes a 3-line SVG structure for seamless morphing.","zh":"Morphing Icons是一种基于SVG的图标变形技术，通过三线结构实现图标之间的无缝变形","ja":"Morphing Iconsは、SVGベースのアイコン変形技術であり、3ライン構造によってアイコン間のシームレスな変形を実現する","ko":"Morphing Icons는 SVG 기반의 아이콘 변형 기술로, 3라인 구조를 통해 아이콘 간의 무제한 변형을 구현합니다","es":"Morphing-icons permite crear iconos que se transforman mediante la modificación real de formas, utilizando una estructura de 3 líneas SVG","fr":"Morphing-icons permet de créer des icônes qui se transforment par une véritable modification de formes, en utilisant une structure de 3 lignes SVG","de":"Morphing-icons ermöglicht die Erstellung von Symbolen, die sich durch reale Formveränderung verändern, unter Verwendung einer 3-Linien-SVG-Struktur","pt":"Morfing-ícones é uma técnica que permite a transformação de ícones mediante a alteração da forma, utilizando três linhas SVG. As ferramentas de IA facilitam a criação desses ícones.","ru":"Морфинг-иконки - это техника, позволяющая преобразовывать иконки посредством изменения формы, используя три линии SVG. ИИ Агенты упрощают создание таких иконок.","ar":"الأيقونات المتغيرة هي تقنية تسمح بتحويل الأيقونات من خلال تغيير الشكل، باستخدام ثلاثة خطوط SVG. أدوات الذكاء الاصطناعي تسهل إنشاء هذه الأيقونات."},"seo":{"title":{"en":"Morphing-Icons: Seamless Icon Transformation Setup Guide ...","zh":"Morphing Icons Setup Guide - 基于SVG的图标变形技术","ja":"Morphing Icons の設定方法 - AIエージェントを使用したアイコン変形","ko":"Morphing Icons 설정 가이드 - SVG 기반 아이콘 변형 기술","es":"Guía de configuración de morphing-icons para interfaces m...","fr":"Mise en place des icônes morphing pour des interfaces amé...","de":"Einrichtungsleitfaden für morphing-icons zur Verbesserung...","pt":"Guia de Configuração de Ícones Morfáveis com Ferramentas ...","ru":"Руководство по настройке морфинг-иконок с помощью ИИ Агентов","ar":"دليل تكوين الأيقونات المتغيرة باستخدام أدوات الذكاء الاصط..."},"description":{"en":"Discover how morphing-icons enables smooth icon transitions with its 3-line SVG structure. Learn to implement this innovative technique for better interfaces...","zh":"了解Morphing Icons的核心概念和架构，实现图标之间的无缝变形。基于SVG的三线结构，任何图标都可以变形为其他图标","ja":"Morphing Iconsのコアコンセプトとアーキテクチャを学び、アイコン間のシームレスな変形を実現。SVGベースの3ライン構造により、任意のアイコンを変形できる","ko":"Morphing Icons의 핵심 개념과 아키텍처를 학습하고, 아이콘 간의 무제한 변형을 구현하세요. SVG 기반의 3라인 구조로 인해 任意의 아이콘을 변형할 수 있습니다","es":"Aprende a crear iconos que se transforman mediante la modificación real de formas, no mediante crossfades, con morphing-icons","fr":"Découvrez comment créer des icônes qui se transforment par une véritable modification de formes, et non par crossfades, avec morphing-icons","de":"Erfahren Sie, wie Sie mit morphing-icons Symbole erstellen, die sich durch reale Formveränderung und nicht durch Crossfades verändern","pt":"Aprenda a criar ícones que se transformam mediante a alteração real da forma, não crossfades, com as ferramentas de IA","ru":"Узнайте, как создавать иконки, которые меняют форму посредством реального преобразования, а не перекрестных затуханий, с помощью ИИ Агентов","ar":"تعلم كيفية إنشاء أيقونات تتحول من خلال التغيير الفعلي للشكل، وليس عبر التلاشي المتقاطع، باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"Morphing-icons is a technique for building icons that transform through actual shape transformation, not crossfades, using a shared 3-line SVG structure.","zh":"Morphing Icons是一种图标变形技术，通过SVG的三线结构实现图标之间的无缝变形","ja":"Morphing Iconsは、アイコン変形技術の一種で、SVGの3ライン構造によってアイコン間のシームレスな変形を実現する","ko":"Morphing Icons는 아이콘 변형 기술의 일종으로, SVG의 3라인 구조로 인해 아이콘 간의 무제한 변형을 구현합니다","es":"Morphing-icons es una técnica para crear iconos que se transforman mediante la modificación real de formas, utilizando una estructura de 3 líneas SVG","fr":"Morphing-icons est une technique pour créer des icônes qui se transforment par une véritable modification de formes, en utilisant une structure de 3 lignes SVG","de":"Morphing-icons ist eine Technik zur Erstellung von Symbolen, die sich durch reale Formveränderung verändern, unter Verwendung einer 3-Linien-SVG-Struktur","pt":"Ícones morfáveis são ícones que se transformam mediante a alteração da forma, utilizando três linhas SVG","ru":"Морфинг-иконки - это иконки, которые меняют форму посредством реального преобразования, используя три линии SVG","ar":"الأيقونات المتغيرة هي أيقونات تتحول من خلال التغيير الفعلي للشكل، باستخدام ثلاثة خطوط SVG"},"features":{"en":["Utilizes a 3-line SVG structure for seamless icon morphing","Enables any icon to morph into any other icon","Collapses extra lines to invisible center points for icons with fewer lines","Defines each line with coordinates and optional opacity","Supports shape transformation without crossfades"],"zh":["基于SVG的三线结构","图标之间的无缝变形","支持任意图标变形","使用TS定义线的坐标和不透明度","实现图标变形的核心概念和架构"],"ja":["SVGベースの3ライン構造","アイコン間のシームレスな変形","任意のアイコンを変形できる","TSを使用して線の座標と不透明度を定義","アイコン変形のコアコンセプトとアーキテクチャ"],"ko":["SVG 기반의 3라인 구조","아이콘 간의 무제한 변형","任意의 아이콘을 변형할 수 있습니다","TS를 사용하여 선의 좌표와 불투명도를 정의","아이콘 변형의 핵심 개념과 아키텍처"],"es":["Transformación de iconos mediante modificación real de formas","Estructura de 3 líneas SVG para una morphing fluida","Cualquier icono puede transformarse en otro","Compatibilidad con coordenadas y opacidad para cada línea","Arquitectura escalable para interfaces complejas"],"fr":["Transformation d''icônes par modification réelle de formes","Structure de 3 lignes SVG pour une morphing fluide","Toute icône peut se transformer en une autre","Compatibilité avec les coordonnées et l''opacité pour chaque ligne","Architecture évolutrice pour des interfaces complexes"],"de":["Transformation von Symbolen durch reale Formveränderung","3-Linien-SVG-Struktur für eine flüssige Morphing","Jedes Symbol kann sich in ein anderes verändern","Kompatibilität mit Koordinaten und Opazität für jede Linie","Skalierbare Architektur für komplexe Schnittstellen"],"pt":["Transformação de forma real, não crossfades","Utilização de três linhas SVG para cada ícone","Compatibilidade com ferramentas de IA para criação de ícones","Capacidade de morphar qualquer ícone em outro","Utilização de coordenadas e opacidade para definição de linhas","Suporte à criação de ícones personalizados"],"ru":["Реальное преобразование формы, а не перекрестные затухания","Использование трех линий SVG для каждой иконки","Совместимость с ИИ Агентами для создания иконок","Возможность преобразования любой иконки в другую","Использование координат и прозрачности для определения линий","Поддержка создания пользовательских иконок"],"ar":["التحول الفعلي للشكل، وليس عبر التلاشي المتقاطع","استخدام ثلاثة خطوط SVG لكل أيقونة","التأثير مع أدوات الذكاء الاصطناعي لإنشاء الأيقونات","القدرة على تحويل أي أيقونة إلى أخرى","استخدام الإحداثيات والopacity لتعريف الخطوط","دعم إنشاء الأيقونات المخصصة"]},"keywords":{"en":["how to use morphing-icons","morphing-icons alternative","morphing-icons setup guide","what is morphing-icons","morphing-icons vs icon animation libraries","morphing-icons install","morphing-icons SVG structure","morphing-icons shape transformation"],"zh":["Morphing Icons","SVG图标变形","三线结构","图标变形技术","AIエージェント","TS定义线的坐标和不透明度"],"ja":["Morphing Icons","SVGアイコン変形","3ライン構造","アイコン変形技術","AIエージェント","TSを使用して線の座標と不透明度を定義"],"ko":["Morphing Icons","SVG 아이콘 변형","3라인 구조","아이콘 변형 기술","AI 에이전트","TS를 사용하여 선의 좌표와 불투명도를 정의"],"es":["morphing-icons","iconos que se transforman","interfaces mejoradas","SVG","desarrollo de interfaces","herramientas de diseño","Agentes de IA para diseño","Guías de configuración de morphing-icons"],"fr":["morphing-icons","icônes qui se transforment","interfaces améliorées","SVG","développement d''interfaces","outils de design","Outils d''IA pour la conception","Mise en place des icônes morphing"],"de":["morphing-icons","Symbole die sich verändern","verbesserte Schnittstellen","SVG","Entwicklung von Schnittstellen","Designwerkzeuge","Ii-Tools für die Gestaltung","Einrichtungsleitfaden für morphing-icons"],"pt":["ícones morfáveis","ferramentas de IA","transformação de forma","três linhas SVG","criação de ícones personalizados","morphing de ícones","desenvolvimento de interfaces","ícones dinâmicos","design de ícones"],"ru":["морфинг-иконки","ИИ Агенты","преобразование формы","три линии SVG","создание пользовательских иконок","морфинг иконок","разработка интерфейсов","динамические иконки","дизайн иконок"],"ar":["أيقونات متغيرة","أدوات الذكاء الاصطناعي","تحويل الشكل","ثلاثة خطوط SVG","إنشاء أيقونات مخصصة","تحويل الأيقونات","تنمية الواجهات","أيقونات ديناميكية","تصميم الأيقونات"]}},"owner":"raphaelsalaja","repo":"userinterface-wiki","repoPath":"raphaelsalaja/userinterface-wiki","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.286Z","topics":[],"category":"community","skillMd":{"name":"morphing-icons","description":"Build icon components where any icon morphs into any other through SVG line transformation. Use when asked to create morphing icons, build icon transitions, animate between icons, or transform icons.","version":"1.0.0","bodyPreview":"# Morphing Icons\n\nBuild icons that transform through actual shape transformation, not crossfades. Any icon can morph into any other because they share the same underlying 3-line structure.\n\n## Core Concept\n\nEvery icon is composed of exactly **three SVG lines**. Icons that need fewer lines collapse the extras to invisible center points. This constraint enables seamless morphing between any two icons.\n\n## Architecture\n\n### 1. Line Definition\n\nEach line has coordinates and optional opacity:\n\n```ts","body":"# Morphing Icons\n\nBuild icons that transform through actual shape transformation, not crossfades. Any icon can morph into any other because they share the same underlying 3-line structure.\n\n## Core Concept\n\nEvery icon is composed of exactly **three SVG lines**. Icons that need fewer lines collapse the extras to invisible center points. This constraint enables seamless morphing between any two icons.\n\n## Architecture\n\n### 1. Line Definition\n\nEach line has coordinates and optional opacity:\n\n```ts\ninterface IconLine {\n  x1: number;\n  y1: number;\n  x2: number;\n  y2: number;\n  opacity?: number;\n}\n```\n\n### 2. Collapsed Lines\n\nIcons needing fewer than 3 lines use collapsed lines—zero-length lines at the center:\n\n```ts\nconst CENTER = 7; // Center of 14x14 viewbox\n\nconst collapsed: IconLine = {\n  x1: CENTER,\n  y1: CENTER,\n  x2: CENTER,\n  y2: CENTER,\n  opacity: 0,\n};\n```\n\n### 3. Icon Definition\n\nEach icon has exactly 3 lines, optional rotation, and optional group:\n\n```ts\ninterface IconDefinition {\n  lines: [IconLine, IconLine, IconLine];\n  rotation?: number;\n  group?: string;\n}\n```\n\n### 4. Rotation Groups\n\nIcons sharing a `group` animate rotation when transitioning between them. Icons without matching groups jump to the new rotation instantly:\n\n```ts\n// These rotate smoothly between each other\n{ lines: plusLines, rotation: 0, group: \"plus-cross\" }   // plus\n{ lines: plusLines, rotation: 45, group: \"plus-cross\" }  // cross\n\n// These rotate smoothly between each other\n{ lines: arrowLines, rotation: 0, group: \"arrow\" }       // arrow-right\n{ lines: arrowLines, rotation: 90, group: \"arrow\" }      // arrow-down\n{ lines: arrowLines, rotation: 180, group: \"arrow\" }     // arrow-left\n{ lines: arrowLines, rotation: -90, group: \"arrow\" }     // arrow-up\n```\n\n## Implementation Rules\n\n### `morphing-three-lines`\nEvery icon MUST use exactly 3 lines. No more, no fewer.\n\n**Fail:**\n```ts\nconst checkIcon = {\n  lines: [\n    { x1: 2, y1: 7.5, x2: 5.5, y2: 11 },\n    { x1: 5.5, y1: 11, x2: 12, y2: 3 },\n  ], // Only 2 lines\n};\n```\n\n**Pass:**\n```ts\nconst checkIcon = {\n  lines: [\n    { x1: 2, y1: 7.5, x2: 5.5, y2: 11 },\n    { x1: 5.5, y1: 11, x2: 12, y2: 3 },\n    collapsed, // Third line collapsed\n  ],\n};\n```\n\n### `morphing-use-collapsed`\nUnused lines must use the collapsed constant, not omission or null.\n\n**Fail:**\n```ts\nconst minusIcon = {\n  lines: [\n    { x1: 2, y1: 7, x2: 12, y2: 7 },\n    null,\n    null,\n  ],\n};\n```\n\n**Pass:**\n```ts\nconst minusIcon = {\n  lines: [\n    { x1: 2, y1: 7, x2: 12, y2: 7 },\n    collapsed,\n    collapsed,\n  ],\n};\n```\n\n### `morphing-consistent-viewbox`\nAll icons must use the same viewBox (14x14 recommended).\n\n**Fail:**\n```ts\n// Mixing viewbox scales\nconst icon1 = { lines: [{ x1: 2, y1: 7, x2: 12, y2: 7 }, ...] }; // 14x14\nconst icon2 = { lines: [{ x1: 4, y1: 14, x2: 24, y2: 14 }, ...] }; // 28x28\n```\n\n**Pass:**\n```ts\nconst VIEWBOX_SIZE = 14;\nconst CENTER = 7;\n// All coordinates within 0-14 range\n```\n\n### `morphing-group-variants`\nIcons that are rotational variants MUST share the same group and base lines.\n\n**Fail:**\n```ts\n// Different line definitions for arrows\nconst arrowRight = { lines: [{ x1: 2, y1: 7, x2: 12, y2: 7 }, ...] };\nconst arrowDown = { lines: [{ x1: 7, y1: 2, x2: 7, y2: 12 }, ...] }; // Different!\n```\n\n**Pass:**\n```ts\nconst arrowLines: [IconLine, IconLine, IconLine] = [\n  { x1: 2, y1: 7, x2: 12, y2: 7 },\n  { x1: 7.5, y1: 2.5, x2: 12, y2: 7 },\n  { x1: 7.5, y1: 11.5, x2: 12, y2: 7 },\n];\n\nconst icons = {\n  \"arrow-right\": { lines: arrowLines, rotation: 0, group: \"arrow\" },\n  \"arrow-down\": { lines: arrowLines, rotation: 90, group: \"arrow\" },\n  \"arrow-left\": { lines: arrowLines, rotation: 180, group: \"arrow\" },\n  \"arrow-up\": { lines: arrowLines, rotation: -90, group: \"arrow\" },\n};\n```\n\n### `morphing-spring-rotation`\nRotation between grouped icons should use spring physics for natural motion.\n\n**Fail:**\n```tsx\n<motion.g animate={{ rotate: rotation }} transition={{ duration: 0.3 }} />\n```\n\n**Pass:**\n```tsx\nconst rotation = useSpring(definition.rotation ?? 0, activeTransition);\n\n<motion.g style={{ rotate: rotation, transformOrigin: \"center\" }} />\n```\n\n### `morphing-reduced-motion`\nRespect `prefers-reduced-motion` by disabling animations.\n\n**Fail:**\n```tsx\nfunction MorphingIcon({ icon }: Props) {\n  return <motion.line animate={...} transition={{ duration: 0.4 }} />;\n}\n```\n\n**Pass:**\n```tsx\nfunction MorphingIcon({ icon }: Props) {\n  const reducedMotion = useReducedMotion() ?? false;\n  const activeTransition = reducedMotion ? { duration: 0 } : transition;\n  \n  return <motion.line animate={...} transition={activeTransition} />;\n}\n```\n\n### `morphing-jump-non-grouped`\nWhen transitioning between icons NOT in the same group, rotation should jump instantly.\n\n**Fail:**\n```tsx\n// Always animating rotation regardless of group\nuseEffect(() => {\n  rotation.set(definition.rotation ?? 0);\n}, [definition]);\n```\n\n**Pass:**\n```tsx\nuseEffect(() => {\n  if (shouldRotate) {\n    rotation.set(definition.rotation ?? 0); // Animate\n  } else {\n    rotation.jump(definition.rotation ?? 0); // Instant\n  }\n}, [definition, shouldRotate]);\n```\n\n### `morphing-strokelinecap-round`\nLines should use `strokeLinecap=\"round\"` for polished endpoints.\n\n**Fail:**\n```tsx\n<motion.line strokeLinecap=\"butt\" />\n```\n\n**Pass:**\n```tsx\n<motion.line strokeLinecap=\"round\" />\n```\n\n### `morphing-aria-hidden`\nIcon SVGs should be `aria-hidden` since they''re decorative.\n\n**Fail:**\n```tsx\n<svg width={size} height={size}>...</svg>\n```\n\n**Pass:**\n```tsx\n<svg width={size} height={size} aria-hidden=\"true\">...</svg>\n```\n\n## Common Icon Patterns\n\n### Two-Line Icons (check, minus, equals, chevron)\nUse one or two collapsed lines:\n\n```ts\nconst check = {\n  lines: [\n    { x1: 2, y1: 7.5, x2: 5.5, y2: 11 },\n    { x1: 5.5, y1: 11, x2: 12, y2: 3 },\n    collapsed,\n  ],\n};\n```\n\n### Three-Line Icons (menu, asterisk, play)\nUse all three lines:\n\n```ts\nconst menu = {\n  lines: [\n    { x1: 2, y1: 3.5, x2: 12, y2: 3.5 },\n    { x1: 2, y1: 7, x2: 12, y2: 7 },\n    { x1: 2, y1: 10.5, x2: 12, y2: 10.5 },\n  ],\n};\n```\n\n### Point Icons (more, grip)\nUse zero-length lines as dots:\n\n```ts\nconst more = {\n  lines: [\n    { x1: 3, y1: 7, x2: 3, y2: 7 },\n    { x1: 7, y1: 7, x2: 7, y2: 7 },\n    { x1: 11, y1: 7, x2: 11, y2: 7 },\n  ],\n};\n```\n\n## Recommended Transition\n\nUse exponential ease-out for smooth morphing:\n\n```ts\nconst defaultTransition: Transition = {\n  ease: [0.19, 1, 0.22, 1],\n  duration: 0.4,\n};\n```\n\n## Output Format\n\nWhen auditing morphing icon implementations, output findings as:\n\n```\nfile:line - [rule-id] description of issue\n\nExample:\ncomponents/icon/index.tsx:45 - [morphing-three-lines] Icon \"check\" has only 2 lines, needs collapsed third\ncomponents/icon/index.tsx:78 - [morphing-group-variants] arrow-down uses different line definitions than arrow-right\n```\n\n## Summary Table\n\nAfter findings, output a summary:\n\n| Rule | Count | Severity |\n|------|-------|----------|\n| `morphing-three-lines` | 2 | HIGH |\n| `morphing-group-variants` | 1 | HIGH |\n| `morphing-reduced-motion` | 1 | MEDIUM |\n\n## References\n\n- [Benji''s experiments with Claude](https://benji.org/morphing-icons-with-claude)\n- [Motion useSpring](https://motion.dev/docs/react-use-spring)\n- [SVG Line Element](https://developer.mozilla.org/en-US/docs/Web/SVG/Element/line)\n"},"lastSynced":"2026-03-08T02:00:59.817Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced icon transformation capabilities using SVG.","zh":"非常适合需要使用SVG进行高级图标转换的前端代理。","ja":"フロントエンドエージェントがSVGを使用した高度なアイコン変換機能を必要とする場合に最適です。","ko":"프론트엔드 에이전트가 SVG를 사용하여 고급 아이콘 변환 기능을 필요로 할 때 적합합니다.","es":"Perfecto para agentes Frontend que necesitan capacidades avanzadas de transformación de iconos utilizando SVG.","fr":"Parfait pour les agents Frontend ayant besoin de capacités avancées de transformation d''icônes en utilisant SVG.","de":"Perfekt für Frontend-Agents, die erweiterte Icon-Transformationsfunktionen mit SVG benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de transformação de ícones usando SVG.","ru":"Идеально для агентов Frontend, которым необходимы продвинутые возможности преобразования иконок с помощью SVG.","ar":"مثالي لعميل واجهة المستخدم الذين يحتاجون إلى قدرات متقدمة لتحويل الأيقونات باستخدام SVG."},"recommendation":{"en":"Empowers agents to create seamless icon morphing effects using a 3-line SVG structure, enabling shape transformation between any two icons, and leveraging SVG lines with coordinates and optional opacity.","zh":"赋予代理创建无缝图标形态效果的能力，使用3行SVG结构，使得任何两個图标之间的形状转换成为可能，并利用带有坐标和可选不透明度的SVG线。","ja":"エージェントが3行のSVG構造を使用してシームレスなアイコンモーフィング効果を作成できるようにし、任意の2つのアイコン間の形状変換を可能にし、座標とオプションの不透明度を持つSVG線を利用します。","ko":"에이전트가 3행 SVG 구조를 사용하여 무봉태 아이콘 모핑 효과를 생성할 수 있도록 하여任意의 두 개의 아이콘 사이의 형태 변환을 가능하게 하며, 좌표 및 선택적 불투명도를 갖는 SVG 선을 활용합니다.","es":"Habilita a los agentes a crear efectos de morfismo de iconos sin problemas utilizando una estructura SVG de 3 líneas, lo que permite la transformación de forma entre dos iconos y aprovecha las líneas SVG con coordenadas y opacidad opcional.","fr":"Permet aux agents de créer des effets de morphisme d''icônes sans problème en utilisant une structure SVG de 3 lignes, ce qui permet la transformation de forme entre deux icônes et exploite les lignes SVG avec des coordonnées et une opacité optionnelle.","de":"Ermöglicht es Agents, nahtlose Icon-Morphing-Effekte zu erstellen, indem sie eine 3-zeilige SVG-Struktur verwenden, die eine Formtransformation zwischen zwei Icons ermöglicht und SVG-Linien mit Koordinaten und optionaler Opazität nutzt.","pt":"Habilita os agentes a criar efeitos de morfismo de ícones sem interrupção usando uma estrutura SVG de 3 linhas, permitindo a transformação de forma entre qualquer duas ícones e aproveitando as linhas SVG com coordenadas e opacidade opcional.","ru":"Наделяет агентов возможностью создавать бесшовные эффекты морфинга иконок, используя 3-строчную структуру SVG, что позволяет выполнять преобразование форм между любыми двумя иконками и использовать строки SVG с координатами и опциональной непрозрачностью.","ar":"يمنح الوكيل khảية إنشاء تأثيرات تحويل الأيقونات بدون انقطاع باستخدام هيكل SVG من 3 أسطر، مما يسمح بتحويل الشكل بين أي زوج من الأيقونات واستخدام خطوط SVG مع الإحداثيات وال-opacity الإختياري."},"useCases":{"en":["Generating morphing icons for dynamic UI elements","Creating seamless shape transformations for icon animations","Building icon sets with consistent 3-line SVG structure"],"zh":["为动态UI元素生成形态图标","创建无缝形状变换用于图标动画","使用一致的3行SVG结构构建图标集"],"ja":["動的UI要素用のモーフィングアイコンを生成する","アイコンアニメーション用のシームレスな形状変換を作成する","一貫した3行SVG構造を使用してアイコンセットを構築する"],"ko":["동적 UI 요소에 대한 모핑 아이콘 생성","아이콘 애니메이션을 위한 무봉태 형태 변환 생성","일관된 3행 SVG 구조를 사용하여 아이콘 세트 구축"],"es":["Generar iconos morfantes para elementos de interfaz de usuario dinámicos","Crear transformaciones de forma sin problemas para animaciones de iconos","Crear conjuntos de iconos con una estructura SVG de 3 líneas coherente"],"fr":["Générer des icônes morphantes pour des éléments d''interface utilisateur dynamiques","Créer des transformations de forme sans problème pour des animations d''icônes","Construire des ensembles d''icônes avec une structure SVG de 3 lignes cohérente"],"de":["Erzeugen von Morphing-Icons für dynamische Benutzeroberflächenelemente","Erstellen von nahtlosen Formtransformationen für Icon-Animationen","Erstellen von Icon-Sätzen mit einer konsistenten 3-zeiligen SVG-Struktur"],"pt":["Geração de ícones morfantes para elementos de interface do usuário dinâmicos","Criação de transformações de forma sem interrupção para animações de ícones","Construção de conjuntos de ícones com estrutura SVG de 3 linhas consistente"],"ru":["Генерация морфных иконок для динамических элементов интерфейса пользователя","Создание бесшовных преобразований форм для анимаций иконок","Построение наборов иконок с последовательной 3-строчной структурой SVG"],"ar":["توليد الأيقونات المتغيرة الشكل لعناصر واجهة المستخدم الديناميكية","إنشاء تحويلات الشكل بدون انقطاع لرسوم متحركة الأيقونات","بناء مجموعات الأيقونات مع هيكل SVG من 3 أسطر متسق"]},"limitations":{"en":["Requires SVG compatibility","Limited to 3-line SVG structure"],"zh":["需要SVG兼容性","仅限于3行SVG结构"],"ja":["SVGの互換性が必要","3行SVG構造のみに限定される"],"ko":["SVG 호환성이 필요","3행 SVG 구조로만 제한"],"es":["Requiere compatibilidad con SVG","Limitado a la estructura SVG de 3 líneas"],"fr":["Nécessite la compatibilité SVG","Limité à la structure SVG de 3 lignes"],"de":["Benötigt SVG-Kompatibilität","Begrenzt auf die 3-zeilige SVG-Struktur"],"pt":["Requer compatibilidade com SVG","Limitado à estrutura SVG de 3 linhas"],"ru":["Требует совместимости с SVG","Ограничен 3-строчной структурой SVG"],"ar":["يتطلب توافقًا مع SVG","محدود بهيكل SVG من 3 أسطر"]},"version":4},"contentHash":"690cb3ebe7860f77b4fedd6f951aba6aff129faa84a98849489de4338c88f97f","qualityScore":53}');
