INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('raphaelsalaja/userinterface-wiki/morphing-icons', 'morphing-icons', 'raphaelsalaja', 'userinterface-wiki', 'community', 'morphing-icons raphaelsalaja userinterface-wiki community Morphing-icons is a technical solution for creating icons that transform through shape transformation, benefiting developers and designers. It utilizes a 3-line SVG structure for seamless morphing. Morphing Icons是一种基于SVG的图标变形技术，通过三线结构实现图标之间的无缝变形 Morphing Iconsは、SVGベースのアイコン変形技術であり、3ライン構造によってアイコン間のシームレスな変形を実現する Morphing Icons는 SVG 기반의 아이콘 변형 기술로, 3라인 구조를 통해 아이콘 간의 무제한 변형을 구현합니다 Morphing-icons permite crear iconos que se transforman mediante la modificación real de formas, utilizando una estructura de 3 líneas SVG Morphing-icons permet de créer des icônes qui se transforment par une véritable modification de formes, en utilisant une structure de 3 lignes SVG Morphing-icons ermöglicht die Erstellung von Symbolen, die sich durch reale Formveränderung verändern, unter Verwendung einer 3-Linien-SVG-Struktur Morfing-ícones é uma técnica que permite a transformação de ícones mediante a alteração da forma, utilizando três linhas SVG. As ferramentas de IA facilitam a criação desses ícones. Морфинг-иконки - это техника, позволяющая преобразовывать иконки посредством изменения формы, используя три линии SVG. ИИ Агенты упрощают создание таких иконок. الأيقونات المتغيرة هي تقنية تسمح بتحويل الأيقونات من خلال تغيير الشكل، باستخدام ثلاثة خطوط SVG. أدوات الذكاء الاصطناعي تسهل إنشاء هذه الأيقونات. how to use morphing-icons morphing-icons alternative morphing-icons setup guide what is morphing-icons morphing-icons vs icon animation libraries morphing-icons install morphing-icons SVG structure morphing-icons shape transformation Morphing Icons SVG图标变形 三线结构 图标变形技术 AIエージェント TS定义线的坐标和不透明度 Utilizes a 3-line SVG structure for seamless icon morphing Enables any icon to morph into any other icon Collapses extra lines to invisible center points for icons with fewer lines Defines each line with coordinates and optional opacity Supports shape transformation without crossfades Morphing-icons is a technique for building icons that transform through actual shape transformation, not crossfades, using a shared 3-line SVG structure.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Liinkiing/larastack/native-data-fetching', 'community', 'Liinkiing', 'larastack', 'Liinkiing/larastack', 'native-data-fetching', 0, 0, 53, '2026-03-08T01:57:15.331Z', '2026-03-08T02:03:13.763Z', 'b4e72ed9215cac46f40a461e816acd634797512d97e39477925087eccc6220be', '{"id":"Liinkiing/larastack/native-data-fetching","name":"native-data-fetching","description":{"en":"The native-data-fetching skill provides a fresh Laravel 12 Next 16 Expo 55 starter with built-in OAuth and Socialite for developers to streamline data fetching and networking tasks.","zh":"Native-data-fetching 是一个 Laravel 12 Next 16 Expo 55 启动器，内置 OAuth 和 Socialite，使用 Panda CSS 和 NativeWind","ja":"ネイティブデータフェッチングは、Laravel 12 Next 16 Expo 55 スターターであり、OAuth と Socialite が組み込まれており、Panda CSS と NativeWind を使用しています","ko":"네이티브 데이터 패칭은 Laravel 12 Next 16 Expo 55 스타터로, OAuth 및 Socialite가 내장되어 있으며 Panda CSS 및 NativeWind를 사용합니다","es":"Native-data-fetching es una habilidad para desarrolladores que permite configurar solicitudes de API y caché con Expo y tecnologías como React Query y SWR","fr":"Native-data-fetching est une compétence pour les développeurs qui permet de configurer les requêtes API et le cache avec Expo et des technologies comme React Query et SWR","de":"Native-data-fetching ist eine Fähigkeit für Entwickler, die es ermöglicht, API-Anfragen und Caching mit Expo und Technologien wie React Query und SWR zu konfigurieren","pt":"O native-data-fetching é uma habilidade que fornece uma forma eficiente de trabalhar com API requests e data fetching em projetos Expo e Laravel","ru":"ИИ Агент native-data-fetching предоставляет эффективный способ работы с API-запросами и fetching данных в проектах Expo и Laravel","ar":"native-data-fetching هو أداة قوية لتعامل مع طلبات API و fetching البيانات في مشاريع Expo و Laravel"},"seo":{"title":{"en":"native-data-fetchi