INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Liinkiing/larastack/native-data-fetching', 'native-data-fetching', 'Liinkiing', 'larastack', 'community', 'native-data-fetching Liinkiing larastack community The native-data-fetching skill provides a fresh Laravel 12 Next 16 Expo 55 starter with built-in OAuth and Socialite for developers to streamline data fetching and networking tasks. Native-data-fetching 是一个 Laravel 12 Next 16 Expo 55 启动器，内置 OAuth 和 Socialite，使用 Panda CSS 和 NativeWind ネイティブデータフェッチングは、Laravel 12 Next 16 Expo 55 スターターであり、OAuth と Socialite が組み込まれており、Panda CSS と NativeWind を使用しています 네이티브 데이터 패칭은 Laravel 12 Next 16 Expo 55 스타터로, OAuth 및 Socialite가 내장되어 있으며 Panda CSS 및 NativeWind를 사용합니다 Native-data-fetching es una habilidad para desarrolladores que permite configurar solicitudes de API y caché con Expo y tecnologías como React Query y SWR Native-data-fetching est une compétence pour les développeurs qui permet de configurer les requêtes API et le cache avec Expo et des technologies comme React Query et SWR Native-data-fetching ist eine Fähigkeit für Entwickler, die es ermöglicht, API-Anfragen und Caching mit Expo und Technologien wie React Query und SWR zu konfigurieren O native-data-fetching é uma habilidade que fornece uma forma eficiente de trabalhar com API requests e data fetching em projetos Expo e Laravel ИИ Агент native-data-fetching предоставляет эффективный способ работы с API-запросами и fetching данных в проектах Expo и Laravel native-data-fetching هو أداة قوية لتعامل مع طلبات API و fetching البيانات في مشاريع Expo و Laravel how to use native-data-fetching native-data-fetching setup guide expo networking tutorial react query caching strategies native-data-fetching alternative to axios native-data-fetching vs react-native-fetch native-data-fetching install native-data-fetching for AI agents native-data-fetching with socialite native-data-fetching Expo React Query API 请求 数据抓取 缓存策略 OAuth Socialite Panda CSS NativeWind Implements API requests using Expo''s fetch Sets up data fetching with React Query and SWR Handles network failures and offline scenarios Manages authentication and token renewal with Socialite Configures API URLs and environment variables native-data-fetching is a skill that enables efficient data fetching, caching, and network debugging for developers using Expo, React Query, and SWR.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('raudyagdel/ai_setup_and_tips/tailwind-4', 'community', 'raudyagdel', 'ai_setup_and_tips', 'raudyagdel/ai_setup_and_tips', 'tailwind-4', 0, 0, 53, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:23.673Z', '7dbf1477e95ef24f8685a989479ea3b5c525e61d94f2ca496887cecb7ceb4c9c', '{"id":"raudyagdel/ai_setup_and_tips/tailwind-4","name":"tailwind-4","description":{"en":"The tailwind-4 skill helps developers set up Markdown for AI agents, providing a styling decision tree and critical rules for dynamic values and conditional styles. This benefits developers working with Tailwind CSS and AI-powered tools.","zh":"Tailwind-4 是一种用于 AI 代理的样式配置工具，提供了动态值、条件样式和静态样式的设置","ja":"Tailwind-4 は、AI エージェント用のスタイル設定ツールであり、動的値、条件付きスタイル、静的スタイルの設定を提供する","ko":"Tailwind-4는 AI 에이전트를 위한 스타일 설정 도구로, 동적 값, 조건부 스타일, 정적 스타일의 설정을 제공합니다","es":"tailwind-4 es una herramienta de configuración para Agentes de IA que permite una mayor personalización y flexibilidad en la creación de interfaces de usuario","fr":"tailwind-4 est un outil de configuration pour les Agents d''IA qui permet une personnalisation et une flexibilité accrues dans la création d''interfaces utilisateur","de":"tailwind-4 ist ein Konfigurationstool für KI-Agents, das eine größere Anpassungsfähigkeit und Flexibilität bei der Erstellung von Benutzeroberflächen ermöglicht","pt":"O Tailwind-4 é uma ferramenta poderosa para estilizar aplicações web. Saiba como configurá-lo para ferramentas de IA.","ru":"Tailwind-4 - это мощный инструмент для стилизации веб-приложений. Узнайте, как настроить его для ИИ Агентов.","ar":"Tailwind-4 هو أداة قوية لتنسيق التطبيقات الويب. تعلم كيفية إعدادها لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"tailwind-4: AI Setup Guide for Markdown | AI Agent Skill","zh":"Tailwind-4 Setup Guide: AI Agent 配置最佳实践","ja":"Tailwind-4 セットアップガイド: AIエージェントのベストプラクティス","ko":"Tailwind-4 설정 가이드: AI 에이전트 최적화 방법","es":"Guía de configuración de tailwind-4 para Agentes de IA","fr":"Guide de configuration de tailwind-4 pour les Agents d''IA","de":"Konfigurationsleitfaden für tailwind-4 und KI-Agents","pt":"Guia de Configuração do Tailwind-4 para Ferramentas de IA","ru":"Настройка Tailwind-4 для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد Tailwind-4 لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to set up Tailwind 4 for AI agents like Copilot, Claude, Codex, and Gemini. Learn expert tips and best practices for styling decision trees and ...","zh":"了解 Tailwind-4 的关键规则和样式决策树，优化您的 AI 代理配置","ja":"Tailwind-4 の重要なルールとスタイルの決定ツリーをマスターして、AI エージェントの設定を最適化する","ko":"Tailwind-4의 중요 규칙과 스타일 결정 트리를 익히고 AI 에이전트 설정을 최적화 하십시오","es":"Aprende a configurar tailwind-4 para Agentes de IA como Copilot, Claude, Codex y Gemini con nuestras mejores prácticas","fr":"Découvrez comment configurer tailwind-4 pour les Agents d''IA tels que Copilot, Claude, Codex et Gemini avec nos meilleures pratiques","de":"Erfahren Sie, wie Sie tailwind-4 für KI-Agents wie Copilot, Claude, Codex und Gemini konfigurieren können, mit unseren Best Practices","pt":"Aprenda a configurar o Tailwind-4 para ferramentas de IA como Copilot, Claude, Codex e Gemini. Descubra as melhores práticas e dicas para um desenvolvimento ...","ru":"Узнайте, как настроить Tailwind-4 для ИИ Агентов, таких как Copilot, Claude, Codex и Gemini. Откройте для себя лучшие практики и советы для эффективного разв...","ar":"تعلم كيفية إعداد Tailwind-4 لأدوات الذكاء الاصطناعي مثل Copilot و Claude و Codex و Gemini. اكتشف أفضل الممارسات والنصائح من أجل تطوير فعال."},"definition":{"en":"tailwind-4 is a skill that enables AI agents to set up Markdown using Tailwind CSS, following a styling decision tree and adhering to critical rules for dynamic values and conditional styles.","zh":"Tailwind-4 是一种用于 AI 代理的样式配置工具，用于设置动态值、条件样式和静态样式","ja":"Tailwind-4 は、AI エージェント用のスタイル設定ツールであり、動的値、条件付きスタイル、静的スタイルを設定する","ko":"Tailwind-4는 AI 에이전트를 위한 스타일 설정 도구로, 동적 값, 조건부 스타일, 정적 스타일을 설정하는 데 사용됩니다","es":"tailwind-4 es un conjunto de clases y funciones para la creación de interfaces de usuario personalizadas para Agentes de IA","fr":"tailwind-4 est un ensemble de classes et de fonctions pour la création d''interfaces utilisateur personnalisées pour les Agents d''IA","de":"tailwind-4 ist ein Satz von Klassen und Funktionen für die Erstellung von benutzerdefinierten Benutzeroberflächen für KI-Agents","pt":"O Tailwind-4 é uma ferramenta de estilização para aplicações web que permite a configuração para ferramentas de IA.","ru":"Tailwind-4 - это инструмент стилизации для веб-приложений, который позволяет настраивать для ИИ Агентов.","ar":"Tailwind-4 هو أداة تنسيق لتطبيقات الويب التي تسمح بإعداد أدوات الذكاء الاصطناعي."},"features":{"en":["Generates Markdown using Tailwind class names","Handles dynamic values with style prop and template literals","Applies conditional styles using the `cn` function","Follows critical rules for using `var()` constants in style props","Supports setup for AI agents like Copilot, Claude, Codex, and Gemini"],"zh":["动态值设置","条件样式设置","静态样式设置","Tailwind 类名设置","样式决策树","关键规则：永远不要在类名中使用 var()"],"ja":["動的値の設定","条件付きスタイルの設定","静的スタイルの設定","Tailwind クラス名の設定","スタイルの決定ツリー","重要なルール：クラス名には var() を使用しない"],"ko":["동적 값 설정","조건부 스타일 설정","정적 스타일 설정","Tailwind 클래스 이름 설정","스타일 결정 트리","중요한 규칙: 클래스 이름에는 var()를 사용하지 않는다"],"es":["Uso de clases de Tailwind para la creación de interfaces de usuario","Soporte para valores dinámicos y condicionales","Compatibilidad con Copilot, Claude, Codex y Gemini","Uso de la función cn() para la aplicación de estilos condicionales","Soporte para la propiedad style con constantes var()"],"fr":["Utilisation de classes Tailwind pour la création d''interfaces utilisateur","Prise en charge de valeurs dynamiques et conditionnelles","Compatibilité avec Copilot, Claude, Codex et Gemini","Utilisation de la fonction cn() pour l''application de styles conditionnels","Prise en charge de la propriété style avec des constantes var()"],"de":["Verwendung von Tailwind-Klassen für die Erstellung von Benutzeroberflächen","Unterstützung für dynamische und bedingte Werte","Kompatibilität mit Copilot, Claude, Codex und Gemini","Verwendung der Funktion cn() für die Anwendung von bedingten Stilen","Unterstützung für die Eigenschaft style mit var()-Konstanten"],"pt":["Utilização de classes Tailwind para estilização","Geração de estilos dinâmicos com valores condicionais","Uso de constantes com var() para estilos estáticos","Integração com bibliotecas que não suportam classes","Evitando o uso de var() em nomes de classes"],"ru":["Использование классов Tailwind для стилизации","Генерация динамических стилей с условными значениями","Использование констант с var() для статических стилей","Интеграция с библиотеками, которые не поддерживают классы","Избегание использования var() в именах классов"],"ar":["استخدام الفئات Tailwind للتنسيق","إنشاء أنماط ديناميكية مع قيم مشروطة","استخدام الثوابت مع var() لأنماط ثابتة","التكامل مع المكتبات التي لا تدعم الفئات","تجنب استخدام var() في أسماء الفئات"]},"keywords":{"en":["how to use tailwind-4","tailwind-4 setup guide","tailwind-4 vs tailwind-3","tailwind-4 install","what is tailwind-4","tailwind-4 alternative","tailwind-4 for AI agents","tailwind-4 markdown setup","tailwind-4 styling decision tree"],"zh":["Tailwind-4","AI 代理","样式配置","动态值","条件样式","静态样式","Tailwind 类名","样式决策树","AI 工具","前端开发"],"ja":["Tailwind-4","AI エージェント","スタイル設定","動的値","条件付きスタイル","静的スタイル","Tailwind クラス名","スタイルの決定ツリー","AI ツール","フロントエンド開発"],"ko":["Tailwind-4","AI 에이전트","스타일 설정","동적 값","조건부 스타일","정적 스타일","Tailwind 클래스 이름","스타일 결정 트리","AI 도구","프론트엔드 개발"],"es":["tailwind-4","Agentes de IA","Copilot","Claude","Codex","Gemini","clases de Tailwind","valores dinámicos","estilos condicionales","configuración de Agentes de IA"],"fr":["tailwind-4","Agents d''IA","Copilot","Claude","Codex","Gemini","classes Tailwind","valeurs dynamiques","styles conditionnels","configuration des Agents d''IA"],"de":["tailwind-4","KI-Agents","Copilot","Claude","Codex","Gemini","Tailwind-Klassen","dynamische Werte","bedingte Stile","Konfiguration von KI-Agents"],"pt":["Tailwind-4","ferramentas de IA","estilização de aplicações web","classes Tailwind","estilos dinâmicos","var()","bibliotecas de front-end","desenvolvimento web"],"ru":["Tailwind-4","ИИ Агенты","стилизация веб-приложений","классы Tailwind","динамические стили","var()","библиотеки фронтенда","веб-разработка"],"ar":["Tailwind-4","أدوات الذكاء الاصطناعي","تنسيق تطبيقات الويب","فئات Tailwind","أنماط ديناميكية","var()","مكتبات الواجهة الأمامية","تطوير الويب"]}},"owner":"raudyagdel","repo":"ai_setup_and_tips","repoPath":"raudyagdel/ai_setup_and_tips","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.338Z","topics":[],"category":"community","skillMd":{"name":"tailwind-4","description":">","version":"1.1","bodyPreview":"## Styling Decision Tree\n\n```\nTailwind class exists?  → className=\"...\"\nDynamic value?          → style={{ width: `${x}%` }}\nConditional styles?     → cn(\"base\", condition && \"variant\")\nStatic only?            → className=\"...\" (no cn() needed)\nLibrary can''t use class?→ style prop with var() constants\n```\n\n## Critical Rules\n\n### Never Use var() in className\n\n```typescript\n// ❌ NEVER: var() in className\n<div className=\"bg-[var(--color-primary)]\" />\n<div className=\"text-[var(--text-color)]\" />\n\n//","body":"## Styling Decision Tree\n\n```\nTailwind class exists?  → className=\"...\"\nDynamic value?          → style={{ width: `${x}%` }}\nConditional styles?     → cn(\"base\", condition && \"variant\")\nStatic only?            → className=\"...\" (no cn() needed)\nLibrary can''t use class?→ style prop with var() constants\n```\n\n## Critical Rules\n\n### Never Use var() in className\n\n```typescript\n// ❌ NEVER: var() in className\n<div className=\"bg-[var(--color-primary)]\" />\n<div className=\"text-[var(--text-color)]\" />\n\n// ✅ ALWAYS: Use Tailwind semantic classes\n<div className=\"bg-primary\" />\n<div className=\"text-slate-400\" />\n```\n\n### Never Use Hex Colors\n\n```typescript\n// ❌ NEVER: Hex colors in className\n<p className=\"text-[#ffffff]\" />\n<div className=\"bg-[#1e293b]\" />\n\n// ✅ ALWAYS: Use Tailwind color classes\n<p className=\"text-white\" />\n<div className=\"bg-slate-800\" />\n```\n\n## The cn() Utility\n\n```typescript\nimport { clsx } from \"clsx\";\nimport { twMerge } from \"tailwind-merge\";\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs));\n}\n```\n\n### When to Use cn()\n\n```typescript\n// ✅ Conditional classes\n<div className={cn(\"base-class\", isActive && \"active-class\")} />\n\n// ✅ Merging with potential conflicts\n<button className={cn(\"px-4 py-2\", className)} />  // className might override\n\n// ✅ Multiple conditions\n<div className={cn(\n  \"rounded-lg border\",\n  variant === \"primary\" && \"bg-blue-500 text-white\",\n  variant === \"secondary\" && \"bg-gray-200 text-gray-800\",\n  disabled && \"opacity-50 cursor-not-allowed\"\n)} />\n```\n\n### When NOT to Use cn()\n\n```typescript\n// ❌ Static classes - unnecessary wrapper\n<div className={cn(\"flex items-center gap-2\")} />\n\n// ✅ Just use className directly\n<div className=\"flex items-center gap-2\" />\n```\n\n## Style Constants for Charts/Libraries\n\nWhen libraries don''t accept className (like Recharts):\n\n```typescript\n// ✅ Constants with var() - ONLY for library props\nconst CHART_COLORS = {\n  primary: \"var(--color-primary)\",\n  secondary: \"var(--color-secondary)\",\n  text: \"var(--color-text)\",\n  gridLine: \"var(--color-border)\",\n};\n\n// Usage with Recharts (can''t use className)\n<XAxis tick={{ fill: CHART_COLORS.text }} />\n<CartesianGrid stroke={CHART_COLORS.gridLine} />\n```\n\n## Dynamic Values\n\n```typescript\n// ✅ style prop for truly dynamic values\n<div style={{ width: `${percentage}%` }} />\n<div style={{ opacity: isVisible ? 1 : 0 }} />\n\n// ✅ CSS custom properties for theming\n<div style={{ \"--progress\": `${value}%` } as React.CSSProperties} />\n```\n\n## Common Patterns\n\n### Flexbox\n\n```typescript\n<div className=\"flex items-center justify-between gap-4\" />\n<div className=\"flex flex-col gap-2\" />\n<div className=\"inline-flex items-center\" />\n```\n\n### Grid\n\n```typescript\n<div className=\"grid grid-cols-3 gap-4\" />\n<div className=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6\" />\n```\n\n### Spacing\n\n```typescript\n// Padding\n<div className=\"p-4\" />           // All sides\n<div className=\"px-4 py-2\" />     // Horizontal, vertical\n<div className=\"pt-4 pb-2\" />     // Top, bottom\n\n// Margin\n<div className=\"m-4\" />\n<div className=\"mx-auto\" />       // Center horizontally\n<div className=\"mt-8 mb-4\" />\n```\n\n### Typography\n\n```typescript\n<h1 className=\"text-2xl font-bold text-white\" />\n<p className=\"text-sm text-slate-400\" />\n<span className=\"text-xs font-medium uppercase tracking-wide\" />\n```\n\n### Borders & Shadows\n\n```typescript\n<div className=\"rounded-lg border border-slate-700\" />\n<div className=\"rounded-full shadow-lg\" />\n<div className=\"ring-2 ring-blue-500 ring-offset-2\" />\n```\n\n### States\n\n```typescript\n<button className=\"hover:bg-blue-600 focus:ring-2 active:scale-95\" />\n<input className=\"focus:border-blue-500 focus:outline-none\" />\n<div className=\"group-hover:opacity-100\" />\n```\n\n### Responsive\n\n```typescript\n<div className=\"w-full md:w-1/2 lg:w-1/3\" />\n<div className=\"hidden md:block\" />\n<div className=\"text-sm md:text-base lg:text-lg\" />\n```\n\n### Dark Mode\n\n```typescript\n<div className=\"bg-white dark:bg-slate-900\" />\n<p className=\"text-gray-900 dark:text-white\" />\n```\n\n## Arbitrary Values (Escape Hatch)\n\n```typescript\n// ✅ OK for one-off values not in design system\n<div className=\"w-[327px]\" />\n<div className=\"top-[117px]\" />\n<div className=\"grid-cols-[1fr_2fr_1fr]\" />\n\n// ❌ Don''t use for colors - use theme instead\n<div className=\"bg-[#1e293b]\" />  // NO\n```\n\n## Keywords\ntailwind, css, styling, cn, utility classes, responsive\n"},"lastSynced":"2026-03-08T02:03:23.673Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing streamlined CSS styling with Tailwind CSS","zh":"非常适合需要简化CSS样式的前端代理，使用Tailwind CSS","ja":"Frontendエージェントがストリームライン化されたCSSスタイリングが必要な場合に最適です。Tailwind CSSを使用します","ko":"프론트엔드 에이전트가 스트림 라인化된 CSS 스타일링을 필요로 할 때 완벽합니다. Tailwind CSS를 사용합니다","es":"Perfecto para Agentes Frontend que necesitan un estilo de CSS optimizado con Tailwind CSS","fr":"Parfait pour les agents Frontend ayant besoin d''un style de CSS optimisé avec Tailwind CSS","de":"Perfekt für Frontend-Agents, die ein optimiertes CSS-Design mit Tailwind CSS benötigen","pt":"Perfeito para Agentes Frontend que precisam de estilização de CSS simplificada com Tailwind CSS","ru":"Идеально для агентов Frontend, которым требуется упрощенная стилизация CSS с помощью Tailwind CSS","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى تنسيق CSS مبسط مع Tailwind CSS"},"recommendation":{"en":"Empowers agents to dynamically apply conditional styles, leverage dynamic values, and utilize the styling decision tree with Tailwind classes, all while avoiding var() in className for optimal compatibility with libraries like React","zh":"赋予代理动态应用条件样式、利用动态值和利用样式决策树的Tailwind类的能力，同时避免在className中使用var()以实现与React等库的最佳兼容性","ja":"エージェントが条件スタイルを動的に適用し、動的値を活用し、スタイルの決定木のTailwindクラスを利用する能力を与えます。同時に、Reactなどのライブラリとの最適な互換性を実現するために、className内でvar()を使用しない","ko":"에이전트가 조건부 스타일을 동적으로 적용하고 동적 값을 활용하며 스타일 결정 트리의 Tailwind 클래스를 활용할 수 있는 능력을 부여합니다.同時に React 등의 라이브러리와의 최적의 호환성을實現하기 위해 className에서 var()를 사용하지 않음","es":"Habilita a los agentes a aplicar estilos condicionales de forma dinámica, aprovechar valores dinámicos y utilizar el árbol de decisión de estilos con clases de Tailwind, todo ello mientras evita usar var() en className para garantizar la compatibilidad óptima con bibliotecas como React","fr":"Permet aux agents d''appliquer des styles conditionnels de manière dynamique, d''exploiter des valeurs dynamiques et d''utiliser l''arbre de décision de style avec des classes Tailwind, le tout en évitant d''utiliser var() dans className pour assurer une compatibilité optimale avec des bibliothèques comme React","de":"Ermöglicht es den Agenten, bedingte Styles dynamisch anzuwenden, dynamische Werte zu nutzen und den Entscheidungsbaum für Styles mit Tailwind-Klassen zu verwenden, all dies unter Vermeidung von var() in className für eine optimale Kompatibilität mit Bibliotheken wie React","pt":"Habilita os agentes a aplicar dinamicamente estilos condicionais, aproveitar valores dinâmicos e utilizar a árvore de decisão de estilização com classes Tailwind, tudo isso sem usar var() em className para compatibilidade ótima com bibliotecas como React","ru":"Наделяет агентов возможностью динамически применять условные стили, использовать динамические значения и использовать дерево решений стиля с классами Tailwind, все это без использования var() в className для оптимальной совместимости с библиотеками seperti React","ar":"يسمح للوكلاء بتطبيق أنماط условية ديناميكيا، واستخدام قيم ديناميكية، واستخدام شجرة اتخاذ القرارات لتنسيق مع فئات Tailwind، كل ذلك بدون استخدام var() في className لتحقيق التوافق الأمثل مع المكتبات مثل React"},"useCases":{"en":["Applying conditional styles with cn() function","Generating dynamic values for style props","Styling Markdown content for AI-powered tools"],"zh":["使用cn()函数应用条件样式","为样式属性生成动态值","为AI驱动工具样式化Markdown内容"],"ja":["cn()関数を使用して条件スタイルを適用する","スタイル属性の動的値を生成する","AI駆動ツールのMarkdownコンテンツをスタイル設定する"],"ko":["cn() 함수를 사용하여 조건부 스타일을 적용하는 것","스타일 속성에 대한 동적 값을 생성","AI 구동 도구의 Markdown 컨텐츠를 스타일 설정"],"es":["Aplicar estilos condicionales con la función cn()","Generar valores dinámicos para propiedades de estilo","Estilar contenido de Markdown para herramientas impulsadas por IA"],"fr":["Appliquer des styles conditionnels avec la fonction cn()","Générer des valeurs dynamiques pour les propriétés de style","Styler le contenu Markdown pour les outils alimentés par l''IA"],"de":["Bedingte Styles mit der cn()-Funktion anwenden","Dynamische Werte für Style-Eigenschaften generieren","Markdown-Inhalt für künstlich intelligente Tools stylen"],"pt":["Aplicar estilos condicionais com a função cn()","Gerar valores dinâmicos para propriedades de estilo","Estilizar conteúdo Markdown para ferramentas com inteligência artificial"],"ru":["Применять условные стили с помощью функции cn()","Генерировать динамические значения для свойств стиля","Стилизовать контент Markdown для инструментов с искусственным интеллектом"],"ar":["تطبيق أنماط условية مع دالة cn()","генерировать قيم ديناميكية لممتلكات التنسيق","تنسيق محتوى Markdown لأدوات ذكية"]},"limitations":{"en":["Requires Tailwind CSS setup","Never use var() in className"],"zh":["需要Tailwind CSS设置","不应在className中使用var()"],"ja":["Tailwind CSSの設定が必要","className内でvar()を使用しない"],"ko":["Tailwind CSS 설정이 필요","className에서 var()를 사용하지 않음"],"es":["Requiere configuración de Tailwind CSS","Nunca use var() en className"],"fr":["Nécessite une configuration de Tailwind CSS","Ne jamais utiliser var() dans className"],"de":["Benötigt eine Tailwind-CSS-Konfiguration","Verwenden Sie niemals var() in className"],"pt":["Requer configuração do Tailwind CSS","Nunca use var() em className"],"ru":["Требует настройки Tailwind CSS","Никогда не используйте var() в className"],"ar":["يتطلب إعداد Tailwind CSS","أبدا لا تستخدم var() في className"]},"version":4},"contentHash":"7dbf1477e95ef24f8685a989479ea3b5c525e61d94f2ca496887cecb7ceb4c9c","qualityScore":53}');
