INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('WhatIfWeDigDeeper/typescript-features-by-version/package-json-maintenance', 'package-json-maintenance', 'WhatIfWeDigDeeper', 'typescript-features-by-version', 'community', 'package-json-maintenance WhatIfWeDigDeeper typescript-features-by-version community The package-json-maintenance skill automates JavaScript package maintenance tasks, including security audits and dependency updates, for developers working with npm, yarn, pnpm, or bun. Package.json 维护 AI 工具，支持安全审计、依赖更新和包管理，包括 npm、yarn、pnpm 和 bun Package.json メンテナンス AI ツールは、セキュリティ監査、依存関係の更新、パッケージ管理をサポートし、npm、yarn、pnpm、bun を含む Package.json 유지 보수 AI 도구는 보안 감사, 종속성 업데이트 및 패키지 관리를 지원하며 npm, yarn, pnpm 및 bun을 포함 package-json-maintenance gestiona tareas de mantenimiento de paquetes JavaScript, incluyendo auditorías de seguridad y actualizaciones de dependencias package-json-maintenance gère les tâches de maintenance de packages JavaScript, y compris les audits de sécurité et les mises à jour des dépendances package-json-maintenance verwaltet JavaScript-Paket-Wartungsaufgaben, einschließlich Sicherheitsaudits und Abhängigkeitsupdates O package-json-maintenance é uma ferramenta que ajuda a manter os pacotes JavaScript atualizados e seguros. Ele automatiza tarefas de manutenção, incluindo auditorias de segurança e atualizações de dependências Package-json-maintenance - это инструмент, который помогает поддерживать пакеты JavaScript в актуальном и безопасном состоянии. Он автоматизирует задачи по поддержке, включая аудиты безопасности и обновления зависимостей أداة package-json-maintenance هي أداة مساعدة لتحسين أداء حزم JavaScript. إنها تautomatiza مهام الصيانة، بما في ذلك عمليات التدقيق الأمنية وتحديث الإعتماديات how to use package-json-maintenance package-json-maintenance setup guide automated dependency management JavaScript package maintenance security audit tools package-json-maintenance vs npm package-json-maintenance install package-json-maintenance tutorial dependency update best practices Package.json 维护 AI 工具 安全审计 依赖更新 包管理 npm yarn pnpm bun Automatically detects and uses the project''s package manager (npm, yarn, pnpm, or bun) Supports specific packages, all packages, and glob patterns for flexible dependency management Performs security audits to identify vulnerabilities and CVEs Updates dependencies to ensure project security and stability Works with isolated worktrees for efficient package management package-json-maintenance is a skill that manages JavaScript package maintenance tasks in an isolated worktree, supporting various package managers and automating security audits and dependency updates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jdeweedata/circletel/Session Checker', 'community', 'jdeweedata', 'circletel', 'jdeweedata/circletel', 'Session Checker', 0, 0, 53, '2026-03-08T01:57:15.352Z', '2026-03-08T02:03:55.327Z', '06f431cd69e57eef1eedffc883f7e6b1fe150a3430be948b792097b3fd18ed0e', '{"id":"jdeweedata/circletel/Session Checker","name":"Session Checker","description":{"en":"The Session Checker skill analyzes CDRs to determine real-time connection status for CircleTel customers, benefiting developers and support teams. It automatically activates to check internet sessions, view session history, and debug connection issues.","zh":"Session Checker 是一个用于检查 CircleTel 客户 PPPoE/RADIUS 会话是否活跃的技能，通过分析 CDR 实时确定连接状态","ja":"Session Checker は、CircleTel の PPPoE/RADIUS セッションがアクティブであるかどうかを確認するスキルで、CDR を分析してリアルタイムで接続状態を決定します","ko":"Session Checker는 CircleTel 고객의 PPPoE/RADIUS 세션이 활성화되었는지 확인하는 기능으로, CDR를 분석하여 실시간으로 연결 상태를 결정합니다","es":"Session Checker es una habilidad para verificar sesiones PPPoE/RADIUS activas utilizando la API de Telemetría de Interstellio. Analiza registros de detalles de llamadas para determinar el estado de conexión en tiempo real.","fr":"Session Checker est une compétence pour vérifier les sessions PPPoE/RADIUS actives en utilisant l''API de télémétrie d''Interstellio. Elle analyse les enregistrements de détails d''appel pour déterminer l''état de connexion en temps réel.","de":"Session Checker ist eine Fähigkeit, um aktive PPPoE/RADIUS-Sitzungen mit der Interstellio-Telemetrie-API zu überprüfen. Sie analysiert Anrufdetailaufzeichnungen, um den Verbindungsstatus in Echtzeit zu bestimmen.","pt":"O Session Checker é uma habilidade que verifica se as sessões PPPoE/RADIUS dos clientes estão ativas, analisando CDR em tempo real.","ru":"Session Checker — это навык, который проверяет активные сессии PPPoE/RADIUS клиентов, анализируя CDR в режиме реального времени с помощью ИИ Агентов.","ar":"Session Checker هو مهارة تقوم بالتحقق من حالة جلسات PPPoE/RADIUS للعملاء، وتحليل سجلات التفاصيل الدورية في الوقت الفعلي باستخدام أدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"Session Checker: Real-time Connection Monitoring for AI A...","zh":"Session Checker 设置指南：实时检查 CircleTel 客户 PPPoE/RADIUS 会话","ja":"Session Checker のベストプラクティス：CircleTel の PPPoE/RADIUS セッション...","ko":"Session Checker 설정 가이드: CircleTel 고객의 PPPoE/RADIUS 세션 실시간 확인","es":"Guía de configuración de Session Checker para agentes de IA","fr":"Guide d''installation de Session Checker pour les outils d''IA","de":"Einrichtungsleitfaden für Session Checker als KI-Tool","pt":"Guia de Configuração do Session Checker: Verificação de S...","ru":"Руководство по настройке Session Checker: Проверка сессий...","ar":"دليل إعداد Session Checker: التحقق من جلسات PPPoE/RADIUS ..."},"description":{"en":"Discover how Session Checker uses Interstellio Telemetry API to analyze CDRs and troubleshoot connection issues - get started now and optimize your CircleTel...","zh":"了解 Session Checker 的功能和特点，实时检查 CircleTel 客户的 PPPoE/RADIUS 会话，提高网络连接的稳定性","ja":"Session Checker を使用して CircleTel の PPPoE/RADIUS セッションをリアルタイムで確認し、ネットワーク接続の安定性を高める","ko":"Session Checker를 사용하여 CircleTel 고객의 PPPoE/RADIUS 세션을 실시간으로 확인하고 네트워크 연결의 안정성을 높입니다","es":"Aprende a utilizar Session Checker para verificar sesiones PPPoE/RADIUS activas con la API de Telemetría de Interstellio","fr":"Découvrez comment utiliser Session Checker pour vérifier les sessions PPPoE/RADIUS actives avec l''API de télémétrie d''Interstellio","de":"Erfahren Sie, wie Sie Session Checker verwenden, um aktive PPPoE/RADIUS-Sitzungen mit der Interstellio-Telemetrie-API zu überprüfen","pt":"Aprenda a configurar o Session Checker para verificar se as sessões de internet dos clientes estão ativas, analisando CDR e histórico de sessões.","ru":"Узнайте, как настроить Session Checker для проверки активных сессий интернета клиентов, анализируя