INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yveskaufmann/go-psx-memcard/refresh-context', 'refresh-context', 'yveskaufmann', 'go-psx-memcard', 'community', 'refresh-context yveskaufmann go-psx-memcard community The refresh-context skill loads architectural context for PSX Memory Card Manager projects by reading key documentation files, benefiting developers working on the project Refresh Context 技术加载 PlayStation 内存卡管理项目的架构上下文，通过读取关键文档文件 Refresh Context AIエージェントは、PSX メモリーカード マネージャーのアーキテクチャ コンテキストを読み込みます Refresh Context 기술은 플레이스테이션 메모리 카드 이미지 관리자의 아키텍처 컨텍스트를 로드합니다 Refresh-context carga el contexto arquitectónico del proyecto PSX Memory Card Manager leyendo archivos de documentación clave Refresh-context charge le contexte architectural du projet PSX Memory Card Manager en lisant les fichiers de documentation clés Refresh-context lädt den architektonischen Kontext des PSX-Speicherkarten-Manager-Projekts, indem es Schlüsseldokumentationsdateien liest O Refresh Context é uma habilidade que carrega o contexto arquitetônico para o gerenciador de imagens de cartão de memória do PSX ИИ Агент Refresh Context загружает архитектурный контекст для менеджера изображений карты памяти PSX Refresh Context هو مهارة تقوم بتحميل السياق الهندسي لإدارة صور بطاقة الذاكرة PSX how to use refresh-context what is refresh-context refresh-context alternative refresh-context vs memory card managers refresh-context install refresh-context setup guide PSX Memory Card Manager projects architectural context loading debugging PSX Memory Card Manager issues Refresh Context PlayStation 内存卡管理 AI 技术 架构上下文 新会话 多组件修改 新功能实现 UI 调试 ViewModel 调试 Domain 调试 Reads and provides context from key documentation files Loads architectural context for PSX Memory Card Manager projects Supports understanding project architecture at the start of new sessions Facilitates making changes that affect multiple components Aids in debugging issues that span multiple layers (UI, ViewModel, Domain) Provides context for implementing new features refresh-context is a skill that loads architectural context for the PSX Memory Card Manager project by reading key documentation files');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Niraven/pokee-deep-research-skill/tinman', 'community', 'Niraven', 'pokee-deep-research-skill', 'Niraven/pokee-deep-research-skill', 'tinman', 0, 0, 53, '2026-03-08T01:57:15.659Z', '2026-03-08T02:14:02.643Z', 'f58f6ce2cb3d5ff8d7ca5a88c1e68c85a37e59125190de5945533750fdec000b', '{"id":"Niraven/pokee-deep-research-skill/tinman","name":"tinman","description":{"en":"Tinman is an OpenClaw skill for deep research using Pokee AI''s Deep Research API, providing security auditing and hardening for system infrastructure. It benefits developers and security professionals.","zh":"Tinman 是一个 OpenClaw 技能，用于深度研究和安全审计。它提供了多级安全检查和加固功能","ja":"Tinman は OpenClaw スキルで、深度研究とセキュリティ監査に使用されます。多段階のセキュリティチェックと強化機能を提供します","ko":"Tinman 은 OpenClaw 스킬로 심층 연구 및 보안 감사를 위해 사용됩니다. 다단계 보안 점검 및 강화 기능을 제공합니다","es":"Tinman es una habilidad de OpenClaw para investigación profunda utilizando la API de investigación profunda de Pokee AI, enfocada en auditoría y endurecimiento de la seguridad","fr":"Tinman est une compétence OpenClaw pour la recherche approfondie utilisant l''API de recherche approfondie de Pokee AI, axée sur l''audit et le durcissement de la sécurité","de":"Tinman ist eine OpenClaw-Fähigkeit für tiefe Recherche unter Verwendung der Deep Research-API von Pokee AI, fokussiert auf Sicherheitsaudit und -härtung","pt":"O Tinman é uma habilidade do OpenClaw para pesquisa aprofundada usando a API de Pesquisa Aprofundada da Pokee AI, fornecendo segurança avançada e hardening de infraestrutura.","ru":"ИИ Агент Tinman - это навык OpenClaw для глубокого исследования с помощью API глубокого исследования от Pokee AI, обеспечивающий продвинутую безопасность и укрепление инфраструктуры.","ar":"وكيل Tinman هو مهارة مفتاح OpenClaw للبحث المتقدم باستخدام واجهة برمجة التطبيقات البحث المتقدم من Pokee AI، مما يوفر أمانًا متقدمًا وتعزيزًا للبنية التحتية."},"seo":{"title":{"en":"Tinman: Deep Research API Setup Guide | AI Agent Skill","zh":"Tinman 安全审计和加固设置指南","ja":"Tinman のセキュリティ監査と強化ベストプラクティス","ko":"Tinman 보안 감사 및 강화 설정 가이드","es":"Guía de configuración de Tinman para auditoría de seguridad","fr":"Configurer Tinman pour l''audit de sécurité","de":"Tinman Sicherheitsaudit-Setup-Anleitung","pt":"Guia de Configuração do Tinman: Segurança Avançada para O...","ru":"Настройка ИИ Агента Tinman: Руководство по Безопасности O...","ar":"دليل إعداد Tinman: أمان متقدم لمفتاح OpenClaw"},"description":{"en":"Unlock the power of Pokee AI''s Deep Research API with Tinman. Learn how to integrate and secure your OpenClaw infrastructure today!","zh":"了解 Tinman 的安全审计和加固功能，包括 OpenClaw 安全检查和深度研究 API","ja":"Tinman のセキュリティ監査と強化機能について学びます。OpenClaw セキュリティチェックと深度研究 API を含みます","ko":"Tinman 의 보안 감사 및 강화 기능을 알아보세요. OpenClaw 보안 점검 및 심층 연구 API 포함","es":"Aprende a configurar Tinman para auditorías de seguridad y protección de infraestructura con OpenClaw y Pokee AI","fr":"Découvrez comment configurer Tinman pour des audits de sécurité et la protection des infrastructures avec OpenClaw et Pokee AI","de":"Erfahren Sie, wie Sie Tinman für Sicherheitsaudits und Infrastrukturschutz mit OpenClaw und Pokee AI konfigurieren","pt":"Aprenda a configurar o Tinman para auditoria de segurança e hardening de infraestrutura do OpenClaw com o Deep Research API da Pokee AI.","ru":"Узнайте, как настроить ИИ Агента Tinman для аудита безопасности и укрепления инфраструктуры OpenClaw с помощью Deep Research API от Pokee AI.","ar":"تعرف على كيفية إعداد Tinman لتدقيق الأمان وتعزيز البنية التحتية لمفتاح OpenClaw باستخدام واجهة برمجة التطبيقات Deep Research من Pokee AI."},"definition":{"en":"Tinman is a security auditing and hardening skill for OpenClaw and system infrastructure, utilizing Pokee AI''s Deep Research API.","zh":"Tinman 是一个用于 OpenClaw 的安全审计和加固技能","ja":"Tinman は OpenClaw 用のセキュリティ監査と強化スキルです","ko":"Tinman 은 OpenClaw 용 보안 감사 및 강화 스킬입니다","es":"Tinman es una herramienta de auditoría de seguridad para OpenClaw que utiliza la API de Pokee AI","fr":"Tinman est un outil d''audit de sécurité pour OpenClaw utilisant l''API de Pokee AI","de":"Tinman ist ein Sicherheitsaudit-Tool für OpenClaw, das die Pokee-AI-API verwendet","pt":"O Tinman é uma habilidade de segurança do OpenClaw que fornece auditoria e hardening de infraestrutura.","ru":"ИИ Агент Tinman - это навык безопасности OpenClaw, обеспечивающий аудит и укрепление инфраструктуры.","ar":"وكيل Tinman هو مهارة أمان مفتاح OpenClaw التي توفر تدقيقًا وتعزيزًا للبنية التحتية."},"features":{"en":["Performs security checks for Credentials in git with risk level S3","Provides security levels S0 to S4 for incident response and management","Utilizes Pokee AI''s Deep Research API for in-depth analysis","Supports .gitignore configuration for secure credential management","Offers alert and notification systems for security breaches"],"zh":["OpenClaw 安全检查","深度研究 API 集成","多级安全审计（S0-S4）","Credentials 在 git 中的安全检查","自动化安全加固建议"],"ja":["OpenClaw セキュリティチェック","深度研究 API 統合","多段階のセキュリティ監査（S0-S4）","Credentials 在 git 中のセキュリティチェック","自動化セキュリティ強化推奨"],"ko":["OpenClaw 보안 점검","심층 연구 API 통합","다단계 보안 감사（S0-S4）","Credentials 在 git 中의 보안 점검","자동화 보안 강화 추천"],"es":["Auditoría de seguridad de OpenClaw","Niveles de seguridad personalizables (S0-S4)","Comprobación de credenciales en git","Integración con la API de investigación profunda de Pokee AI","Notificación y recomendaciones de reparación para problemas de seguridad","Acciones inmediatas para problemas críticos de seguridad"],"fr":["Audit de sécurité OpenClaw","Niveaux de sécurité personnalisables (S0-S4)","Vérification des informations d''identification dans git","Intégration à l''API de recherche approfondie de Pokee AI","Notification et recommandations de correction pour les problèmes de sécurité","Actions immédiates pour les problèmes de sécurité critiques"],"de":["Sicherheitsaudit von OpenClaw","Anpassbare Sicherheitsstufen (S0-S4)","Überprüfung von Anmeldedaten in git","Integration in die Deep Research-API von Pokee AI","Benachrichtigung und Reparaturempfehlungen für Sicherheitsprobleme","Sofortmaßnahmen für kritische Sicherheitsprobleme"],"pt":["Auditoria de segurança do OpenClaw","Hardening de infraestrutura de sistema","Níveis de segurança personalizáveis (S0-S4)","Verificação de credenciais em repositórios Git","Integração com a API de Pesquisa Aprofundada da Pokee AI"],"ru":["Аудит безопасности OpenClaw","Укрепление инфраструктуры системы","Настраиваемые уровни безопасности (S0-S4)","Проверка учетных данных в репозиториях Git","Интеграция с API глубокого исследования от Pokee AI"],"ar":["تدقيق أمان مفتاح OpenClaw","تعزيز البنية التحتية للنظام","مستويات أمان قابلة للتعديل (S0-S4)","تحقق من بيانات اعتماد في مستودعات Git","التكامل مع واجهة برمجة التطبيقات البحث المتقدم من Pokee AI"]},"keywords":{"en":["how to use tinman","tinman setup guide","tinman alternative","tinman vs OpenClaw","tinman install","what is tinman","Pokee AI Deep Research API","OpenClaw security auditing","tinman security hardening"],"zh":["Tinman","OpenClaw","安全审计","深度研究","API 集成","多级安全检查","AIエージェント","安全加固"],"ja":["Tinman","OpenClaw","セキュリティ監査","深度研究","API 統合","多段階のセキュリティチェック","AIエージェント","セキュリティ強化"],"ko":["Tinman","OpenClaw","보안 감사","심층 연구","API 통합","다단계 보안 점검","AI 에이전트","보안 강화"],"es":["Tinman","auditoría de seguridad","OpenClaw","Pokee AI","API de investigación profunda","seguridad de la infraestructura","sistema de gestión de seguridad","herramientas de seguridad","agentes de IA para seguridad","Herramientas de seguridad para desarrolladores"],"fr":["Tinman","audit de sécurité","OpenClaw","Pokee AI","API de recherche approfondie","sécurité de l''infrastructure","système de gestion de la sécurité","outils de sécurité","agents d''IA pour la sécurité","Outils de sécurité pour les développeurs"],"de":["Tinman","Sicherheitsaudit","OpenClaw","Pokee AI","Deep Research-API","Infrastruktursicherheit","Sicherheitsmanagementsystem","Sicherheitstools","KI-Agents für Sicherheit","Sicherheitstools für Entwickler"],"pt":["Tinman","OpenClaw","segurança avançada","auditoria de segurança","hardening de infraestrutura","Deep Research API","Pokee AI","segurança de sistema","credenciais em Git"],"ru":["ИИ Агент Tinman","OpenClaw","продвинутая безопасность","аудит безопасности","укрепление инфраструктуры","API глубокого исследования","Pokee AI","безопасность системы","учетные данные в Git"],"ar":["وكيل Tinman","مفتاح OpenClaw","أمان متقدم","تدقيق أمان","تعزيز البنية التحتية","واجهة برمجة التطبيقات البحث المتقدم","Pokee AI","أمان النظام","بيانات اعتماد في Git"]}},"owner":"Niraven","repo":"pokee-deep-research-skill","repoPath":"Niraven/pokee-deep-research-skill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.659Z","topics":[],"category":"community","skillMd":{"name":"tinman","description":"Security auditing and hardening for OpenClaw and system infrastructure.","version":"1.0.0","bodyPreview":"# Tinman\n\nSecurity auditing and hardening for OpenClaw and system infrastructure.\n\n## Security Levels\n\n| Level | Description | Response |\n|-------|-------------|----------|\n| **S0** | Info | Log only |\n| **S1** | Low | Notify user |\n| **S2** | Medium | Alert + recommend fix |\n| **S3** | High | Immediate action required |\n| **S4** | Critical | Stop + notify immediately |\n\n## Checks\n\n### OpenClaw Security\n\n| Check | Risk | Action |\n|-------|------|--------|\n| Credentials in git | S3 | Add to .giti","body":"# Tinman\n\nSecurity auditing and hardening for OpenClaw and system infrastructure.\n\n## Security Levels\n\n| Level | Description | Response |\n|-------|-------------|----------|\n| **S0** | Info | Log only |\n| **S1** | Low | Notify user |\n| **S2** | Medium | Alert + recommend fix |\n| **S3** | High | Immediate action required |\n| **S4** | Critical | Stop + notify immediately |\n\n## Checks\n\n### OpenClaw Security\n\n| Check | Risk | Action |\n|-------|------|--------|\n| Credentials in git | S3 | Add to .gitignore, rotate |\n| Token expiration | S2 | Refresh tokens |\n| Exposed secrets | S4 | Rotate immediately |\n| Uncommitted changes | S1 | Review + commit |\n\n### System Security\n\n| Check | Risk | Action |\n|-------|------|--------|\n| SSH password auth | S2 | Disable, use keys only |\n| Open ports | S1 | Review with `ss -tlnp` |\n| Unattended upgrades | S2 | Enable automatic updates |\n| Firewall status | S2 | Verify ufw/iptables |\n\n## Workflow\n\n### 1. Security Scan\n\n```bash\n# Check for credentials in git\ngit log --all --full-history -- .credentials/\n\n# Check file permissions\nls -la ~/.credentials/\n\n# Check SSH config\ncat /etc/ssh/sshd_config | grep -E \"PasswordAuthentication|PermitRootLogin\"\n```\n\n### 2. Report Generation\n\n```markdown\n## Security Audit Report\n**Date:** 2026-02-20\n**Scope:** OpenClaw + System\n\n### Findings\n| Level | Issue | Recommendation |\n|-------|-------|----------------|\n| S2 | Token expires in 3 days | Refresh Google OAuth |\n\n### Actions Taken\n- [x] Verified .credentials/ permissions (600)\n- [ ] Refresh expiring tokens\n```\n\n### 3. Automated Monitoring\n\n```json\n{\n  \"name\": \"daily-security-check\",\n  \"schedule\": {\"kind\": \"cron\", \"expr\": \"0 6 * * *\"},\n  \"payload\": {\n    \"kind\": \"agentTurn\",\n    \"message\": \"Run tinman security scan. Check: credential perms, token expiration, git secrets. Report S2+ issues.\"\n  },\n  \"sessionTarget\": \"isolated\",\n  \"notify\": true\n}\n```\n\n## Best Practices\n\n1. **Credential hygiene** — 600 permissions, never in git\n2. **Token rotation** — Before expiration\n3. **Regular audits** — Weekly automated scans\n4. **Principle of least privilege** — Minimal permissions\n5. **Audit logging** — Track all changes\n\n## Emergency Response\n\nIf S4 (Critical) detected:\n\n1. **Stop** — Halt related operations\n2. **Assess** — Scope of exposure\n3. **Rotate** — Change all affected credentials\n4. **Review** — How did it happen\n5. **Prevent** — Update processes\n"},"lastSynced":"2026-03-08T02:14:02.643Z","agentAnalysis":{"suitability":{"en":"Perfect for Security Auditing Agents needing advanced infrastructure hardening and vulnerability assessment capabilities.","zh":"非常适合需要高级基础设施加固和漏洞评估能力的安全审计代理。","ja":"セキュリティ監査エージェントが高度なインフラストラクチャの強化と脆弱性評価機能を必要とする場合に最適です。","ko":"고급 인프라 강화 및 취약점 평가 기능이 필요한 보안 감사 에이전트에게 적합합니다.","es":"Perfecto para agentes de auditoría de seguridad que necesitan capacidades de endurecimiento de infraestructura avanzadas y evaluación de vulnerabilidades.","fr":"Parfait pour les agents d''audit de sécurité ayant besoin de capacités de durcissement d''infrastructure avancées et d''évaluation de vulnérabilités.","de":"Perfekt für Sicherheitsaudit-Agents, die erweiterte Infrastruktur-Härtung und Schwachstellenbewertungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Auditoria de Segurança que precisam de infraestrutura avançada de endurecimento e capacidades de avaliação de vulnerabilidades.","ru":"Идеально подходит для агентов безопасности, аудит которых требует продвинутого укрепления инфраструктуры и возможностей оценки уязвимостей.","ar":"مثالي لعميل فحص الأمن الذي يحتاج إلى تقوية بنية تحتية متقدمة وقدرات تقييم للضعف."},"recommendation":{"en":"Empowers agents to perform deep research using Pokee AI''s Deep Research API, providing security auditing and hardening for system infrastructure, including OpenClaw security checks and risk assessment using S0 to S4 security levels.","zh":"通过Pokee AI的Deep Research API使代理能够进行深入研究，提供系统基础设施的安全审计和强化，包括OpenClaw安全检查和使用S0到S4安全级别的风险评估。","ja":"Pokee AIのDeep Research APIを使用してエージェントが深い調査を実行できるようにし、システムインフラストラクチャのセキュリティ監査と強化を提供します。OpenClawのセキュリティチェックや、S0からS4のセキュリティレベルを使用したリスク評価も含まれます。","ko":"Pokee AI의 Deep Research API를 사용하여 에이전트가 심도 있는 연구를 수행할 수 있도록 하여 시스템 인프라의 보안 감사 및 강화 기능을 제공합니다. OpenClaw 보안 점검 및 S0에서 S4까지의 보안 수준을 사용한 위험 평가도 포함됩니다.","es":"Habilita a los agentes a realizar investigaciones profundas utilizando la API de investigación profunda de Pokee AI, proporcionando auditoría de seguridad y endurecimiento para la infraestructura del sistema, incluyendo controles de seguridad de OpenClaw y evaluación de riesgos utilizando los niveles de seguridad S0 a S4.","fr":"Habilite les agents à effectuer des recherches approfondies en utilisant l''API de recherche approfondie de Pokee AI, fournissant une audit de sécurité et un durcissement pour l''infrastructure du système, y compris les vérifications de sécurité OpenClaw et l''évaluation des risques en utilisant les niveaux de sécurité S0 à S4.","de":"Ermächtigt Agenten, tiefe Recherchen mit der Deep Research API von Pokee AI durchzuführen, wodurch Sicherheitsaudits und -härtung für die Systeminfrastruktur bereitgestellt werden, einschließlich OpenClaw-Sicherheitsprüfungen und Risikobewertung unter Verwendung der Sicherheitsstufen S0 bis S4.","pt":"Habilita os agentes a realizar pesquisas aprofundadas usando a Pokee AI''s Deep Research API, fornecendo auditoria de segurança e endurecimento para infraestrutura de sistema, incluindo verificações de segurança OpenClaw e avaliação de risco usando níveis de segurança S0 a S4.","ru":"Предоставляет агентам возможность проведения глубокого исследования с использованием Pokee AI''s Deep Research API, обеспечивая аудит безопасности и укрепление инфраструктуры системы, включая проверки безопасности OpenClaw и оценку риска с использованием уровней безопасности S0 до S4.","ar":"تمكّن الوكيل من إجراء بحث متعمق باستخدام Pokee AI''s Deep Research API، وتوفير فحص أمني وتقوية لبنية النظام، بما في ذلك فحص أمان OpenClaw وتقييم المخاطر باستخدام مستويات الأمان من S0 إلى S4."},"useCases":{"en":["Automating security audits for OpenClaw and system infrastructure","Identifying credentials in git for S3-level risks","Alerting users to medium-level risks with recommended fixes"],"zh":["为OpenClaw和系统基础设施自动化安全审计","在git中识别S3级别风险的凭据","提醒用户中级风险并提供推荐的修复方法"],"ja":["OpenClawとシステムインフラストラクチャのセキュリティ監査の自動化","gitのS3レベルのリスクの資格情報を特定する","ユーザーに中程度のリスクを通知し、推奨される修復方法を提供する"],"ko":["OpenClaw 및 시스템 인프라의 보안 감사를 자동화합니다.","git에서 S3 수준의 위험에 대한 자격 증명을 식별합니다.","사용자에게 중간 수준의 위험을 알리고 권장되는 수정 방법을 제공합니다."],"es":["Automatización de auditorías de seguridad para OpenClaw e infraestructura del sistema","Identificación de credenciales en git para riesgos de nivel S3","Alerta a los usuarios sobre riesgos de nivel medio con soluciones recomendadas"],"fr":["Automatisation des audits de sécurité pour OpenClaw et l''infrastructure du système","Identification des informations d''identification dans git pour les risques de niveau S3","Alerte des utilisateurs aux risques de niveau moyen avec des correctifs recommandés"],"de":["Automatisierung von Sicherheitsaudits für OpenClaw und Systeminfrastruktur","Identifizierung von Anmeldeinformationen in git für S3-Risiken","Benachrichtigung von Benutzern über mittlere Risiken mit empfohlenen Lösungen"],"pt":["Automatizar auditorias de segurança para OpenClaw e infraestrutura de sistema","Identificar credenciais no git para riscos de nível S3","Alertar usuários para riscos de nível médio com soluções recomendadas"],"ru":["Автоматизировать аудит безопасности для OpenClaw и инфраструктуры системы","Определять учетные данные в git для рисков уровня S3","Оповещать пользователей о рисках среднего уровня с рекомендуемыми исправлениями"],"ar":["تأتمتة فحص الأمن للبنية التحتية مفتوحة الطبعة والنظام","تحديد بيانات الاعتماد في جيت للمخاطر من المستوى S3","إعلام المستخدمين بالمخاطر المتوسطة مع إصلاحات مقترحة"]},"limitations":{"en":["Requires Pokee AI''s Deep Research API access","Specific to OpenClaw and system infrastructure security"],"zh":["需要Pokee AI的Deep Research API访问","仅限于OpenClaw和系统基础设施的安全"],"ja":["Pokee AIのDeep Research APIへのアクセスが必要","OpenClawとシステムインフラストラクチャのセキュリティに限定される"],"ko":["Pokee AI의 Deep Research API 액세스가 필요합니다.","OpenClaw 및 시스템 인프라의 보안에만 해당합니다."],"es":["Requiere acceso a la API de investigación profunda de Pokee AI","Específico para la seguridad de OpenClaw y la infraestructura del sistema"],"fr":["Nécessite l''