INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Niraven/pokee-deep-research-skill/tinman', 'tinman', 'Niraven', 'pokee-deep-research-skill', 'community', 'tinman Niraven pokee-deep-research-skill community Tinman is an OpenClaw skill for deep research using Pokee AI''s Deep Research API, providing security auditing and hardening for system infrastructure. It benefits developers and security professionals. Tinman 是一个 OpenClaw 技能，用于深度研究和安全审计。它提供了多级安全检查和加固功能 Tinman は OpenClaw スキルで、深度研究とセキュリティ監査に使用されます。多段階のセキュリティチェックと強化機能を提供します Tinman 은 OpenClaw 스킬로 심층 연구 및 보안 감사를 위해 사용됩니다. 다단계 보안 점검 및 강화 기능을 제공합니다 Tinman es una habilidad de OpenClaw para investigación profunda utilizando la API de investigación profunda de Pokee AI, enfocada en auditoría y endurecimiento de la seguridad Tinman est une compétence OpenClaw pour la recherche approfondie utilisant l''API de recherche approfondie de Pokee AI, axée sur l''audit et le durcissement de la sécurité Tinman ist eine OpenClaw-Fähigkeit für tiefe Recherche unter Verwendung der Deep Research-API von Pokee AI, fokussiert auf Sicherheitsaudit und -härtung O Tinman é uma habilidade do OpenClaw para pesquisa aprofundada usando a API de Pesquisa Aprofundada da Pokee AI, fornecendo segurança avançada e hardening de infraestrutura. ИИ Агент Tinman - это навык OpenClaw для глубокого исследования с помощью API глубокого исследования от Pokee AI, обеспечивающий продвинутую безопасность и укрепление инфраструктуры. وكيل Tinman هو مهارة مفتاح OpenClaw للبحث المتقدم باستخدام واجهة برمجة التطبيقات البحث المتقدم من Pokee AI، مما يوفر أمانًا متقدمًا وتعزيزًا للبنية التحتية. how to use tinman tinman setup guide tinman alternative tinman vs OpenClaw tinman install what is tinman Pokee AI Deep Research API OpenClaw security auditing tinman security hardening Tinman OpenClaw 安全审计 深度研究 API 集成 多级安全检查 AIエージェント 安全加固 Performs security checks for Credentials in git with risk level S3 Provides security levels S0 to S4 for incident response and management Utilizes Pokee AI''s Deep Research API for in-depth analysis Supports .gitignore configuration for secure credential management Offers alert and notification systems for security breaches Tinman is a security auditing and hardening skill for OpenClaw and system infrastructure, utilizing Pokee AI''s Deep Research API.');
